window.AULAS = window.AULAS || {};
window.AULAS["farma-gilmar-01"] = {"subtitulo": "Introdução: vocabulário, formas farmacêuticas, áreas e nomenclatura", "pdf": "pdf/gilmar/aula-01.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 1 · Fármaco (Prof. Dr. Gilmar S. Erzinger)", "Brunton e Knollmann (Goodman & Gilman); Katzung (Farmacologia Básica e Clínica); OMS (Guide to Good Prescribing), citados nos slides", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página.", "Slides e transcrição da aula, Prof. Dr. Gilmar S. Erzinger (resumo completo)"], "tabela": {"titulo": "Radicais da DCB: o nome revela a classe (slide 9)", "colunas": ["Radical", "Classe", "Exemplos"], "linhas": [["-olol", "Betabloqueadores", "propranolol, atenolol, metoprolol"], ["-pril", "Inibidores da ECA", "captopril, enalapril, ramipril"], ["-sartana", "Bloqueadores do receptor AT1", "losartana, valsartana, olmesartana"], ["-statina", "Inibidores da HMG-CoA redutase", "sinvastatina, atorvastatina, rosuvastatina"], ["-prazol", "Inibidores da bomba de prótons", "omeprazol, pantoprazol, esomeprazol"], ["-azepam / -azolam", "Benzodiazepínicos", "diazepam, clonazepam, midazolam"], ["-gliflozina", "Inibidores do SGLT2", "dapagliflozina, empagliflozina"], ["-mabe", "Anticorpos monoclonais", "rituximabe, adalimumabe, pembrolizumabe"]]}, "resumo": [{"titulo": "1. Vocabulário básico: fármaco, medicamento, droga, remédio e placebo", "pontos": [{"t": "Fármaco", "sub": ["Fármaco é uma substância química de estrutura definida, com efeito farmacológico. É o princípio ativo, a molécula responsável pelo efeito. Exemplo: amoxicilina. Quando se fala de fármaco, fala-se da molécula, sem o veículo que a transporta até o paciente.", "Essa distinção é a base de toda a disciplina: o efeito vem do fármaco, mas o que chega ao paciente é um medicamento, com excipientes e uma forma farmacêutica."]}, {"t": "Medicamento", "sub": ["Medicamento é o produto farmacêutico tecnicamente elaborado, com finalidade profilática, curativa, paliativa ou diagnóstica. A fórmula é: fármaco + excipientes + forma farmacêutica.", "Excipientes são substâncias sem efeito terapêutico próprio, que dão forma, estabilidade, sabor ou capacidade de liberação ao fármaco. Eles não são inertes do ponto de vista clínico: podem causar reações alérgicas, e a troca de excipiente pode alterar a absorção."]}, {"t": "Droga", "sub": ["Droga é um termo amplo: qualquer substância que altera funções do organismo. No uso leigo, a palavra fica associada a substâncias de abuso. Na farmacologia, a palavra não tem essa carga; a discussão é sobre a relação entre o efeito e a dose."]}, {"t": "Remédio", "sub": ["Remédio é tudo o que alivia ou cura, incluindo medidas não farmacológicas, como repouso, fisioterapia e dieta. Por isso o termo é mais amplo que medicamento e não implica comprovação científica."]}, {"t": "Placebo", "sub": ["Placebo é uma preparação sem ativo farmacológico específico. O efeito placebo é real: a melhora pode vir da expectativa do paciente ou do contexto do tratamento. Por isso o placebo interfere nos ensaios clínicos, e os estudos precisam de grupo controle e de duplo-cego para separar o efeito do fármaco do efeito psicológico.", "O efeito nocebo é o inverso: o paciente piora porque espera piorar, mesmo com placebo. Ele também precisa ser controlado no desenho do estudo."]}]}, {"titulo": "2. Formas farmacêuticas: como o fármaco chega ao corpo", "pontos": [{"t": "Por que existem formas farmacêuticas", "sub": ["A forma farmacêutica é a apresentação física do medicamento. Ela facilita a administração, garante a segurança e otimiza o efeito do princípio ativo no organismo. Duas formas com o mesmo fármaco podem ter absorção, início de ação e duração muito diferentes."]}, {"t": "Formas sólidas", "sub": ["Proporcionam precisão de dose, estabilidade e facilidade de transporte.", "Comprimidos são pós comprimidos por pressão. Podem ser efervescentes, sublinguais ou revestidos.", "Cápsulas são invólucros, geralmente de gelatina, que encerram o princípio ativo sólido ou líquido.", "Drágeas são comprimidos com revestimento de açúcar e outras substâncias, para mascarar sabor ou proteger o ativo no estômago.", "Supositórios e óvulos são formas sólidas que derretem à temperatura corporal, para uso retal ou vaginal. São úteis quando o paciente vomita ou não pode engolir."]}, {"t": "Formas semissólidas", "sub": ["São de consistência intermediária e são aplicadas na pele ou nas mucosas, para efeito local ou regional.", "Pomadas são formulações mais gordurosas e oclusivas. Cremes são emulsões de óleo e água, de fácil espalhabilidade e menos oleosas. Géis são preparações à base de água, com agentes que dão consistência firme."]}, {"t": "Formas líquidas", "sub": ["São ideais para rápida absorção e para pacientes com dificuldade de deglutição, como crianças e idosos.", "Soluções são misturas homogêneas, com o fármaco totalmente dissolvido. Suspensões têm partículas sólidas dispersas e exigem agitação antes do uso. Xaropes e elixires são preparações aquosas ou hidroalcoólicas com alta concentração de açúcar ou adoçantes."]}, {"t": "Formas gasosas", "sub": ["Administradas por inalação ou via nasal, atingem diretamente as vias respiratórias. Aerossóis e sprays dispersam o medicamento em gotículas ou partículas no ar. Inalantes são gases ou vapores direcionados aos pulmões. O efeito é rápido e o fármaco evita a primeira passagem hepática."]}]}, {"titulo": "3. As grandes áreas da farmacologia", "pontos": [{"t": "Farmacocinética: o que o organismo faz com o fármaco", "sub": ["É o estudo de absorção, distribuição, metabolismo e excreção, o chamado ADME. Responde à pergunta: quanto do fármaco chega ao local de ação, por quanto tempo, e como sai do corpo?"]}, {"t": "Farmacodinâmica: o que o fármaco faz com o organismo", "sub": ["Estuda os alvos moleculares, os mecanismos de ação e a relação entre dose e efeito. É a parte onde entram receptores, agonistas e antagonistas."]}, {"t": "Farmacoterapia: uso clínico", "sub": ["Trata da escolha do fármaco, da dose, da via, da duração e do monitoramento do tratamento."]}, {"t": "Farmacovigilância", "sub": ["Detecta, avalia e previne reações adversas depois que o medicamento é comercializado. Os ensaios clínicos não conseguem detectar eventos raros; a farmacovigilância faz isso no uso real.", "Áreas transversais: toxicologia, farmacogenética e farmacoepidemiologia."]}]}, {"titulo": "4. Nomenclatura: o nome revela a classe", "pontos": [{"t": "Denominação Comum Brasileira (DCB)", "sub": ["A DCB segue a lógica dos radicais da DCI da OMS. O sufixo do nome indica a classe do fármaco. Saber os radicais permite identificar a classe de um medicamento que você nunca viu antes."]}, {"t": "Radicais principais", "sub": ["-olol: betabloqueadores (propranolol, atenolol, metoprolol).", "-pril: inibidores da enzima conversora de angiotensina, ECA (captopril, enalapril, ramipril).", "-sartana: bloqueadores do receptor AT1 da angiotensina II (losartana, valsartana, olmesartana).", "-statina: inibidores da HMG-CoA redutase, usados para reduzir colesterol (sinvastatina, atorvastatina, rosuvastatina).", "-prazol: inibidores da bomba de prótons, que reduzem a secreção ácida gástrica (omeprazol, pantoprazol, esomeprazol).", "-azepam e -azolam: benzodiazepínicos (diazepam, clonazepam, midazolam).", "-gliflozina: inibidores do SGLT2, que aumentam a excreção de glicose pela urina (dapagliflozina, empagliflozina).", "-mabe: anticorpos monoclonais (rituximabe, adalimumabe, pembrolizumabe).", "Atenção: nem todo nome parecido indica a mesma classe. Confirme sempre."]}]}, {"titulo": "5. Como descrever um medicamento: a estrutura que vira esquema mental", "pontos": [{"t": "Os cinco blocos", "sub": ["1. Classe e mecanismo: qual é o alvo molecular e qual é o efeito fisiológico resultante.", "2. Farmacocinética: via, biodisponibilidade, meia-vida, metabolismo (CYP) e eliminação renal.", "3. Usos clínicos: indicações principais e a indicação de escolha nas diretrizes.", "4. Segurança: reações adversas frequentes e graves, contraindicações e cuidados na gestação.", "5. Interações e monitoramento: o que acompanhar, como níveis séricos, exames e sinais clínicos.", "Use sempre a mesma estrutura. Ela serve para a prova e para a clínica."]}]}, {"titulo": "6. Fontes confiáveis e raciocínio terapêutico", "pontos": [{"t": "Onde estudar e buscar dados", "sub": ["Livros-texto: Goodman & Gilman, Katzung (Farmacologia Básica e Clínica), Rang & Dale e Golan.", "Bulário e registros: Bulário Eletrônico da ANVISA, RENAME e Formulário Terapêutico Nacional.", "Diretrizes: PCDT do Ministério da Saúde e CONITEC, e diretrizes de sociedades médicas.", "Bases clínicas: UpToDate, Micromedex e DynaMed, para dose, ajuste renal e interações na prática.", "Literatura primária: ensaios clínicos e revisões sistemáticas (PubMed, Cochrane).", "Evite: materiais sem autoria, propaganda de indústria como fonte principal e redes sociais sem referência."]}, {"t": "Do livro para o paciente: raciocínio terapêutico (OMS)", "sub": ["1. Definir o problema: diagnóstico e fisiopatologia.", "2. Objetivo terapêutico: o que se quer alcançar e como medir.", "3. Escolher o tratamento: eficácia, segurança, conveniência e custo.", "4. Prescrever: dose, via, frequência e duração.", "5. Informar o paciente: uso correto, efeitos esperados e sinais de alerta.", "6. Monitorar: resposta, reações adversas e decisão de manter ou parar."]}]}, {"titulo": "7. Boas práticas de estudo e caso clínico", "pontos": [{"t": "Erros comuns e como evitá-los", "sub": ["Evite decorar listas sem entender o mecanismo, estudar só nomes comerciais, deixar tudo para a semana da prova e reler resumos no lugar de resolver questões.", "Prefira: mecanismo → efeitos → reações adversas → interações; sempre o nome genérico (DCB); revisões curtas e espaçadas; questões e casos clínicos desde o início; e conectar cada classe a uma doença-alvo."]}, {"t": "Caso clínico de aplicação (slide 14)", "sub": ["Mulher de 58 anos, hipertensa e diabética, em uso de enalapril 20 mg a cada 12 horas, com tosse seca persistente há 2 meses, sem febre, e radiografia de tórax normal.", "Pelo radical '-pril', a classe é inibidor da ECA. A tosse é causada pelo acúmulo de bradicinina, porque a ECA também degrada a bradicinina. Uma alternativa que mantém o benefício renal e cardiovascular e não causa tosse é um bloqueador do receptor AT1 (-sartana). Os exames a monitorar são creatinina, potássio e pressão arterial, porque esses fármacos podem elevar o potássio e reduzir a função renal."]}]}], "glossario": [{"termo": "Fármaco", "tecnica": "Vocabulário", "definicao": "Substância química de estrutura definida, com efeito farmacológico; o princípio ativo.", "slide": 2}, {"termo": "Medicamento", "tecnica": "Vocabulário", "definicao": "Produto farmacêutico elaborado, com fármaco, excipientes e forma farmacêutica.", "slide": 2}, {"termo": "Nocebo", "tecnica": "Vocabulário", "definicao": "Efeito negativo que ocorre sem ação do princípio ativo, real e que interfere nos ensaios.", "slide": 2}, {"termo": "Drágea", "tecnica": "Forma sólida", "definicao": "Comprimido com revestimento de açúcar e outras substâncias, para mascarar sabor ou proteger o ativo no estômago.", "slide": 4}, {"termo": "DCB", "tecnica": "Nomenclatura", "definicao": "Denominação Comum Brasileira, baseada nos radicais da DCI/OMS.", "slide": 9}, {"termo": "Farmacovigilância", "tecnica": "Área da farmacologia", "definicao": "Detecção, avaliação e prevenção de reações adversas após a comercialização.", "slide": 8}, {"termo": "Droga", "tecnica": "Vocabulário", "definicao": "Termo amplo para qualquer substância que altera funções do organismo. No uso leigo, associa-se a substâncias de abuso.", "slide": 2}, {"termo": "Remédio", "tecnica": "Vocabulário", "definicao": "Tudo o que alivia ou cura, inclusive medidas não farmacológicas, como repouso, fisioterapia e dieta.", "slide": 2}, {"termo": "Excipiente", "tecnica": "Vocabulário", "definicao": "Componente do medicamento que não é o princípio ativo. Junto com o fármaco e a forma farmacêutica, compõe o medicamento.", "slide": 2}, {"termo": "Comprimido efervescente, sublingual e revestido", "tecnica": "Forma sólida", "definicao": "Variações do comprimido: efervescente se dissolve em água; sublingual é absorvido sob a língua; revestido tem camada externa.", "slide": 4}, {"termo": "Cápsula", "tecnica": "Forma sólida", "definicao": "Invólucro, geralmente de gelatina, que encerra o princípio ativo sólido ou líquido.", "slide": 4}, {"termo": "Supositório e óvulo", "tecnica": "Forma sólida", "definicao": "Formas que derretem à temperatura corporal, para uso retal (supositório) ou vaginal (óvulo).", "slide": 4}, {"termo": "Pomada", "tecnica": "Forma semissólida", "definicao": "Formulação mais gordurosa e oclusiva, de uso na pele ou em mucosas.", "slide": 5}, {"termo": "Creme", "tecnica": "Forma semissólida", "definicao": "Emulsão de óleo e água, de fácil espalhamento e menos oleosa que a pomada.", "slide": 5}, {"termo": "Gel", "tecnica": "Forma semissólida", "definicao": "Preparação de base aquosa, com agente que confere consistência firme.", "slide": 5}, {"termo": "Solução", "tecnica": "Forma líquida", "definicao": "Mistura homogênea em que o fármaco está totalmente dissolvido.", "slide": 6}, {"termo": "Suspensão", "tecnica": "Forma líquida", "definicao": "Líquido com partículas sólidas dispersas. Exige agitação antes do uso.", "slide": 6}, {"termo": "Xarope e elixir", "tecnica": "Forma líquida", "definicao": "Preparações de alta concentração de açúcar ou adoçantes, aquosas ou hidroalcoólicas.", "slide": 6}, {"termo": "Aerossol e spray", "tecnica": "Forma gasosa", "definicao": "Sistema que dispersa o medicamento em gotículas ou partículas no ar.", "slide": 7}, {"termo": "Inalante", "tecnica": "Forma gasosa", "definicao": "Gás ou vapor direcionado aos pulmões.", "slide": 7}, {"termo": "Farmacocinética (ADME)", "tecnica": "Área da farmacologia", "definicao": "Descreve o que o organismo faz com o fármaco: absorção, distribuição, metabolismo e excreção.", "slide": 8}, {"termo": "Farmacodinâmica", "tecnica": "Área da farmacologia", "definicao": "Descreve o que o fármaco faz com o organismo: alvos, mecanismos de ação e relação dose-efeito.", "slide": 8}, {"termo": "Farmacoterapia", "tecnica": "Área da farmacologia", "definicao": "Uso clínico do fármaco: escolha, dose, via, duração e monitoramento.", "slide": 8}, {"termo": "Toxicologia, farmacogenética e farmacoepidemiologia", "tecnica": "Áreas transversais", "definicao": "Áreas que atravessam as outras: efeitos tóxicos, genética da resposta e uso de medicamentos em populações.", "slide": 8}, {"termo": "Sufixo -olol", "tecnica": "Radical", "definicao": "Betabloqueadores. Ex.: propranolol, atenolol, metoprolol.", "slide": 9}, {"termo": "Sufixo -pril", "tecnica": "Radical", "definicao": "Inibidores da enzima conversora de angiotensina (ECA). Ex.: captopril, enalapril.", "slide": 9}, {"termo": "Sufixo -sartana", "tecnica": "Radical", "definicao": "Bloqueadores do receptor AT1 da angiotensina II. Ex.: losartana, valsartana.", "slide": 9}, {"termo": "Sufixo -statina", "tecnica": "Radical", "definicao": "Inibidores da HMG-CoA redutase, usados para reduzir o colesterol. Ex.: sinvastatina.", "slide": 9}, {"termo": "Sufixo -prazol", "tecnica": "Radical", "definicao": "Inibidores da bomba de prótons (H⁺/K⁺ ATPase). Ex.: omeprazol.", "slide": 9}, {"termo": "Sufixo -azepam e -azolam", "tecnica": "Radical", "definicao": "Benzodiazepínicos, que potencializam o GABA. Ex.: diazepam, midazolam.", "slide": 9}, {"termo": "Sufixo -gliflozina", "tecnica": "Radical", "definicao": "Inibidores do cotransportador SGLT2, que aumentam a glicosúria. Ex.: dapagliflozina.", "slide": 9}, {"termo": "Sufixo -mabe", "tecnica": "Radical", "definicao": "Anticorpos monoclonais. Ex.: rituximabe, adalimumabe.", "slide": 9}, {"termo": "Goodman & Gilman", "tecnica": "Fonte", "definicao": "Principal livro-texto de farmacologia, citado como referência da aula.", "slide": 11}, {"termo": "Katzung (Farmacologia Básica e Clínica)", "tecnica": "Fonte", "definicao": "Livro-texto de farmacologia clínica, citado como referência.", "slide": 11}, {"termo": "Rang & Dale", "tecnica": "Fonte", "definicao": "Livro-texto de farmacologia, citado como referência.", "slide": 11}, {"termo": "RENAME", "tecnica": "Fonte", "definicao": "Relação Nacional de Medicamentos Essenciais, do Ministério da Saúde.", "slide": 11}, {"termo": "Bulário Eletrônico da Anvisa", "tecnica": "Fonte", "definicao": "Base oficial de bulas para o profissional de saúde.", "slide": 11}, {"termo": "PCDT e CONITEC", "tecnica": "Fonte", "definicao": "Protocolos Clínicos e Diretrizes Terapêuticas do Ministério da Saúde, com avaliação da CONITEC.", "slide": 11}, {"termo": "Guia para a Boa Prescrição (OMS)", "tecnica": "Raciocínio terapêutico", "definicao": "Guia com seis passos: definir o problema, objetivo, escolher tratamento, prescrever, informar e monitorar.", "slide": 12}, {"termo": "Dunlosky et al. (2013)", "tecnica": "Método de estudo", "definicao": "Revisão sobre técnicas de aprendizagem com evidência, como revisão espaçada e prática de questões.", "slide": 15}, {"termo": "Bradicinina", "tecnica": "Mecanismo", "definicao": "Peptídeo vasoativo que se acumula quando a ECA é inibida, e causa a tosse dos inibidores da ECA.", "slide": 14}], "caso": {"titulo": "Caso: tosse após início de enalapril", "perfil": "Radical do nome, mecanismo da tosse e classe alternativa.", "etapas": [{"titulo": "Etapa 1: classe e mecanismo", "texto": "Mulher de 58 anos, hipertensa e diabética, em uso de enalapril 20 mg a cada 12 h. Refere tosse seca persistente há dois meses, sem febre; a radiografia de tórax é normal.", "perguntas": [{"pergunta": "Qual é a classe do fármaco, pelo radical do nome?", "alts": ["Inibidor da enzima conversora de angiotensina (ECA)", "Bloqueador do receptor AT1 da angiotensina", "Betabloqueador não seletivo", "Inibidor da HMG-CoA redutase", "Inibidor da bomba de prótons"], "erradas": ["Bloqueador AT1 tem radical -sartana, como losartana.", "Betabloqueadores têm radical -olol.", "Estatinas têm radical -statina.", "Inibidores da bomba de prótons têm radical -prazol."], "justificativa": "O radical -pril identifica os inibidores da ECA, como captopril, enalapril e ramipril (slide 9)."}]}, {"titulo": "Etapa 2: alternativa sem tosse", "texto": "A tosse é atribuída ao acúmulo de bradicinina. O médico quer manter o benefício renal e cardiovascular, sem a tosse.", "perguntas": [{"pergunta": "Qual classe alternativa mantém o benefício e não causa tosse, segundo a aula?", "alts": ["Bloqueador do receptor AT1, de radical -sartana", "Betabloqueador de radical -olol, sem efeito renal", "Inibidor da bomba de prótons, de radical -prazol", "Benzodiazepínico, de radical -azepam", "Inibidor do SGLT2, de radical -gliflozina"], "erradas": ["Betabloqueadores não são alternativa renal a IECA neste caso.", "Inibidor da bomba de prótons não trata a pressão arterial.", "Benzodiazepínicos não têm efeito renal ou anti-hipertensivo.", "Inibidores do SGLT2 não são a alternativa citada na aula."], "justificativa": "Bloqueadores AT1 (-sartana) atuam na mesma via sem acumular bradicinina, e a aula cita a tosse como efeito da classe anterior (slide 14)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Paciente J.M., 74 anos, com disfagia após AVC, recebe comprimido revestido de liberação prolongada de um fármaco. A equipe quer triturar o comprimido para dar por sonda. Qual é a consequência mais provável e a alternativa correta?", "alternativas": ["Nenhuma alteração, porque o revestimento é inerte e serve apenas para proteger o comprimido da umidade do ambiente", "Aumento da meia-vida, porque a metade do comprimido é absorvida mais lentamente pelo intestino delgado do paciente", "Altera a liberação e a biodisponibilidade; trocar por forma líquida", "Redução do volume de distribuição, porque o fármaco se concentra no plasma e não nos tecidos periféricos do idoso", "Aumento da ligação às proteínas plasmáticas, o que torna o fármaco mais ativo e mais tóxico para o paciente idoso"], "gabarito": "C", "justificativa": "O revestimento de liberação controlada dosa a liberação. Triturar altera a biodisponibilidade e pode causar toxicidade ou perda de efeito. Em disfagia, usa-se forma líquida ou de liberação imediata (resumo: Formas farmacêuticas).", "tecnica": "Forma farmacêutica e absorção", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um farmacêutico afirma que, no caso do paciente que usa amoxicilina em cápsula, o 'fármaco' é a cápsula. Um colega discorda. Qual é a classificação correta do componente que causa o efeito antimicrobiano?", "alternativas": ["O fármaco é a cápsula, porque é o que se administra; a amoxicilina é apenas um excipiente de enchimento", "O fármaco é o excipiente da cápsula, que dissolve a amoxicilina e permite sua absorção no estômago", "O fármaco é a gelatina, que tem efeito antimicrobiano próprio e reforça a ação da amoxicilina", "O fármaco é a amoxicilina, o princípio ativo; a cápsula é a forma farmacêutica do medicamento", "O fármaco é o placebo presente na cápsula, que aumenta a adesão do paciente ao tratamento antibiótico"], "gabarito": "D", "justificativa": "Fármaco é a substância química de estrutura definida com efeito farmacológico, o princípio ativo. Medicamento é o conjunto fármaco + excipientes + forma farmacêutica (resumo: Vocabulário básico).", "tecnica": "Conceito: fármaco × medicamento", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Em um ensaio de analgésico, o grupo placebo relata melhora de dor de 40%. Um pesquisador conclui que o placebo não tem efeito. Qual é a crítica mais precisa?", "alternativas": ["O placebo não tem efeito algum, e a melhora relatada reflete apenas o viés do pesquisador na coleta de dados", "O placebo sempre piora o quadro, por efeito nocebo, e a melhora observada indica erro de randomização do estudo", "O efeito placebo é real e interfere nos ensaios; a diferença entre o fármaco e o placebo é que deve ser medida", "A melhora de 40% prova que o analgésico é inútil, porque o placebo tem a mesma eficácia do fármaco ativo", "O placebo só funciona em crianças e idosos, e a amostra do estudo não incluiu pacientes dessas faixas etárias"], "gabarito": "C", "justificativa": "O efeito placebo é real e interfere nos ensaios clínicos. Por isso o estudo compara o fármaco com o placebo, em duplo-cego, para separar o efeito farmacológico do psicológico (resumo: Vocabulário básico).", "tecnica": "Placebo e nocebo", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Paciente com dor lombar recebe fisioterapia, repouso e um anti-inflamatório. Um professor afirma que a fisioterapia é um 'remédio' e o anti-inflamatório é um 'medicamento'. Qual é a análise mais precisa?", "alternativas": ["A fisioterapia é medicamento, porque altera funções do organismo; o anti-inflamatório é apenas um fármaco sem forma farmacêutica", "Ambos são remédios; só o anti-inflamatório é medicamento registrado", "Ambos são drogas, porque o termo droga inclui todo tratamento, e remédio é sinônimo de placebo no vocabulário técnico", "A fisioterapia é placebo, e o anti-inflamatório é droga, porque a dose ultrapassa o limite de segurança", "Ambos são medicamentos, porque qualquer intervenção que alivia a dor é produto farmacêutico registrado na bula"], "gabarito": "B", "justificativa": "Remédio é tudo o que alivia ou cura, inclusive medidas não farmacológicas. Medicamento é o produto farmacêutico registrado, com fármaco, excipientes e forma (resumo: Vocabulário básico).", "tecnica": "Droga × remédio × medicamento", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Criança de 3 anos, com vômitos incoercíveis, precisa de um fármaco antiemético com início de ação rápido e sem passar pelo estômago. Qual forma farmacêutica é a mais adequada, e por quê?", "alternativas": ["Drágea revestida, que protege o ativo no estômago e libera o fármaco somente no intestino delgado", "Comprimido efervescente, que se dissolve na água e exige deglutição para atingir a circulação sistêmica", "Xarope com alta concentração de açúcar, que é absorvido pelo estômago e acelera o esvaziamento gástrico", "Supositório, que derrete à temperatura corporal na via retal e pode evitar parte da primeira passagem", "Cápsula de gelatina de liberação prolongada, que impede a absorção até o final do período de vômitos"], "gabarito": "D", "justificativa": "Supositórios são formas sólidas que derretem à temperatura corporal e são úteis quando o paciente vomita ou não consegue engolir. Evitam parcialmente a primeira passagem hepática (resumo: Formas farmacêuticas).", "tecnica": "Formas farmacêuticas e via", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente recebe prescrição de 'losartana' e outro de 'captopril' para hipertensão. Um estudante diz que as duas drogas têm o mesmo mecanismo. Qual é a correção mais precisa?", "alternativas": ["-sartana bloqueia o AT1; -pril inibe a ECA; ambos atuam na angiotensina II", "Ambas inibem a enzima conversora, porque todo fármaco anti-hipertensivo com terminação em -a age sobre a ECA", "Losartana é betabloqueador e captopril é bloqueador de canal de cálcio, porque ambos terminam em -ol e -pril", "Ambas são inibidoras da bomba de prótons, porque o radical -pril e o radical -sartana indicam mesma classe", "Losartana inibe a HMG-CoA redutase e captopril ativa o receptor AT1, pela regra de nomenclatura da DCB"], "gabarito": "A", "justificativa": "-sartana bloqueia o receptor AT1 da angiotensina II. -pril inibe a ECA. Ambas reduzem o efeito da angiotensina II, mas em alvos diferentes (resumo: Nomenclatura, DCB).", "tecnica": "Radicais e classe", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Mulher de 58 anos, hipertensa e diabética, em uso de enalapril há 6 meses, desenvolve tosse seca persistente. A radiografia de tórax é normal. Qual é o mecanismo da tosse e a conduta mais coerente?", "alternativas": ["Aumento da angiotensina II, que estimula o receptor de histamina H1 nas vias aéreas e causa tosse seca", "Inibição da COX-2 pelo enalapril, o que aumenta a produção de leucotrienos broncoconstritores no pulmão", "Acúmulo de bradicinina; trocar por -sartana mantém o benefício renal", "Ativação do receptor β2 pelo enalapril, o que causa broncoespasmo e tosse seca de caráter crônico", "Depleção de potássio pelo enalapril, o que causa tosse por hipocalemia e reduz a condução nervosa vagal"], "gabarito": "C", "justificativa": "A ECA degrada a bradicinina. Com a inibição, ela se acumula e causa tosse. Trocar por um -sartana mantém o benefício e não causa tosse (resumo: Nomenclatura e caso clínico).", "tecnica": "Raciocínio sobre enalapril e tosse", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Após iniciar um inibidor da ECA e um diurético poupador de potássio em paciente idoso com doença renal, a creatinina sobe 40% e o potássio sérico é de 6,2 mEq/L. Qual é a conduta mais coerente com a farmacologia de monitoramento?", "alternativas": ["Reavaliar a associação, suspender o poupador de potássio e monitorar creatinina e potássio em curto prazo", "Aumentar a dose do inibidor da ECA, porque a elevação de creatinina indica que o fármaco está agindo corretamente", "Iniciar suplemento de potássio oral, porque a hipercalemia com inibidor da ECA é rara e sempre benigna", "Manter a associação sem alteração, porque creatinina e potássio não são parâmetros de segurança desses fármacos", "Trocar o inibidor da ECA por um betabloqueador, porque betabloqueadores não alteram creatinina nem potássio"], "gabarito": "A", "justificativa": "Inibidores da ECA e poupadores de potássio elevam o potássio, e a função renal pode cair. É necessário monitorar creatinina e potássio e reavaliar a associação (resumo: Caso clínico, monitoramento).", "tecnica": "Monitoramento de inibidores da ECA", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um fármaco é descrito como agonista de receptor acoplado a proteína G do tipo Gs, que aumenta o AMPc. Qual é o efeito esperado em um tecido que responde a AMPc, como o miocárdio?", "alternativas": ["Diminuição da contratilidade, porque o AMPc ativa a fosfolipase C e reduz o cálcio intracelular", "Aumento da contratilidade e da frequência cardíaca, porque o AMPc ativa a PKA e a entrada de cálcio", "Constrição dos vasos coronários, porque o AMPc ativa a via de IP₃ e libera cálcio do retículo", "Aumento da secreção de ácido gástrico, porque o AMPc inibe a adenilil ciclase na célula parietal", "Relaxamento do músculo liso brônquico apenas, sem efeito cardíaco, porque o AMPc age só nos pulmões"], "gabarito": "B", "justificativa": "Gs ativa a adenilil ciclase e aumenta o AMPc, que ativa a PKA. No miocárdio, isso aumenta a contratilidade e a frequência (resumo: Farmacodinâmica, áreas da farmacologia).", "tecnica": "Farmacodinâmica e alvo", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um medicamento aprovado em ensaios com 3.000 pacientes apresenta, após dois anos de uso em milhões de pessoas, um efeito adverso raro e grave. Por que o ensaio não detectou esse evento, e qual área cuida disso?", "alternativas": ["Os ensaios usaram placebo e o evento só ocorre com placebo, por isso não foi visto nos participantes do estudo", "O evento é causado pela formulação e não pelo fármaco, por isso o ensaio clínico não tem poder de detectá-lo", "A farmacocinética do fármaco mudou após a aprovação, e a toxicologia clássica não avalia esse tipo de mudança", "Número insuficiente para eventos raros; a farmacovigilância detecta após comercialização", "O evento é transitório e desaparece após seis meses, por isso não aparece em estudos de longo prazo"], "gabarito": "D", "justificativa": "Farmacovigilância detecta, avalia e previne reações adversas depois da comercialização. Eventos raros exigem grandes populações, que só aparecem no uso real (resumo: Áreas da farmacologia).", "tecnica": "Farmacovigilância", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um fármaco é absorvido no intestino, passa pelo fígado antes de chegar à circulação sistêmica e é eliminado pelo rim. Qual é a sequência de etapas que descreve esse percurso?", "alternativas": ["Distribuição, absorção, excreção hepática e metabolismo renal, nessa ordem, pela circulação portal", "Metabolismo, excreção, absorção e distribuição, porque o fígado atua antes da absorção intestinal", "Excreção, distribuição, metabolismo e absorção, porque o rim atua como primeiro órgão de contato", "Liberação, excreção, absorção e metabolismo, porque a forma farmacêutica é eliminada antes do intestino", "Absorção, primeira passagem hepática, distribuição, metabolismo hepático e excreção renal"], "gabarito": "E", "justificativa": "ADME: absorção, distribuição, metabolismo e excreção. A primeira passagem hepática ocorre depois da absorção intestinal e antes da circulação sistêmica (resumo: Áreas da farmacologia, farmacocinética).", "tecnica": "Farmacocinética: ADME", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Paciente com alergia a um corante usado como excipiente em comprimido de um fármaco de uso crônico tem urticária após o início do tratamento. Qual é a explicação farmacológica e a conduta?", "alternativas": ["O fármaco é alérgico por si só, e a troca de excipiente não altera a resposta, sendo necessário suspender o princípio ativo", "O excipiente pode causar reação de hipersensibilidade; troca por outra forma sem o corante, mantendo o princípio ativo", "O corante é o princípio ativo do medicamento, e a alergia indica que o fármaco está em dose alta demais", "Excipientes não têm efeito algum no organismo, e a urticária é causada por contaminação do ambiente de uso", "A urticária é efeito placebo, porque o corante não interage com a pele e o paciente imagina a reação"], "gabarito": "B", "justificativa": "Excipientes não são inertes do ponto de vista clínico. Podem causar hipersensibilidade. A conduta é trocar a forma ou o excipiente, mantendo o fármaco (resumo: Vocabulário e medicamento).", "tecnica": "Excipientes", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Paciente com angina aguda recebe um fármaco por via sublingual, que se absorve rapidamente. Qual é a vantagem farmacocinética dessa via em relação à oral?", "alternativas": ["Evita parte da primeira passagem; início rápido e biodisponibilidade alta", "Aumenta a meia-vida do fármaco, porque a absorção sublingual é mais lenta e prolonga o efeito do fármaco", "Diminui a biodisponibilidade, porque a absorção sublingual é sempre incompleta e depende do pH da saliva", "Aumenta o volume de distribuição, porque o fármaco se concentra no tecido gengival e não no plasma", "Elimina a necessidade de monitoramento, porque a via sublingual não produz metabólitos ativos"], "gabarito": "A", "justificativa": "A via sublingual evita a primeira passagem hepática, por isso a biodisponibilidade é alta e o início é rápido. É a via usada na angina aguda (resumo: Formas farmacêuticas, primeira passagem).", "tecnica": "Forma sublingual e primeira passagem", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Ao definir o tratamento de um paciente com hipertensão, o médico decide entre dois fármacos de eficácia equivalente. Um tem custo muito maior e exige três tomadas por dia; o outro é uma vez ao dia. Qual critério do raciocínio terapêutico orienta a escolha?", "alternativas": ["Apenas a eficácia, porque o custo e a conveniência não entram no raciocínio terapêutico em nenhuma etapa", "Apenas a meia-vida, porque o médico deve sempre escolher o fármaco de maior duração, independente do paciente", "Apenas a via de administração, porque fármacos orais são sempre preferidos a fármacos injetáveis", "Apenas a interação com outros fármacos, porque a escolha do tratamento depende exclusivamente disso", "Conveniência e custo, junto com eficácia e segurança, na escolha"], "gabarito": "E", "justificativa": "A etapa 'escolher o tratamento' combina eficácia, segurança, conveniência e custo. Em igualdade de eficácia, a conveniência e o custo orientam a escolha (resumo: Raciocínio terapêutico da OMS).", "tecnica": "Raciocínio terapêutico", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Paciente P.R., 66 anos, com dispepsia e tratamento prolongado com um inibidor de bomba de prótons (-prazol). Ele pergunta por que o médico não prescreveu um bloqueador H2. Qual é a melhor resposta farmacológica?", "alternativas": ["O bloqueador H2 é mais potente que o inibidor de bomba de prótons, mas causa mais efeitos adversos no sistema nervoso central", "O inibidor de bomba de prótons é usado apenas para infecção, e o bloqueador H2 é o único indicado para dispepsia crônica", "Não há diferença de mecanismo, porque ambos são agonistas de receptor acoplado a proteína G com efeito idêntico", "O inibidor de bomba de prótons aumenta a acidez gástrica, por isso é usado em pacientes que precisam de mais ácido", "Bloqueia a H+/K+-ATPase, a etapa final da secreção ácida; efeito mais intenso"], "gabarito": "E", "justificativa": "Inibidores da bomba de prótons (-prazol) bloqueiam a H⁺/K⁺-ATPase, a etapa final da secreção ácida, com efeito mais intenso que os anti-H2. O exemplo mostra a necessidade de conhecer o mecanismo para justificar a escolha (resumo: Nomenclatura e raciocínio).", "tecnica": "Caso clínico integrado", "slide": null}], "id": "farma-gilmar-01", "titulo": "Aula 1", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-02"] = {"subtitulo": "Farmacocinética: ADME, biodisponibilidade, metabolismo e doses", "pdf": "pdf/gilmar/aula-02.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 2 · Farmacocinética (Prof. Dr. Gilmar S. Erzinger)", "Katzung, Farmacologia Básica e Clínica; Goodman & Gilman; Rowland e Tozer; Lei 9.787/1999 (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página.", "Slides e transcrição da aula, Prof. Dr. Gilmar S. Erzinger (resumo completo)"], "tabela": {"titulo": "Vias de administração e biodisponibilidade (slide 7)", "colunas": ["Via", "Biodisponibilidade", "Característica principal"], "linhas": [["Intravenosa", "100% (referência)", "Início imediato; controle preciso da dose"], ["Intramuscular", "75 a ≤100%", "Rápida em solução aquosa; veículo oleoso forma depósito"], ["Subcutânea", "75 a ≤100%", "Absorção mais lenta que a IM (ex.: insulina, heparina)"], ["Oral", "5 a <100%", "Mais conveniente; sujeita à primeira passagem"], ["Retal", "30 a <100%", "Primeira passagem parcial; útil com vômitos"], ["Transdérmica", "80 a ≤100%", "Absorção lenta e sustentada (ex.: adesivos)"]]}, "resumo": [{"titulo": "1. Visão geral: o ADME e o que a aula pede", "pontos": [{"t": "O que é farmacocinética", "sub": ["Farmacocinética descreve o que o organismo faz com o medicamento, da forma farmacêutica até a eliminação total. Cada etapa pode limitar o efeito: se o fármaco não se dissolve, não é absorvido; se é metabolizado rápido demais, não chega ao alvo; se é eliminado rápido, precisa de doses mais frequentes.", "As etapas são: Liberação (desintegração e dissolução da forma farmacêutica), Absorção (passagem do local de administração para a circulação sistêmica), Distribuição (passagem do sangue para os tecidos, com ligação a proteínas), Metabolismo ou biotransformação (sobretudo hepática, para metabólitos mais polares) e Excreção (rim, bile, pulmões). O acrônimo ADME resume a sequência."]}, {"t": "Objetivos de aprendizagem da aula", "sub": ["Ao final, você deve descrever as etapas ADME e os fatores que as modificam; interpretar a curva concentração × tempo e a biodisponibilidade; explicar metabolismo de fase I e II, CYP450, indução e inibição; calcular e aplicar clearance, volume de distribuição e meia-vida; e ajustar o raciocínio para populações especiais."]}]}, {"titulo": "2. Absorção: como o fármaco atravessa as membranas", "pontos": [{"t": "Mecanismos de passagem", "sub": ["Difusão passiva é o mecanismo principal: a favor do gradiente, depende da lipossolubilidade. A difusão facilitada usa carreadores, sem gasto de energia. O transporte ativo usa transportadores, como os SLC e a glicoproteína-P, que pode expulsar o fármaco da célula. A endocitose serve para macromoléculas."]}, {"t": "Ionização e pH: a regra que resolve quase tudo", "sub": ["Apenas a forma não ionizada atravessa bem as membranas. Ácidos fracos, como o AAS, ficam mais não ionizados em pH ácido, por isso são bem absorvidos no estômago. Bases fracas ficam mais não ionizadas em pH alcalino, por isso são bem absorvidas no intestino.", "A equação de Henderson-Hasselbalch relaciona pKa e pH à proporção entre a forma não ionizada e a ionizada: para ácidos, pKa − pH = log([não ionizada]/[ionizada]).", "O aprisionamento iônico explica o acúmulo do fármaco em compartimentos de pH diferente. Por isso alcalinizar a urina acelera a eliminação de ácidos fracos, como salicilatos e fenobarbital (ver excreção)."]}]}, {"titulo": "3. A curva concentração × tempo", "pontos": [{"t": "Como ler a curva após dose oral", "sub": ["Cmáx é o pico de concentração. Tmáx é o tempo até o pico e indica a velocidade da absorção. AUC é a área sob a curva e representa a exposição total ao fármaco.", "Janela terapêutica é o intervalo entre a concentração mínima efetiva e a concentração mínima tóxica. Duração do efeito é o tempo em que a concentração fica acima da mínima efetiva.", "Interpretação: um fármaco com janela estreita exige monitoramento de nível sérico, porque pequenas variações de dose ou de absorção levam ao efeito tóxico ou à falha."]}]}, {"titulo": "4. Biodisponibilidade e vias de administração", "pontos": [{"t": "Definição e cálculo", "sub": ["Biodisponibilidade (F) é a fração da dose que chega inalterada à circulação sistêmica, na velocidade e na quantidade certas. Pode ser calculada pela razão entre a AUC oral e a AUC intravenosa, corrigida pela dose. Por definição, a via intravenosa tem F = 100%.", "Bioequivalência compara a biodisponibilidade de duas versões do mesmo remédio. É a base dos genéricos (Lei 9.787/1999)."]}, {"t": "Biodisponibilidade por via", "sub": ["Intravenosa: 100%, início imediato e controle preciso da dose.", "Intramuscular: 75 a 100%, rápida em solução aquosa; veículo oleoso forma depósito.", "Subcutânea: 75 a 100%, absorção mais lenta (insulina, heparina).", "Oral: 5 a menos de 100%, mais conveniente, mas sujeita à absorção incompleta e à primeira passagem.", "Retal: 30 a menos de 100%, primeira passagem parcial, útil quando há vômito.", "Transdérmica: 80 a 100%, absorção lenta e sustentada (adesivos).", "Sublingual, inalatória e IV evitam a primeira passagem."]}, {"t": "Primeira passagem e implicações clínicas", "sub": ["Primeira passagem é o metabolismo intestinal e hepático antes de o fármaco atingir a circulação sistêmica.", "Exemplos de alta extração: nitroglicerina (oral quase inútil, por isso é sublingual), propranolol, morfina e lidocaína (não usada por via oral).", "Consequência: a dose oral de um fármaco com alta extração é muito maior que a dose IV. Na cirrose ou em shunts portossistêmicos, a primeira passagem cai e a exposição aumenta, então a dose deve ser reduzida."]}, {"t": "Bioequivalência, genérico, similar e referência", "sub": ["Bioequivalência é a comprovação de que dois medicamentos com a mesma fórmula e quantidade de princípio ativo produzem biodisponibilidade equivalente. O objetivo é garantir a intercambiabilidade.", "O critério é estatístico, em geral com voluntários sadios: os parâmetros de velocidade (Tmáx) e extensão (AUC) da cópia devem ficar entre 80 e 125% do valor da referência.", "Referência (marca): produto inovador, com eficácia, segurança e qualidade comprovadas no registro na Anvisa, com nome comercial próprio.", "Genérico: cópia da referência, identificada obrigatoriamente pela DCB, com a mesma concentração, forma, via, posologia e indicação. É intercambiável com a referência.", "Similar: mesmo princípio ativo, concentração, forma, via e indicação, mas com marca própria. Historicamente podia diferir em excipientes ou embalagem; hoje também deve comprovar equivalência."]}]}, {"titulo": "5. Distribuição", "pontos": [{"t": "Volume de distribuição (Vd)", "sub": ["Vd = Dose ÷ C₀. É um volume aparente, não anatômico, porque relaciona a dose à concentração plasmática resultante. Vd baixo indica fármaco retido no plasma, como a varfarina. Vd alto indica acúmulo tecidual, como amiodarona e digoxina."]}, {"t": "Ligação a proteínas", "sub": ["A albumina liga ácidos fracos e a α1-glicoproteína ácida liga bases. Só a fração livre é ativa e eliminada. Na hipoalbuminemia, a fração livre aumenta: exemplo, fenitoína.", "Deslocamento: competição pela albumina aumenta a fração livre, mas o efeito clínico costuma ser transitório, porque a eliminação também aumenta."]}, {"t": "Barreiras e fluxo sanguíneo", "sub": ["Barreira hematoencefálica tem junções firmes e glicoproteína-P; na inflamação meníngea, a passagem aumenta. Barreira placentária é atravessada por fármacos lipossolúveis, o que é relevante na gestação.", "Órgãos muito perfundidos (cérebro, coração, rim e fígado) recebem o fármaco primeiro.", "Redistribuição: tiopental e propofol têm efeito que termina pela redistribuição do SNC para músculo e gordura, não pela eliminação."]}]}, {"titulo": "6. Metabolismo: fases I e II, CYP450", "pontos": [{"t": "Objetivo do metabolismo", "sub": ["O metabolismo transforma o fármaco em um composto mais polar e facilmente excretável. O principal órgão é o fígado."]}, {"t": "Fase I: funcionalização", "sub": ["Oxidação pelo CYP450, redução e hidrólise. Introduz ou expõe grupos polares como –OH, –NH₂ e –COOH. Pode ativar pró-fármacos ou gerar metabólitos tóxicos, como o NAPQI do paracetamol."]}, {"t": "Fase II: conjugação", "sub": ["Glicuronidação, sulfatação, acetilação, metilação e conjugação com glutationa. Gera compostos geralmente inativos e hidrossolúveis.", "Acetiladores lentos têm maior toxicidade de isoniazida e hidralazina. No neonato a glicuronidação é imatura, o que explica a síndrome cinzenta do cloranfenicol."]}, {"t": "CYP450: a superfamília que decide as interações", "sub": ["O CYP450 é uma superfamília de enzimas, principalmente hepáticas. Modifica a estrutura dos fármacos para eliminá-los, e às vezes ativa pró-fármacos. Também participa da síntese de hormônios e colesterol.", "Seis enzimas metabolizam cerca de 90% dos medicamentos. As mais importantes são CYP3A4 (maior número de fármacos), CYP2D6, CYP2C9, CYP2C19 e CYP1A2."]}, {"t": "Indução e inibição: a maior fonte de interações", "sub": ["Indutores: rifampicina, carbamazepina, fenitoína, fenobarbital, erva-de-são-joão e tabagismo (CYP1A2). Início lento, em dias a semanas, porque exige síntese de enzimas. Efeito: menor concentração do fármaco-alvo e falha terapêutica. Exemplo: rifampicina e contraceptivo oral.", "Inibidores: claritromicina, cetoconazol, itraconazol, fluconazol, ritonavir, amiodarona, fluoxetina e paroxetina (2D6) e suco de toranja (3A4). Início rápido, em horas a poucos dias, por competição direta. Efeito: maior concentração e toxicidade. Exemplo: sinvastatina com claritromicina, com miopatia e rabdomiólise.", "Ao suspender: após a indução, a concentração cai e o efeito some. Após a inibição, a concentração sobe gradualmente e surge toxicidade."]}]}, {"titulo": "7. Excreção", "pontos": [{"t": "Vias de eliminação", "sub": ["Filtração glomerular: só a fração livre é filtrada. Depende da taxa de filtração glomerular (TFG), que é a base do ajuste de dose na doença renal.", "Secreção tubular: transporte ativo pelos transportadores OAT e OCT. Probenecida inibe a secreção de penicilinas, e há competição com o metotrexato.", "Reabsorção passiva: depende do pH urinário. Alcalinizar a urina acelera a eliminação de ácidos fracos, como salicilatos e fenobarbital.", "Biliar e fecal: metabólitos conjugados vão à bile. A circulação êntero-hepática prolonga a ação, como nos estrogênios.", "Pulmonar: anestésicos inalatórios e etanol, base do etilômetro. Leite materno: bases fracas podem se concentrar no leite, porque o pH do leite é menor que o do plasma."]}]}, {"titulo": "8. Parâmetros que orientam a dose", "pontos": [{"t": "Clearance, volume e meia-vida", "sub": ["Clearance (CL) é o volume de plasma depurado por unidade de tempo. A taxa de eliminação é CL × C. A dose de manutenção é CL × Css ÷ F, por intervalo.", "Volume de distribuição (Vd) relaciona dose e concentração. A dose de ataque é Vd × C alvo ÷ F.", "Meia-vida (t½) é o tempo para a concentração cair 50%. Fórmula: t½ = 0,693 × Vd ÷ CL. Define o intervalo entre doses e o tempo até o equilíbrio.", "A meia-vida é um parâmetro dependente: muda quando Vd ou CL mudam. Por isso uma doença renal, que reduz o CL, aumenta a meia-vida de fármacos de eliminação renal."]}, {"t": "Doses repetidas e estado de equilíbrio", "sub": ["Após 1 meia-vida, a concentração atinge 50% da concentração de equilíbrio (Css). Após 2, 75%. Após 3, 87,5%. Após 4 a 5, 94 a 97%: esse é o equilíbrio clínico.", "O mesmo raciocínio vale para a eliminação após suspender o fármaco. Fármacos de meia-vida longa, como amiodarona e digoxina, usam dose de ataque para atingir o alvo mais cedo."]}]}, {"titulo": "9. Cinética: primeira ordem e ordem zero", "pontos": [{"t": "Primeira ordem (linear)", "sub": ["Elimina-se uma fração constante por unidade de tempo. A meia-vida é constante e a concentração é proporcional à dose. Vale para a grande maioria dos fármacos nas doses terapêuticas."]}, {"t": "Ordem zero (saturável)", "sub": ["Elimina-se uma quantidade constante por unidade de tempo. As enzimas estão saturadas, então um pequeno aumento de dose gera grande aumento de concentração.", "Exemplos: etanol, fenitoína e salicilatos em doses altas. Exige ajustes pequenos e monitoramento de nível sérico."]}]}, {"titulo": "10. Populações especiais", "pontos": [{"t": "Idosos, neonatos, gestantes e doentes", "sub": ["Idosos: menor TFG, menos massa magra, mais gordura corporal e menos albumina. Estime a função renal e comece com doses baixas.", "Neonatos e crianças: imaturidade renal e hepática; a dose é calculada por peso ou superfície corporal.", "Gestação: aumento do Vd, da TFG e de algumas CYP, além da passagem placentária. Doses devem ser reavaliadas, como na lamotrigina.", "Doença renal: ajustar dose ou intervalo de fármacos de eliminação renal, como aminoglicosídeos, vancomicina, metformina e enoxaparina.", "Doença hepática: menor metabolismo e menor albumina. Não há marcador simples; usa-se a classificação de Child-Pugh e cautela.", "Obesidade: fármacos lipofílicos têm maior Vd; usa-se peso ideal ou ajustado, conforme o fármaco."]}]}, {"titulo": "11. Caso clínico e pontos-chave", "pontos": [{"t": "Interação varfarina e fluconazol", "sub": ["Homem de 67 anos, com fibrilação atrial, usa varfarina com INR estável em 2,5. Recebe fluconazol por candidíase esofágica. Após 5 dias apresenta equimoses e gengivorragia, com INR de 6,8.", "Mecanismo: o fluconazol inibe o CYP2C9, que metaboliza a varfarina. O fármaco se acumula e o efeito anticoagulante aumenta.", "Por que em poucos dias: inibição é competitiva e rápida. Indução seria lenta. Conduta: suspender ou reduzir a varfarina, medir o INR, avaliar sangramento e, se necessário, usar vitamina K. Prevenção: revisar interações antes de prescrever e monitorar o INR ao iniciar qualquer antifúngico azólico."]}, {"t": "Pontos-chave", "sub": ["ADME define quanto fármaco chega ao alvo e por quanto tempo.", "A biodisponibilidade oral é reduzida por absorção incompleta e primeira passagem.", "Só a fração livre age e é eliminada.", "CYP3A4, 2D6, 2C9, 2C19 e 1A2 concentram as interações. Indutores reduzem os níveis; inibidores aumentam.", "Vd define a dose de ataque; CL define a dose de manutenção.", "O equilíbrio ocorre após 4 a 5 meias-vidas. Na ordem zero, a cautela é maior."]}]}], "glossario": [{"termo": "Biodisponibilidade (F)", "tecnica": "Farmacocinética", "definicao": "Fração da dose que chega inalterada à circulação sistêmica.", "slide": 8}, {"termo": "Primeira passagem", "tecnica": "Metabolismo", "definicao": "Metabolismo intestinal e hepático antes de a droga atingir a circulação sistêmica.", "slide": 8}, {"termo": "Clearance (CL)", "tecnica": "Parâmetro", "definicao": "Volume de plasma depurado por unidade de tempo; define a dose de manutenção.", "slide": 16}, {"termo": "Volume de distribuição (Vd)", "tecnica": "Parâmetro", "definicao": "Volume aparente que relaciona dose e concentração; define a dose de ataque.", "slide": 11}, {"termo": "Indutor enzimático", "tecnica": "Interação", "definicao": "Fármaco que acelera o metabolismo, como rifampicina e carbamazepina, reduzindo níveis.", "slide": 14}, {"termo": "Ordem zero", "tecnica": "Cinética", "definicao": "Eliminação de quantidade constante por tempo, com enzimas saturadas, como etanol e fenitoína em doses altas.", "slide": 18}, {"termo": "Equação de Henderson-Hasselbalch (epônimo: Henderson-Hasselbalch)", "tecnica": "Absorção e pH", "definicao": "Relaciona pKa, pH e as formas ionizada e não ionizada de ácidos e bases fracas; explica a absorção conforme o pH.", "slide": 4}, {"termo": "Bioequivalência", "tecnica": "Farmacocinética", "definicao": "Comprova que duas versões do mesmo fármaco têm biodisponibilidade equivalente. Base dos genéricos.", "slide": 6}, {"termo": "Lei nº 9.787/1999", "tecnica": "Legislação", "definicao": "Lei que regulamenta os medicamentos genéricos no Brasil.", "slide": 8}, {"termo": "Nitroglicerina (via sublingual)", "tecnica": "Exemplo", "definicao": "Alta extração hepática. Usada por via sublingual para evitar a primeira passagem.", "slide": 8}, {"termo": "Meia-vida (t½)", "tecnica": "Parâmetro", "definicao": "Tempo para a concentração cair 50%. t½ = 0,693 × Vd ÷ CL.", "slide": 16}, {"termo": "Cmáx, Tmáx e AUC", "tecnica": "Curva", "definicao": "Cmáx é o pico; Tmáx é o tempo até o pico e indica a velocidade de absorção; AUC é a exposição total.", "slide": 5}, {"termo": "Janela terapêutica", "tecnica": "Curva", "definicao": "Intervalo entre a concentração mínima efetiva e a concentração mínima tóxica.", "slide": 5}, {"termo": "Ionização e pH", "tecnica": "Absorção", "definicao": "Só a forma não ionizada atravessa bem a membrana. Ácidos fracos absorvem em pH ácido; bases fracas, em pH alcalino.", "slide": 4}, {"termo": "Glicoproteína-P", "tecnica": "Transporte", "definicao": "Transportador de efluxo que expulsa fármacos das células. Presente na barreira hematoencefálica.", "slide": 4}, {"termo": "Transportadores SLC", "tecnica": "Transporte", "definicao": "Família de transportadores ativos que levam fármacos para dentro das células.", "slide": 4}, {"termo": "Difusão passiva", "tecnica": "Absorção", "definicao": "Mecanismo principal de absorção, a favor do gradiente, dependente da lipossolubilidade.", "slide": 4}, {"termo": "Albumina", "tecnica": "Distribuição", "definicao": "Proteína plasmática que liga principalmente os ácidos fracos. Só a fração livre é ativa.", "slide": 11}, {"termo": "Alfa-1-glicoproteína ácida", "tecnica": "Distribuição", "definicao": "Proteína plasmática que liga principalmente as bases fracas.", "slide": 11}, {"termo": "Redistribuição (tiopental e propofol)", "tecnica": "Distribuição", "definicao": "Saída do fármaco do SNC para músculo e gordura, que termina o efeito sem eliminação.", "slide": 11}, {"termo": "Barreira hematoencefálica", "tecnica": "Distribuição", "definicao": "Barreira de junções firmes e glicoproteína-P. A inflamação meníngea aumenta a passagem.", "slide": 11}, {"termo": "Placenta e lipossolubilidade", "tecnica": "Distribuição", "definicao": "Fármacos lipossolúveis atravessam a placenta, o que é relevante na gestação.", "slide": 11}, {"termo": "Fase I (funcionalização)", "tecnica": "Metabolismo", "definicao": "Oxidação, redução e hidrólise, sobretudo pelo CYP450. Pode gerar metabólitos tóxicos.", "slide": 12}, {"termo": "Fase II (conjugação)", "tecnica": "Metabolismo", "definicao": "Glicuronidação, sulfatação, acetilação e conjugação com glutationa. Gera compostos inativos e hidrossolúveis.", "slide": 12}, {"termo": "CYP450 (citocromo P450)", "tecnica": "Metabolismo", "definicao": "Superfamília de enzimas hepáticas. Seis enzimas processam cerca de 90% dos medicamentos.", "slide": 13}, {"termo": "CYP3A4", "tecnica": "Enzima", "definicao": "Maior número de fármacos metabolizados. Inibida por suco de toranja e claritromicina.", "slide": 13}, {"termo": "CYP2D6", "tecnica": "Enzima", "definicao": "Metaboliza muitos antidepressivos e betabloqueadores. Inibida por fluoxetina e paroxetina.", "slide": 13}, {"termo": "CYP2C9, CYP2C19 e CYP1A2", "tecnica": "Enzima", "definicao": "Enzimas citadas como relevantes para interações. CYP1A2 é induzido pelo tabagismo.", "slide": 13}, {"termo": "NAPQI", "tecnica": "Metabólito", "definicao": "Metabólito tóxico do paracetamol, gerado pelo CYP.", "slide": 12}, {"termo": "Acetiladores lentos", "tecnica": "Metabolismo", "definicao": "Maior toxicidade de isoniazida e hidralazina.", "slide": 12}, {"termo": "Síndrome cinzenta", "tecnica": "Toxicidade neonatal", "definicao": "Toxicidade por cloranfenicol em neonatos, pela glicuronidação imatura.", "slide": 12}, {"termo": "Indutores enzimáticos", "tecnica": "Interação", "definicao": "Rifampicina, carbamazepina, fenitoína, fenobarbital e erva-de-são-joão. Reduzem a concentração do fármaco-alvo.", "slide": 14}, {"termo": "Inibidores enzimáticos", "tecnica": "Interação", "definicao": "Claritromicina, cetoconazol, itraconazol, fluconazol, ritonavir, amiodarona, fluoxetina, paroxetina e suco de toranja. Aumentam a concentração.", "slide": 14}, {"termo": "Probenecida", "tecnica": "Excreção", "definicao": "Inibe a secreção tubular de penicilinas e aumenta o nível sérico delas.", "slide": 15}, {"termo": "OAT e OCT", "tecnica": "Excreção", "definicao": "Transportadores de secreção tubular de ácidos e bases orgânicos no rim.", "slide": 15}, {"termo": "Filtração glomerular (TFG)", "tecnica": "Excreção", "definicao": "Taxa que filtra fármacos livres. Base do ajuste de dose na doença renal.", "slide": 15}, {"termo": "Circulação êntero-hepática", "tecnica": "Excreção", "definicao": "Metabólitos conjugados são excretados na bile e reabsorvidos, prolongando a ação. Ex.: estrogênios.", "slide": 15}, {"termo": "Dose de ataque e dose de manutenção", "tecnica": "Parâmetros de dose", "definicao": "Ataque = Vd × C alvo ÷ F. Manutenção = CL × Css ÷ F, por intervalo.", "slide": 16}, {"termo": "Cinética de ordem zero", "tecnica": "Cinética", "definicao": "Eliminação de quantidade constante por tempo, com enzimas saturadas. Ex.: fenitoína, etanol, salicilatos em doses altas.", "slide": 18}, {"termo": "Cinética de primeira ordem", "tecnica": "Cinética", "definicao": "Eliminação de fração constante por tempo. A meia-vida é constante.", "slide": 18}, {"termo": "Equilíbrio em doses repetidas", "tecnica": "Cinética", "definicao": "Após 4 a 5 meias-vidas, o equilíbrio clínico é atingido (94 a 97%).", "slide": 17}, {"termo": "Child-Pugh (epônimo: Child-Pugh)", "tecnica": "Insuficiência hepática", "definicao": "Escala de gravidade da doença hepática, citada como referência para dose em hepatopatas.", "slide": 19}], "caso": {"titulo": "Caso: sangramento com varfarina e fluconazol", "perfil": "Interação por inibição do metabolismo e risco de sangramento.", "etapas": [{"titulo": "Etapa 1: mecanismo", "texto": "Homem de 67 anos com fibrilação atrial, em varfarina com INR estável em 2,5. Recebe fluconazol por candidíase esofágica. Após cinco dias, apresenta equimoses e gengivorragia, com INR de 6,8.", "perguntas": [{"pergunta": "Qual é o mecanismo mais provável da interação?", "alts": ["Inibição enzimática pelo fluconazol, que eleva a concentração da varfarina", "Indução enzimática pelo fluconazol, que reduz a concentração da varfarina", "Competição pela albumina, que reduz o Vd da varfarina", "Alcalinização urinária, que acelera a excreção renal da varfarina", "Redução da filtração glomerular, que retém a varfarina no plasma"], "erradas": ["Fluconazol é inibidor, e não indutor, por essa via.", "Competição pela albumina tem efeito transitório, e não explica o quadro.", "Alcalinização urinária acelera a eliminação de ácidos fracos, e não o efeito descrito.", "A filtração reduzida não é o mecanismo citado para essa interação."], "justificativa": "Inibidores como fluconazol reduzem o metabolismo pelo CYP e elevam os níveis do fármaco (slide 14). A varfarina é metabolizada principalmente pelo CYP2C9 (slide 12)."}]}, {"titulo": "Etapa 2: conduta", "texto": "A equipe avalia o risco de sangramento. A aula destaca que o efeito de uma interação pode aparecer em dias, conforme a meia-vida e a mudança de níveis.", "perguntas": [{"pergunta": "Qual é a conduta mais adequada diante de INR de 6,8 com sangramento, segundo a lógica da aula?", "alts": ["Suspender a varfarina e avaliar o risco de sangramento com monitoramento", "Manter a dose e aumentar o fluconazol para corrigir o INR", "Dobrar a dose de varfarina para compensar a interação", "Trocar o fluconazol por rifampicina, que é indutora", "Ignorar o INR e reavaliar apenas após duas semanas"], "erradas": ["Manter a dose com fluconazol agrava a interação.", "Aumentar o fluconazol eleva ainda mais a concentração da varfarina.", "Dobrar a dose aumenta o risco de sangramento.", "Adiar a reavaliação expõe o paciente a sangramento grave."], "justificativa": "Com a interação, os níveis sobem gradualmente após o início e caem ao suspender; a conduta é suspender e monitorar, pois o risco é de toxicidade (slide 14)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Paciente J.A., 42 anos, intoxicado com um ácido fraco de pKa 3,5. O fármaco foi ingerido em grande quantidade e a absorção gástrica é rápida. Qual é a razão para a absorção intensa no estômago, e o que muda se o pH gástrico subir com antiácido?", "alternativas": ["No pH alcalino o ácido se torna não ionizado e absorve mais; com antiácido a absorção gástrica aumenta muito", "No pH ácido a forma ionizada atravessa a membrana por transporte ativo; antiácido não altera a absorção do fármaco", "O estômago absorve ácidos por endocitose, que independe do pH; antiácido apenas diminui a dissolução do comprimido", "Forma não ionizada predomina em pH ácido e atravessa; antiácido reduz a absorção", "No pH neutro o ácido é totalmente ionizado e difunde-se pela glicoproteína-P, mais rápido em pH alcalino"], "gabarito": "D", "justificativa": "Ácidos fracos ficam não ionizados em pH ácido e atravessam bem a membrana. Antiácido eleva o pH, aumenta a forma ionizada e reduz a absorção (Henderson-Hasselbalch; resumo: Absorção).", "tecnica": "Henderson-Hasselbalch e absorção", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Paciente com angina aguda usa nitroglicerina por via oral e o efeito é pouco evidente. Após troca para via sublingual, o alívio é rápido. Qual é a explicação para essa diferença?", "alternativas": ["A oral sofre primeira passagem hepática intensa; a sublingual evita essa passagem, com biodisponibilidade alta", "A oral é absorvida apenas no cólon, onde a nitroglicerina é inativada pela microbiota, por isso o efeito é lento", "A sublingual aumenta a meia-vida do fármaco, porque a absorção pela mucosa é mais lenta e prolonga o efeito", "A oral ativa o CYP2D6 e torna a nitroglicerina inativa, enquanto a sublingual é metabolizada apenas no rim", "A oral sofre ligação total à albumina, impedindo o fármaco de chegar ao coração; a sublingual não tem albumina"], "gabarito": "A", "justificativa": "Nitroglicerina tem alta extração hepática. Por via oral, a biodisponibilidade é muito baixa. A via sublingual evita a primeira passagem (resumo: Biodisponibilidade).", "tecnica": "Biodisponibilidade e primeira passagem", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Em um estudo, um fármaco tem AUC oral de 40 mg·h/L e AUC IV de 100 mg·h/L, na mesma dose. Qual é a biodisponibilidade oral e o que ela significa para a dose oral?", "alternativas": ["100%; como a AUC oral é menor, o fármaco é mais eficaz por via oral do que por via intravenosa", "250%; a dose oral pode ser reduzida à metade, porque o fármaco se concentra no fígado após a absorção", "60%; a dose oral deve ser igual à IV, porque a diferença de AUC corresponde à fração ligada à albumina", "4%; o fármaco é quase totalmente inativo por via oral e deve ser administrado somente por via intravenosa", "40%; a dose oral deve ser maior, por absorção incompleta ou primeira passagem"], "gabarito": "E", "justificativa": "F = AUC oral ÷ AUC IV, corrigida pela dose. Com 40 ÷ 100, F = 40%. A dose oral deve ser maior para compensar a fração que não chega à circulação (resumo: Biodisponibilidade e primeira passagem).", "tecnica": "Biodisponibilidade calculada", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Paciente com cirrose descompensada recebe a dose habitual de morfina oral, que tem alta extração hepática, e apresenta sonolência intensa. Qual é a explicação farmacocinética?", "alternativas": ["A cirrose aumenta a ligação à albumina, o que reduz a fração livre e aumenta a eliminação renal da morfina", "A cirrose ativa a glicuronidação e converte a morfina em metabólito neurotóxico que se acumula no cérebro", "A primeira passagem diminui pela cirrose e a exposição sistêmica aumenta, exigindo redução da dose", "A cirrose aumenta o volume de distribuição, e a morfina se acumula no tecido adiposo, causando sedação tardia", "A cirrose reduz a absorção intestinal por lesão da mucosa, e a sonolência resulta da dose de reposição"], "gabarito": "C", "justificativa": "Na cirrose ou em shunts portossistêmicos, a primeira passagem cai e a exposição aumenta. Por isso a dose deve ser reduzida (resumo: Biodisponibilidade e primeira passagem).", "tecnica": "Cirrose e primeira passagem", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Uma indústria apresenta um genérico com AUC 83% e Tmáx dentro da faixa do referência. Um médico pergunta se o genérico pode substituir a marca. Qual é a resposta mais correta, segundo o critério de bioequivalência?", "alternativas": ["Não, porque qualquer valor abaixo de 100% indica que o genérico tem menos fármaco e deve ser reprovado", "Sim, porque a extensão (AUC) está dentro da faixa de 80 a 125% do referência e a velocidade também está adequada", "Não, porque a bioequivalência exige valores acima de 125% do referência para garantir a eficácia terapêutica", "Sim, mas só se o genérico tiver a mesma marca comercial do referência, o que é exigido pela lei de bioequivalência", "Não, porque bioequivalência é comprovada apenas em pacientes com a doença e nunca em voluntários sadios"], "gabarito": "B", "justificativa": "A bioequivalência exige que os parâmetros de velocidade (Tmáx) e extensão (AUC) fiquem entre 80 e 125% do referência. O intervalo de 83% está dentro do critério (resumo: Bioequivalência e genérico).", "tecnica": "Bioequivalência e critério", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Dois fármacos são comparados: um tem Vd de 8 L e outro, Vd de 300 L, com a mesma dose. Qual é a interpretação correta e qual é o exemplo típico de cada caso?", "alternativas": ["Vd baixo indica fármaco eliminado pelo fígado, como a varfarina; Vd alto indica eliminação renal, como a amiodarona", "Vd baixo indica fármaco lipossolúvel, como a digoxina; Vd alto indica fármaco ligado à albumina, como a varfarina", "Vd é um volume anatômico real; o fármaco de 300 L ocupa mais espaço no corpo e é mais perigoso que o de 8 L", "Vd baixo: retido no plasma, como varfarina; Vd alto: acúmulo tecidual, como digoxina", "Vd baixo indica meia-vida curta, como a amiodarona; Vd alto indica meia-vida longa, como a varfarina em dose alta"], "gabarito": "D", "justificativa": "Vd = Dose ÷ C₀ é aparente. Vd baixo: fármaco retido no plasma (varfarina). Vd alto: acúmulo tecidual (amiodarona, digoxina) (resumo: Distribuição).", "tecnica": "Distribuição: Vd baixo e alto", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Paciente hipoalbuminêmica, com 2,4 g/dL, recebe fenitoína, fármaco com alta ligação às proteínas. A concentração total está dentro da faixa, mas há sinais de toxicidade. Qual é a explicação?", "alternativas": ["A hipoalbuminemia aumenta a ligação da fenitoína à α1-glicoproteína, o que reduz a fração livre e causa toxicidade", "A fração livre aumenta com a queda da albumina; a fração ativa fica maior que a esperada pela concentração total", "A hipoalbuminemia reduz a eliminação hepática da fenitoína, mas não altera a fração livre do fármaco no plasma", "A hipoalbuminemia aumenta o clearance renal da fenitoína, o que eleva a concentração no fígado e causa toxicidade", "A hipoalbuminemia aumenta o volume de distribuição, o que diminui a concentração plasmática total do fármaco"], "gabarito": "B", "justificativa": "Só a fração livre é ativa e eliminada. Com a queda da albumina, a fração livre aumenta, e a toxicidade pode aparecer mesmo com concentração total na faixa (resumo: Distribuição, ligação a proteínas).", "tecnica": "Hipoalbuminemia e fração livre", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Recém-nascido recebe cloranfenicol e desenvolve colapso circulatório, cianose e palidez cinzenta. A conduta farmacológica mais coerente considera qual característica do metabolismo neonatal?", "alternativas": ["Excesso de glicuronidação; o fármaco é eliminado rápido demais, e a dose deve ser dobrada para manter o efeito", "Excesso de CYP3A4 neonatal; o fármaco é inativado pelo fígado, e a dose deve ser substituída por outra via", "Ausência de albumina neonatal; o fármaco fica livre e é excretado no leite materno em grande volume", "Glicuronidação imatura; o fármaco se acumula, e a dose deve ser reduzida, com monitoramento de nível sérico", "Alta TFG neonatal; o fármaco é eliminado pelo rim em minutos, e a dose deve ser administrada a cada hora"], "gabarito": "D", "justificativa": "No neonato, a glicuronidação (fase II) é imatura. O cloranfenicol se acumula e causa a síndrome cinzenta. A dose deve ser reduzida e o nível monitorado (resumo: Metabolismo e populações especiais).", "tecnica": "Neonato e fase II", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Homem de 67 anos com fibrilação atrial usa varfarina com INR de 2,5. Recebe fluconazol e, em cinco dias, o INR chega a 6,8 com gengivorragia. Qual é o mecanismo e a conduta imediata mais adequada?", "alternativas": ["Indução do CYP3A4 pelo fluconazol, que acelera a eliminação da varfarina; aumentar a dose de varfarina para compensar", "Inibição do CYP1A2 pelo fluconazol; trocar a varfarina por um betabloqueador sem qualquer monitoramento adicional", "Inibição do CYP2C9 pelo fluconazol; suspender ou reduzir a varfarina e medir o INR", "Ativação da glicoproteína-P pelo fluconazol, que expulsa a varfarina; administrar vitamina K e continuar a mesma dose", "Ligação do fluconazol à albumina, que desloca a varfarina; manter o fármaco e repetir o INR apenas após um mês"], "gabarito": "C", "justificativa": "Fluconazol inibe o CYP2C9, que metaboliza a varfarina. O acúmulo eleva o INR. A conduta inclui suspender ou reduzir a varfarina, medir o INR e avaliar o sangramento (resumo: Caso clínico da aula).", "tecnica": "CYP450: interação e o caso da varfarina", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Mulher de 26 anos, paciente L.C., usa contraceptivo oral e inicia tratamento de tuberculose com rifampicina. Após duas semanas, há gravidez não planejada. Qual é o mecanismo, e por que o efeito demora a aparecer?", "alternativas": ["Inibição de CYP por rifampicina; a inibição é lenta e causa aumento do contraceptivo, que falha por toxicidade", "Indução de CYP por rifampicina; a síntese de novas enzimas leva dias a semanas, e a concentração do contraceptivo cai", "Ligação do contraceptivo à albumina, que é liberada lentamente; o efeito demora porque a albumina é renovada em meses", "Aumento da excreção biliar do contraceptivo; a excreção só se altera após semanas de acúmulo do conteúdo biliar", "Redução da absorção intestinal do contraceptivo pela rifampicina; a mucosa leva semanas para se regenerar"], "gabarito": "B", "justificativa": "Rifampicina é indutora de CYP. A síntese de novas enzimas leva dias a semanas. Com mais enzima, o contraceptivo é metabolizado mais rápido e a concentração cai (resumo: Indução e inibição).", "tecnica": "Indução enzimática e contraceptivo", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Paciente em uso de fenitoína aumenta a dose de 300 para 400 mg/dia, e a concentração sérica dobra em poucos dias, com nistagmo e ataxia. Qual é a explicação cinética?", "alternativas": ["Cinética de primeira ordem com Vd muito baixo, porque a fenitoína fica retida no plasma e não se distribui aos tecidos", "Indução do CYP3A4 pela própria fenitoína, que acelera a eliminação e causa acúmulo tóxico no sistema nervoso", "Aumento da TFG, que filtra mais fenitoína e causa acúmulo em poucos dias de tratamento no paciente", "Redução da albumina, que aumenta a fração livre, mas sem alterar a concentração sérica total do fármaco", "Cinética de ordem zero: as enzimas estão saturadas, e um pequeno aumento de dose gera grande aumento de concentração"], "gabarito": "E", "justificativa": "Fenitoína tem cinética de ordem zero em doses altas. As enzimas se saturam e a eliminação deixa de ser proporcional à concentração. Por isso são necessários ajustes pequenos e monitoramento de nível sérico (resumo: Cinética de ordem zero).", "tecnica": "Ordem zero: fenitoína", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um fármaco de ácido fraco é eliminado principalmente pela urina. Em uma intoxicação, o médico alcaliniza a urina. Qual é o efeito esperado, e por qual mecanismo?", "alternativas": ["Diminuição da eliminação, porque a alcalinização aumenta a ligação do fármaco às proteínas plasmáticas", "Nenhum efeito, porque a eliminação de ácidos fracos depende somente da secreção por transportadores OAT", "Aumento da eliminação, porque a forma ionizada não é reabsorvida no túbulo renal", "Aumento da reabsorção, porque a urina alcalina favorece a difusão passiva da forma não ionizada", "Aumento do volume de distribuição, porque a urina alcalina desloca o fármaco do plasma para os tecidos"], "gabarito": "C", "justificativa": "Ácidos fracos ficam ionizados em urina alcalina e não são reabsorvidos, o que acelera a eliminação (aprisionamento iônico; resumo: Excreção).", "tecnica": "Excreção renal e pH urinário", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Gestante de 32 semanas, paciente F.R., com epilepsia em uso de lamotrigina. A concentração sérica está abaixo da faixa terapêutica, apesar da dose habitual. Qual é a explicação farmacocinética mais coerente?", "alternativas": ["Aumento do Vd e da TFG na gestação; a dose precisa ser reavaliada e a concentração monitorada", "Redução do Vd na gestação, porque o plasma se concentra pela retenção de líquido nas pernas da paciente", "Redução da TFG na gestação, o que aumenta a meia-vida e eleva a concentração, causando intoxicação", "Aumento da albumina na gestação, o que reduz a fração livre e impede a ação do fármaco no sistema nervoso", "Ausência de alterações farmacocinéticas, porque a gestação altera apenas a farmacodinâmica dos receptores"], "gabarito": "A", "justificativa": "Na gestação há aumento do Vd, da TFG e de algumas CYP. A dose precisa ser reavaliada, como na lamotrigina, com monitoramento de nível sérico (resumo: Populações especiais).", "tecnica": "Populações especiais: gestação", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Paciente I.N., 80 anos, com insuficiência renal, usa enoxaparina em dose plena. Apresenta sangramento e acúmulo do fármaco. Qual é a conduta farmacocinética mais adequada, considerando a eliminação do fármaco?", "alternativas": ["Aumentar a dose, porque a enoxaparina é eliminada pelo fígado e a insuficiência renal não interfere na sua eliminação", "Trocar por dose oral diária, porque a via oral evita o acúmulo renal de qualquer fármaco de baixo peso molecular", "Suspender a anticoagulação sem substituição, porque a enoxaparina não tem indicação em pacientes idosos com doença renal", "Administrar vitamina K em dose alta, porque a enoxaparina é inativada pela vitamina K no fígado do paciente", "Ajustar a dose ou o intervalo de fármacos de eliminação renal e monitorar a função renal e a atividade anticoagulante"], "gabarito": "E", "justificativa": "Enoxaparina é de eliminação renal. Na doença renal, deve-se ajustar a dose ou o intervalo e monitorar a função renal e o efeito anticoagulante (resumo: Populações especiais, doença renal).", "tecnica": "Caso clínico integrado: acúmulo e meia-vida", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um fármaco tem clearance de 5 L/h, Vd de 50 L e biodisponibilidade oral de 50%. Qual é a meia-vida aproximada e o efeito de dobrar o clearance sobre a meia-vida?", "alternativas": ["Meia-vida de cerca de 7 horas; dobrar o clearance reduz a meia-vida pela metade, para cerca de 3,5 horas", "Meia-vida de cerca de 2 horas; dobrar o clearance aumenta a meia-vida para cerca de 4 horas, por acúmulo tecidual", "Meia-vida de cerca de 70 horas; dobrar o clearance não altera a meia-vida, porque a biodisponibilidade é fixa", "Meia-vida de cerca de 14 horas; dobrar o clearance dobra a meia-vida, porque a eliminação fica mais lenta", "Meia-vida de cerca de 35 horas; dobrar o clearance reduz a meia-vida a um quarto, pela fórmula inversa"], "gabarito": "A", "justificativa": "t½ = 0,693 × Vd ÷ CL = 0,693 × 50 ÷ 5 ≈ 7 horas. A biodisponibilidade não entra na fórmula de meia-vida. Dobrar o clearance reduz a meia-vida pela metade (resumo: Parâmetros que orientam a dose).", "tecnica": "Parâmetros integrados", "slide": null}], "id": "farma-gilmar-02", "titulo": "Aula 2", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-03"] = {"subtitulo": "Etapas do desenvolvimento de fármacos: pré-clínica, fases I a IV", "pdf": "pdf/gilmar/aula-03.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 3 · Etapas do desenvolvimento de fármacos (Prof. Dr. Gilmar S. Erzinger)", "FDA; ICH E6, E8 e M3; Anvisa; Brunton e Knollmann (Goodman & Gilman), citados nos slides", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página.", "Slides e transcrição da aula, Prof. Dr. Gilmar S. Erzinger (resumo completo)"], "tabela": {"titulo": "Fases clínicas (slide 29)", "colunas": ["Fase", "Participantes", "Objetivo principal", "Pergunta-chave"], "linhas": [["I", "Voluntários saudáveis e/ou pacientes", "Segurança, tolerabilidade, PK/PD", "Qual dose e exposição são toleráveis?"], ["II", "Pacientes", "Eficácia inicial, dose e segurança", "Funciona, e qual dose ou regime usar?"], ["III", "Pacientes", "Confirmar eficácia e segurança", "O benefício é consistente e clinicamente relevante?"], ["IV", "População em uso real", "Farmacovigilância e efetividade", "O que ocorre após ampla utilização?"]]}, "resumo": [{"titulo": "1. O caminho de um fármaco: da descoberta ao pós-registro", "pontos": [{"t": "Visão geral das etapas e do tempo", "sub": ["O desenvolvimento de um fármaco vai da descoberta à farmacovigilância em etapas: descoberta (2 a 4 anos), pré-clínica (1 a 3 anos), fase I (meses a 1 ano), fase II (até 2 anos), fase III (1 a 4 anos), registro (1 a 2 anos) e fase IV (contínua). O tempo total típico é de 10 a 15 anos.", "Antes de testar em humanos, a pesquisa precisa de autorização da agência reguladora e de aprovação ética. Antes de comercializar, precisa de registro sanitário. Essas três barreiras (autorização, ética e registro) são o que separa a pesquisa do medicamento disponível."]}, {"t": "Funil de alto risco", "sub": ["São avaliados de 5.000 a 10.000 compostos na descoberta; cerca de 250 entram na pré-clínica; cerca de 5 chegam aos ensaios clínicos; 1 é aprovado.", "Para cada fármaco aprovado, o custo estimado é de US$ 1 a 2,6 bilhões, incluindo os fracassos. É por isso que o medicamento de referência tem patente e preço elevado, para recuperar o investimento."]}]}, {"titulo": "2. Descoberta e pesquisa pré-clínica", "pontos": [{"t": "Descoberta: do alvo ao candidato", "sub": ["A descoberta começa pela identificação de uma necessidade terapêutica e de um alvo biológico, como uma proteína, um receptor ou uma via envolvida na doença. Moléculas podem vir de síntese química, produtos naturais, biotecnologia ou reposicionamento de fármacos já existentes.", "Triagem de alto rendimento (HTS) e modelagem in silico encontram moléculas ativas, chamadas hits. Modelagem in silico é a simulação por computador de um fenômeno biológico ou farmacológico, antes de experimentos em animais ou humanos.", "Os hits mais promissores em potência, seletividade e perfil químico viram o composto-líder. A otimização ajusta a estrutura (relação estrutura-atividade) até um candidato a fármaco, com mecanismo conhecido."]}, {"t": "O que a pré-clínica avalia", "sub": ["Farmacodinâmica: mecanismo de ação e eficácia em modelos in vitro (células, tecidos) e in vivo (animais).", "Farmacocinética (ADME): absorção, distribuição, metabolismo e excreção, com biodisponibilidade e meia-vida.", "Toxicologia: toxicidade aguda e de doses repetidas, genotoxicidade, toxicidade reprodutiva e, quando aplicável, carcinogenicidade.", "Formulação e produção: forma farmacêutica, estabilidade e fabricação do lote para os estudos clínicos, sob Boas Práticas de Fabricação.", "Princípios: estudos sob Boas Práticas de Laboratório (BPL), em geral em duas espécies (um roedor e um não roedor). Seguem os 3Rs: substituir, reduzir e refinar o uso de animais."]}, {"t": "Perguntas que a pré-clínica precisa responder", "sub": ["O fármaco produz o efeito farmacológico esperado? Qual é a relação entre dose, exposição e efeito? Quais órgãos ou sistemas podem ser afetados? Qual é a margem de segurança? Como o composto é absorvido, distribuído, metabolizado e eliminado? Qual dose inicial pode ser considerada para humanos?", "Mensagem do professor: sucesso pré-clínico não garante eficácia clínica. Muitos fármacos promissores em animais falham em humanos."]}, {"t": "Ponte para os humanos: autorização e ética", "sub": ["Agência reguladora: no Brasil, a Anvisa analisa o dossiê de desenvolvimento clínico. Nos EUA, o FDA analisa o pedido de IND. Ambas avaliam dados pré-clínicos, qualidade do produto e protocolo.", "Comitê de ética: no Brasil, o sistema CEP/Conep avalia riscos e benefícios para os participantes e aprova o Termo de Consentimento Livre e Esclarecido (TCLE).", "Boas Práticas Clínicas (BPC, ICH E6): padrão internacional que rege todos os ensaios clínicos. Princípios fundamentais: consentimento informado, avaliação risco-benefício, proteção dos participantes e qualidade dos dados."]}]}, {"titulo": "3. Fase I: segurança e farmacocinética", "pontos": [{"t": "Quem e quanto", "sub": ["A fase I inclui 20 a 100 participantes, em geral voluntários sadios. Dura de meses a um ano. Cerca de 70% dos candidatos avançam para a fase II.", "Exceção: em oncologia e em outros fármacos muito tóxicos, a fase I é feita diretamente em pacientes, porque voluntários sadios não toleram a dose."]}, {"t": "Objetivos e desenhos", "sub": ["Avaliar segurança e tolerabilidade em humanos. Descrever a farmacocinética (ADME) e os efeitos farmacodinâmicos. Definir a faixa de dose segura e a dose máxima tolerada.", "Desenhos: dose única e doses múltiplas crescentes, chamados SAD (single ascending dose) e MAD (multiple ascending dose). São investigados eventos adversos, sinais vitais, ECG, laboratório, farmacocinética e, quando pertinente, farmacodinâmica.", "Conceitos: first-in-human (FIH) é a primeira administração em humanos. Food effect avalia a influência da alimentação na exposição ao fármaco. Interações medicamentosas podem ser avaliadas quando relevantes.", "A pergunta central da fase I: como o organismo responde ao fármaco e qual é a exposição tolerável?"]}]}, {"titulo": "4. Fase II: a primeira evidência de eficácia", "pontos": [{"t": "Quem, quanto e para quê", "sub": ["A fase II inclui 100 a 300 pacientes com a doença-alvo. Dura até dois anos. Cerca de um terço dos candidatos avança para a fase III.", "Objetivos: obter a primeira evidência de eficácia (prova de conceito), estabelecer a relação dose-resposta e o esquema posológico, e ampliar a avaliação de segurança de curto prazo.", "Fase IIa costuma explorar a prova de conceito e a relação dose-resposta. Fase IIb costuma buscar a dose e o regime que serão usados nos estudos confirmatórios.", "Pergunta-chave: o medicamento parece funcionar? É a fase com maior taxa de fracasso, porque muitos candidatos não demonstram eficácia suficiente."]}, {"t": "Desenho randomizado e controlado", "sub": ["Randomizado: os participantes são distribuídos ao acaso entre os grupos. Assim, diferenças entre os grupos dificilmente explicam os resultados.", "Controlado: existe um grupo de comparação, que pode receber placebo, tratamento padrão ou, em alguns desenhos, outra dose.", "Exemplo do slide: 200 hipertensos randomizados, 100 com 20 mg do novo fármaco e 100 com placebo. Após 12 semanas, a queda da pressão arterial e os eventos adversos são comparados. Se a queda for maior no grupo do fármaco, sem aumento inaceitável de eventos adversos, há evidência preliminar de eficácia.", "Exemplo numérico: queda média de 8 mmHg no grupo do fármaco e de 3 mmHg no controle. A diferença de −5 mmHg sugere atividade terapêutica."]}]}, {"titulo": "5. Fase III: confirmação em larga escala", "pontos": [{"t": "Quem, quanto e para quê", "sub": ["A fase III inclui de 300 a 3.000 ou mais pacientes, em vários centros. Dura de um a quatro anos. Cerca de 25 a 30% dos candidatos chegam ao registro.", "Objetivos: confirmar eficácia e segurança em população maior e mais diversa; comparar com placebo ou tratamento padrão; avaliar desfechos clinicamente relevantes; e detectar reações adversas menos frequentes.", "Desenho: estudos randomizados, duplo-cegos e multicêntricos, chamados de estudos pivotais. Os resultados da fase III formam a base principal do pedido de registro.", "Pergunta-chave: podemos confirmar que funciona em uma população maior?"]}]}, {"titulo": "6. Registro e a decisão regulatória", "pontos": [{"t": "O que a agência avalia", "sub": ["No Brasil, a Anvisa avalia qualidade (fabricação, controle e estabilidade), segurança (dados pré-clínicos e clínicos de todas as fases), eficácia (estudos pivotais), relação benefício-risco, bula e inspeção de Boas Práticas de Fabricação.", "Nos EUA, o FDA faz o mesmo papel; na União Europeia, a EMA.", "A decisão regulatória não encerra a avaliação científica. Rotulagem, indicação, dose, contraindicações, advertências e plano de monitoramento fazem parte do uso aprovado."]}]}, {"titulo": "7. Fase IV: farmacovigilância após a comercialização", "pontos": [{"t": "O que a fase IV detecta", "sub": ["A fase IV envolve milhares a milhões de usuários, na prática real, e dura enquanto o produto existir. Reações raras só são detectáveis em larga escala.", "Objetivos: detectar reações adversas raras ou tardias; avaliar uso a longo prazo e em populações especiais, como idosos, gestantes e crianças; estudar interações e efetividade no mundo real; investigar novas indicações. A notificação de eventos é feita no Brasil pelo VigiMed.", "Exemplo clássico: o rofecoxibe (Vioxx) foi retirado do mercado em 2004, após evidências de aumento do risco cardiovascular."]}]}, {"titulo": "8. Eficácia × efetividade e o que pode parar um programa", "pontos": [{"t": "Conceitos", "sub": ["Eficácia é o desempenho do tratamento em condições controladas de pesquisa. Efetividade é o desempenho em condições mais próximas da prática real. Os conceitos são relacionados, mas não são sinônimos.", "Fases iniciais e ensaios controlados estabelecem a eficácia. Estudos pós-comercialização ampliam o conhecimento sobre efetividade e segurança na vida real."]}, {"t": "Por que um programa de desenvolvimento para", "sub": ["Falta de eficácia ou benefício clínico suficiente. Problemas de segurança ou toxicidade. Perfil farmacocinético inadequado. Dificuldades de formulação, estabilidade ou produção. Interações medicamentosas ou limitações para a população-alvo.", "Também pode parar por razões comerciais ou estratégicas, mesmo quando a molécula tem atividade biológica."]}]}, {"titulo": "9. Quadro-resumo das fases clínicas", "pontos": [{"t": "Fase I, II, III e IV", "sub": ["Fase I: voluntários saudáveis e/ou pacientes; objetivo de segurança, tolerabilidade e farmacocinética; pergunta: qual dose e exposição são toleráveis?", "Fase II: pacientes; eficácia inicial, dose e segurança; pergunta: funciona, e qual dose e regime usar? É uma prova de conceito.", "Fase III: pacientes; confirmar eficácia e segurança; pergunta: o benefício é consistente e clinicamente relevante? É o estudo mais amplo, comparativo.", "Fase IV: população em uso real; farmacovigilância e efetividade; pergunta: o que ocorre após ampla utilização?"]}, {"t": "Exemplo didático: um anti-hipertensivo", "sub": ["Descoberta: a molécula bloqueia um alvo ligado à regulação da pressão arterial. Pré-clínica: atividade, farmacocinética favorável e margem de segurança. Fase I: tolerabilidade e relação dose-exposição. Fase II: pacientes hipertensos, comparando doses. Fase III: grandes estudos confirmatórios, com comparadores apropriados. Fase IV: eventos raros, interações e efetividade no cotidiano."]}]}], "glossario": [{"termo": "Fase I", "tecnica": "Ensaio clínico", "definicao": "Primeiros estudos em humanos, para segurança, tolerabilidade e farmacocinética.", "slide": 14}, {"termo": "SAD e MAD", "tecnica": "Fase I", "definicao": "Single Ascending Dose (dose única crescente) e Multiple Ascending Dose (doses repetidas crescentes).", "slide": 16}, {"termo": "FIH", "tecnica": "Fase I", "definicao": "First-in-human: primeira administração do candidato em seres humanos.", "slide": 16}, {"termo": "Estudo pivotal", "tecnica": "Fase III", "definicao": "Estudo randomizado, duplo-cego e multicêntrico, base do pedido de registro.", "slide": 21}, {"termo": "Randomização", "tecnica": "Desenho do ensaio", "definicao": "Distribuição aleatória dos participantes para os grupos, reduzindo vieses.", "slide": 18}, {"termo": "Farmacovigilância", "tecnica": "Fase IV", "definicao": "Monitoramento de reações adversas após a comercialização; no Brasil, notificação pelo VigiMed.", "slide": 27}, {"termo": "BPL", "tecnica": "Pré-clínica", "definicao": "Boas Práticas de Laboratório, padrão dos estudos não clínicos.", "slide": 8}, {"termo": "Farmacologia clínica", "tecnica": "Desenvolvimento", "definicao": "Estudo de fármacos em seres humanos, em fases progressivas.", "slide": 3}, {"termo": "First-in-human (FIH)", "tecnica": "Fase I", "definicao": "Primeira administração do candidato em seres humanos.", "slide": 16}, {"termo": "Food effect", "tecnica": "Fase I", "definicao": "Avaliação da influência da alimentação na exposição ao fármaco.", "slide": 16}, {"termo": "Fase IIa e IIb", "tecnica": "Fase II", "definicao": "IIa explora prova de conceito e relação dose-resposta. IIb define dose e regime para estudos confirmatórios.", "slide": 17}, {"termo": "Estudo controlado", "tecnica": "Desenho", "definicao": "Estudo com grupo de comparação: placebo, tratamento padrão ou outra dose.", "slide": 18}, {"termo": "Estudo duplo-cego", "tecnica": "Desenho", "definicao": "Nem o participante nem o pesquisador sabem qual grupo recebeu o fármaco.", "slide": 21}, {"termo": "ANVISA (Agência Nacional de Vigilância Sanitária)", "tecnica": "Regulação", "definicao": "Agência brasileira que analisa o dossiê clínico e concede o registro sanitário.", "slide": 12}, {"termo": "DDCM (dossiê de desenvolvimento clínico)", "tecnica": "Regulação", "definicao": "Documento analisado pela Anvisa antes da primeira dose em humanos.", "slide": 12}, {"termo": "FDA e IND", "tecnica": "Regulação", "definicao": "Agência reguladora dos EUA. O IND é o pedido para iniciar estudos em humanos.", "slide": 12}, {"termo": "EMA", "tecnica": "Regulação", "definicao": "Agência reguladora da União Europeia.", "slide": 26}, {"termo": "CEP e Conep", "tecnica": "Ética", "definicao": "Comitês de ética em pesquisa, que avaliam riscos e benefícios e aprovam o TCLE.", "slide": 12}, {"termo": "TCLE (Termo de Consentimento Livre e Esclarecido)", "tecnica": "Ética", "definicao": "Documento de consentimento do participante, aprovado pelo comitê de ética.", "slide": 12}, {"termo": "ICH E6 (Boas Práticas Clínicas)", "tecnica": "Padrão internacional", "definicao": "Padrão que rege todos os ensaios clínicos, do International Council for Harmonisation.", "slide": 12}, {"termo": "Boas Práticas de Laboratório (BPL)", "tecnica": "Pré-clínica", "definicao": "Normas que orientam os estudos pré-clínicos em laboratório.", "slide": 8}, {"termo": "Os 3Rs (substituir, reduzir e refinar)", "tecnica": "Pré-clínica", "definicao": "Princípios do uso de animais em pesquisa: substituir por métodos alternativos, reduzir o número e refinar o procedimento.", "slide": 8}, {"termo": "Modelagem in silico", "tecnica": "Descoberta", "definicao": "Simulação por computador para estudar fenômenos biológicos antes de experimentos.", "slide": 7}, {"termo": "Triagem de alto rendimento (HTS)", "tecnica": "Descoberta", "definicao": "Triagem automatizada de grandes bibliotecas de compostos, que encontra os hits.", "slide": 7}, {"termo": "Composto-líder (lead)", "tecnica": "Descoberta", "definicao": "Hit mais promissor em potência, seletividade e perfil químico.", "slide": 7}, {"termo": "Descoberta do candidato", "tecnica": "Descoberta", "definicao": "Identificação de alvo, triagem, composto-líder e otimização até o candidato a fármaco.", "slide": 6}, {"termo": "VigiMed", "tecnica": "Notificação", "definicao": "Sistema brasileiro de notificação de eventos adversos a medicamentos.", "slide": 27}, {"termo": "Rofecoxibe (Vioxx)", "tecnica": "Exemplo", "definicao": "Medicamento retirado do mercado em 2004, após aumento do risco cardiovascular detectado em uso real.", "slide": 27}, {"termo": "Eficácia", "tecnica": "Conceito", "definicao": "Desempenho do tratamento em condições controladas de pesquisa clínica.", "slide": 28}, {"termo": "Efetividade", "tecnica": "Conceito", "definicao": "Desempenho do tratamento em condições da prática real.", "slide": 28}, {"termo": "Registro sanitário", "tecnica": "Regulação", "definicao": "Autorização de comercialização após avaliação de qualidade, segurança e eficácia.", "slide": 26}, {"termo": "Boas Práticas de Fabricação", "tecnica": "Regulação", "definicao": "Normas de fabricação, inspecionadas antes do registro.", "slide": 26}, {"termo": "Custo de desenvolvimento (PhRMA e DiMasi)", "tecnica": "Dado", "definicao": "Estimativa de US$ 1 a 2,6 bilhões por fármaco aprovado, incluindo fracassos.", "slide": 4}], "caso": {"titulo": "Caso: novo fármaco para insuficiência cardíaca", "perfil": "Decisões em cada etapa do desenvolvimento.", "etapas": [{"titulo": "Etapa 1: onde estamos", "texto": "Uma empresa tem uma molécula para insuficiência cardíaca. Os estudos mostram atividade em modelos animais, mas ainda não há dados em humanos. A equipe precisa decidir o próximo passo.", "perguntas": [{"pergunta": "Qual é o próximo passo adequado, segundo a aula?", "alts": ["Obter autorização da agência e aprovação ética antes da primeira dose em humanos", "Lançar o produto no mercado, com a fase IV como único estudo", "Iniciar a fase III com milhares de pacientes sem fase I", "Dispensar a farmacocinética, pois a atividade já foi mostrada", "Testar em voluntários sem qualquer protocolo ou consentimento"], "erradas": ["Registro sanitário vem depois de todas as fases clínicas.", "Fase III sem fase I e II não é o caminho descrito.", "A farmacocinética é exigida antes da dose em humanos.", "Consentimento e protocolo são obrigatórios antes da inclusão de participantes."], "justificativa": "Antes de testar em humanos é preciso autorização da agência reguladora e aprovação ética (slides 3 e 12)."}]}, {"titulo": "Etapa 2: fase II", "texto": "Em um estudo de fase II com 200 pacientes, o grupo do novo fármaco reduz a pressão arterial em média 8 mmHg, e o grupo placebo, 3 mmHg.", "perguntas": [{"pergunta": "Qual é a interpretação mais adequada, segundo a aula?", "alts": ["Diferença de 5 mmHg sugere atividade terapêutica preliminar", "Prova definitiva de eficácia, dispensando a fase III", "Redução de 8 mmHg prova ausência de efeito placebo", "Diferença sem relevância, pois fase II não compara grupos", "Evidência de toxicidade, pelo efeito de 8 mmHg"], "erradas": ["Fase II não confirma eficácia; a fase III é que confirma.", "Uma redução de 8 mmHg não prova ausência de efeito placebo, que o grupo controle mede.", "Fase II compara grupos randomizados, por definição.", "A redução de pressão é o efeito desejado, e não toxicidade."], "justificativa": "Na fase II, a diferença entre grupos sugere atividade; a fase III confirma a eficácia (slides 19, 20 e 21)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um laboratório testa um novo anti-hipertensivo em 200 pacientes randomizados: 100 recebem o fármaco e 100 placebo. Após 12 semanas, a queda média da PA é de 12 mmHg no grupo do fármaco e de 4 mmHg no placebo, sem aumento de eventos adversos. Em qual fase o estudo se encaixa, e o que ele sugere?", "alternativas": ["Fase III, com confirmação definitiva da eficácia, dispensando a necessidade de estudos adicionais de segurança e dose", "Fase II, com evidência preliminar de eficácia, prova de conceito e necessidade de definir dose para a fase III", "Fase I, com avaliação de tolerabilidade em voluntários sadios, sem nenhuma informação sobre eficácia terapêutica", "Fase IV, porque o estudo usa placebo e envolve pacientes com doença estabelecida, o que caracteriza uso real", "Pré-clínica, porque o estudo usa pacientes apenas como modelo de hipertensão, sem valor para a decisão regulatória"], "gabarito": "B", "justificativa": "Pacientes com a doença-alvo, randomizados e com comparador, caracterizam a fase II. O estudo fornece evidência preliminar de eficácia e ajuda a definir dose e desenho da fase III (resumo: Fase II).", "tecnica": "Fase II: prova de conceito", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um novo fármaco para insuficiência cardíaca está na primeira administração em humanos. A equipe se pergunta quem deve participar e o que se mede. Qual é a resposta mais coerente com o desenho de fase I?", "alternativas": ["Mil pacientes com insuficiência cardíaca, randomizados e duplo-cegos, com foco exclusivo em desfechos de mortalidade", "Pacientes em uso de registro há anos, para avaliar eventos raros e interações com outros medicamentos de uso comum", "Animais de laboratório em duas espécies, com foco em formulação, sem qualquer contato com seres humanos", "Pacientes com alta taxa de adesão, para medir efetividade em condições de vida real após o registro", "Cerca de 20 a 100 voluntários sadios, com foco em segurança, tolerabilidade e farmacocinética, com doses crescentes"], "gabarito": "E", "justificativa": "Na fase I, em geral voluntários sadios, o objetivo é segurança, tolerabilidade e farmacocinética, com doses únicas ou múltiplas crescentes (SAD/MAD). Em oncologia, a fase I pode ser feita em pacientes (resumo: Fase I).", "tecnica": "Fase I: quem é incluído", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um fármaco tem excelente resultado em ensaio duplo-cego, mas na prática os pacientes não se beneficiam tanto. Qual explicação é mais coerente com a distinção entre eficácia e efetividade?", "alternativas": ["Efetividade é o uso real, afetado por adesão, interações e custo", "Efetividade é o mesmo que eficácia, e a diferença observada decorre apenas de erro de medição do laboratório", "Eficácia só é medida em animais, e a efetividade é medida apenas em voluntários sadios no ensaio clínico", "Efetividade depende só da dose, e a eficácia depende só do tempo de tratamento, sem relação com o paciente", "O resultado muda apenas porque o placebo perde efeito após o registro, e isso não afeta a efetividade"], "gabarito": "A", "justificativa": "Eficácia é o desempenho em condições controladas de pesquisa. Efetividade é o desempenho em condições da prática real. Não são sinônimos (resumo: Eficácia × efetividade).", "tecnica": "Eficácia × efetividade", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Em um ensaio de fase II, os pesquisadores distribuem os pacientes ao acaso entre fármaco e placebo. Um revisor pergunta por que a aleatorização é necessária, mesmo com grupos grandes. Qual é a resposta mais precisa?", "alternativas": ["Reduz a possibilidade de que diferenças entre os grupos, conhecidas ou não, expliquem os resultados", "Garante que o grupo tratado tenha mais pacientes graves, o que aumenta a chance de observar efeito terapêutico", "Dispensa o grupo controle, porque a aleatorização substitui a comparação com placebo ou tratamento padrão", "Garante que todos os pacientes tenham a mesma idade e o mesmo sexo, o que elimina a necessidade de estatística", "Permite que o pesquisador escolha os pacientes com melhor resposta, aumentando a eficácia aparente do fármaco"], "gabarito": "A", "justificativa": "Randomização distribui os participantes ao acaso, reduzindo a chance de que diferenças entre grupos expliquem o resultado. O grupo controle continua necessário para a comparação (resumo: Fase II, desenho randomizado).", "tecnica": "Randomização e grupo controle", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um estudo de fase III é desenhado para um anti-hipertensivo. Qual é o objetivo central e o desenho esperado?", "alternativas": ["Descobrir o alvo molecular do fármaco, usando modelos celulares e animais em um único centro de pesquisa", "Testar a primeira dose em voluntários sadios, com escalonamento para determinar a dose máxima tolerada", "Monitorar reações raras após a comercialização, sem grupo controle e sem randomização dos participantes", "Comparar apenas a farmacocinética em pacientes, sem avaliar desfechos clínicos relevantes para a população", "Confirmar eficácia e segurança em população ampla, randomizado e duplo-cego"], "gabarito": "E", "justificativa": "Fase III confirma eficácia e segurança em centenas a milhares de pacientes, em vários centros, com randomização, duplo-cego e comparador. Os estudos pivotais formam a base do registro (resumo: Fase III).", "tecnica": "Fase III: objetivos", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um fármaco aprovado após estudos com 3.000 pacientes passa a ser usado por milhões. Após dois anos, aparece um efeito cardiovascular raro, que não surgiu nos ensaios. Qual fase detecta esse tipo de evento, e por quê?", "alternativas": ["Fase I, porque a farmacocinética em voluntários sadios revela todas as reações adversas possíveis do fármaco", "Fase II, porque a dose-resposta em pacientes mostra todos os eventos raros, mesmo com amostra pequena", "Pré-clínica, porque os modelos animais reproduzem fielmente todos os eventos cardiovasculares humanos", "Fase IV, porque milhares a milhões de usuários em uso real permitem detectar reações raras ou tardias", "Fase III, porque o duplo-cego detecta eventos raros automaticamente ao comparar grupo e placebo"], "gabarito": "D", "justificativa": "A fase IV é contínua e usa a população real. Reações raras só são detectáveis em larga escala, como no rofecoxibe, retirado em 2004 (resumo: Fase IV).", "tecnica": "Fase IV: eventos raros", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Após a fase III, o patrocinador apresenta o dossiê à agência reguladora. Qual é o conjunto de critérios que a agência avalia para o registro?", "alternativas": ["Qualidade, segurança com dados de todas as fases, eficácia dos estudos pivotais, relação benefício-risco e bula", "Apenas o preço do medicamento e a embalagem, porque a eficácia já foi comprovada pelo laboratório na fase II", "Apenas a patente e o nome comercial, porque o registro é um procedimento administrativo sem avaliação científica", "Apenas o número de voluntários da fase I, porque a agência não avalia dados de pacientes em estudos clínicos", "Apenas a farmacocinética em animais, porque o registro depende exclusivamente de estudos pré-clínicos"], "gabarito": "A", "justificativa": "A agência avalia qualidade, segurança, eficácia, relação benefício-risco, bula e inspeção de Boas Práticas de Fabricação. A decisão não encerra a avaliação, que continua na fase IV (resumo: Registro).", "tecnica": "Registro sanitário", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um estudo pré-clínico de toxicologia usa duas espécies animais e reduz o número de animais por meio de modelagem computacional. Qual é o princípio que orienta essa conduta, e qual é o nome das boas práticas que regem os estudos?", "alternativas": ["Princípio da randomização e Boas Práticas Clínicas (BPC), com duplo-cego em todos os estudos animais", "Princípio da farmacovigilância e Boas Práticas de Fabricação (BPF), restritas ao controle de lotes", "Princípio dos 3Rs (substituir, reduzir, refinar) e Boas Práticas de Laboratório (BPL)", "Princípio da bioequivalência e Lei 9.787, que regula o uso de animais em estudos de genéricos", "Princípio da eficácia e Boas Práticas de Farmacovigilância, exigidas apenas para a fase IV"], "gabarito": "C", "justificativa": "Estudos pré-clínicos seguem os 3Rs e as Boas Práticas de Laboratório, em geral em duas espécies (roedor e não roedor). A modelagem in silico reduz o uso de animais (resumo: Pré-clínica).", "tecnica": "Pré-clínica: espécies e 3Rs", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Antes de incluir o primeiro participante humano, um patrocinador precisa de autorizações. Qual alternativa descreve corretamente as instâncias envolvidas no Brasil?", "alternativas": ["O CEP aprova o registro do medicamento, e a Anvisa avalia apenas o preço e a embalagem do produto", "A Anvisa dispensa a análise do dossiê quando há ensaio em voluntários, e o CEP só atua após a fase IV", "O FDA é a única autoridade no Brasil e aprova diretamente o consentimento do participante sem comitê de ética", "Anvisa analisa o dossiê clínico e o sistema CEP/Conep avalia riscos e aprova o TCLE", "O TCLE é aprovado pelo laboratório, sem participação da agência reguladora nem de comitês de ética"], "gabarito": "D", "justificativa": "No Brasil, a Anvisa analisa o dossiê de desenvolvimento clínico (DDCM), e o sistema CEP/Conep avalia riscos e benefícios e aprova o TCLE. As Boas Práticas Clínicas (ICH E6) regem os ensaios (resumo: Ponte para os humanos).", "tecnica": "Ponte para os humanos", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Em uma fase II, a queda da PA com 10 mg é de 5 mmHg, com 20 mg é de 8 mmHg e com 40 mg é de 9 mmHg, sem ganho clínico extra acima de 20 mg, mas com mais efeitos adversos. Qual decisão de desenvolvimento é mais coerente?", "alternativas": ["Escolher a dose de 40 mg para a fase III, porque a maior queda da PA sempre indica o melhor fármaco", "Registrar o fármaco já na fase II, com a dose de 10 mg, porque a fase III é desnecessária para qualquer dose", "Suspender o programa, porque qualquer variação de dose na fase II indica falha total do candidato", "Escolher a dose de 20 mg para a fase III, pela melhor relação entre eficácia e efeitos adversos", "Escolher a dose de 10 mg e repetir a fase I, porque a relação dose-resposta só é estudada em voluntários sadios"], "gabarito": "D", "justificativa": "A fase II estabelece a relação dose-resposta e o esquema posológico. Uma dose que entrega eficácia sem ganho adicional e com mais efeitos adversos é a escolha mais coerente (resumo: Fase II, dose-resposta).", "tecnica": "Fase II: dose-resposta", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um estudo de fase III é descrito como pivotal. O que esse termo significa, e por que ele é central para o registro?", "alternativas": ["É o estudo de farmacovigilância pós-comercialização, feito com pacientes que já usam o fármaco em casa", "É o estudo pré-clínico em animais, que define a margem de segurança e dispensa qualquer estudo em humanos", "É o estudo de fase I com voluntários sadios, que determina a meia-vida e o clearance do novo fármaco", "É o estudo de bioequivalência com genérico, que compara a biodisponibilidade com o produto de referência", "Estudo confirmatório randomizado e duplo-cego; base do pedido de registro"], "gabarito": "E", "justificativa": "Estudos pivotais são os confirmatórios da fase III, randomizados, duplo-cegos e multicêntricos. Seus resultados formam a base principal do pedido de registro (resumo: Fase III, registro).", "tecnica": "Estudo pivotal", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Em um estudo de fase I, os voluntários recebem primeiro uma dose única crescente e depois doses repetidas crescentes. Quais são os nomes desses desenhos, e o que cada um avalia?", "alternativas": ["SAD (estudo de placebo) e MAD (estudo de eficácia), avaliando apenas o efeito terapêutico final do fármaco", "SAD (dose única crescente) e MAD (doses múltiplas crescentes), avaliando tolerabilidade e acúmulo", "SAD (estudo de fase IV) e MAD (estudo pré-clínico), avaliando apenas eventos raros em animais de laboratório", "SAD (bioequivalência) e MAD (eficácia), avaliando apenas a equivalência entre marca e genérico", "SAD (estudo randomizado) e MAD (estudo de coorte), avaliando apenas a incidência de doenças em população"], "gabarito": "B", "justificativa": "SAD é single ascending dose (dose única crescente) e MAD é multiple ascending dose (doses repetidas crescentes). Avaliam segurança, tolerabilidade e farmacocinética (resumo: Fase I, conceitos).", "tecnica": "Fase I: SAD e MAD", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um fármaco é absorvido em menor quantidade quando tomado após refeição gordurosa, na fase I. Qual conceito descreve essa avaliação, e por que ela importa para a prescrição?", "alternativas": ["Efeito placebo, que mostra que a alimentação não altera a absorção do fármaco e dispensa qualquer orientação", "Food effect: influência da alimentação na exposição ao fármaco", "Efeito nocebo, que mostra que a refeição piora o efeito do fármaco, e por isso o fármaco deve ser suspenso", "Bioequivalência, que compara a alimentação do paciente com a do referência para validar o genérico", "Farmacovigilância, que registra a alimentação dos pacientes após o registro, sem relação com a absorção"], "gabarito": "B", "justificativa": "Food effect avalia a influência da alimentação na exposição ao fármaco. A informação orienta a administração, por exemplo, em jejum ou com refeição (resumo: Fase I, conceitos).", "tecnica": "Food effect e fase I", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um estudo de fase III inclui pacientes de diferentes centros, idades e comorbidades. Um pesquisador afirma que a diversidade enfraquece o estudo. Qual é a crítica mais precisa?", "alternativas": ["A diversidade impede a randomização, porque cada centro precisa de um placebo diferente para ser comparável", "A diversidade é dispensável na fase III, porque a fase IV corrige qualquer falha de representatividade", "Generaliza os resultados e detecta reações menos frequentes", "A diversidade aumenta o risco de morte, e por isso a fase III deve incluir apenas pacientes jovens e saudáveis", "A diversidade só importa em animais, porque em humanos a eficácia é a mesma em todas as populações"], "gabarito": "C", "justificativa": "A fase III busca confirmar a eficácia e a segurança em população ampla e diversa, para generalizar os resultados e detectar reações adversas menos frequentes (resumo: Fase III, objetivos).", "tecnica": "Fase III e população diversa", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um estudo de fase II relata redução média de 8 mmHg no grupo do fármaco e 3 mmHg no grupo controle. Qual é a diferença atribuível ao fármaco, e o que ela sugere?", "alternativas": ["Diferença de 11 mmHg, que sugere toxicidade do fármaco por queda excessiva da pressão arterial", "Diferença de 3 mmHg, que sugere que o fármaco é equivalente ao controle e deve ser abandonado", "Diferença de 5 mmHg, que sugere atividade terapêutica do fármaco em relação ao controle", "Diferença de 8 mmHg, que indica que o controle não teve efeito algum e o estudo é inválido", "Diferença de 0 mmHg, que indica que o fármaco não tem efeito, porque a diferença deve ser sempre nula"], "gabarito": "C", "justificativa": "A diferença entre o grupo tratado e o controle é de 8 − 3 = 5 mmHg. Essa diferença sugere atividade terapêutica, a ser confirmada nas fases seguintes (resumo: Fase II, exemplo numérico).", "tecnica": "Eficácia e fase IV: cálculo", "slide": null}], "id": "farma-gilmar-03", "titulo": "Aula 3", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-04"] = {"subtitulo": "Colinérgicos e anticolinérgicos, anticolinesterásicos e nicotínicos", "pdf": "pdf/gilmar/aula-04.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 4 · Colinérgicos e Anticolinérgicos (Prof. Dr. Gilmar S. Erzinger)", "Brunton e Knollmann (Goodman & Gilman); Katzung (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página.", "Slides e transcrição da aula, Prof. Dr. Gilmar S. Erzinger (resumo completo)"], "tabela": {"titulo": "Receptores colinérgicos (slide 8)", "colunas": ["Tipo", "Localização principal", "Mecanismo", "Efeito da ativação"], "linhas": [["M1", "SNC, gânglios, células parietais", "Gq → IP3/DAG, ↑Ca²⁺", "Cognição, ↑ secreção gástrica"], ["M2", "Coração (nós SA e AV)", "Gi → ↓AMPc, abre canais K⁺", "↓ frequência cardíaca, ↓ condução AV"], ["M3", "Músculo liso, glândulas, endotélio", "Gq → IP3/DAG, ↑Ca²⁺", "Contração, secreção, vasodilatação via NO"], ["M4 / M5", "SNC", "Gi / Gq", "Modulação central"], ["NN", "Gânglios, medula adrenal, SNC", "Canal iônico (Na⁺/K⁺)", "Despolarização ganglionar, liberação de catecolaminas"], ["NM", "Placa motora", "Canal iônico (Na⁺/K⁺)", "Contração do músculo esquelético"]]}, "resumo": [{"titulo": "1. Onde a acetilcolina atua no sistema nervoso autônomo", "pontos": [{"t": "Parassimpático e simpático", "sub": ["O parassimpático tem origem craniossacral (nervos III, VII, IX, X e S2 a S4). Os gânglios ficam próximos ou dentro do órgão-alvo. O neurônio pré-ganglionar libera acetilcolina (ACh), que age no receptor nicotínico (NN). O pós-ganglionar libera ACh, que age no receptor muscarínico. É o sistema de 'repouso e digestão'.", "O simpático tem origem toracolombar (T1 a L2). Os gânglios são paravertebrais e pré-vertebrais. O pré-ganglionar também usa ACh e NN. O pós-ganglionar libera noradrenalina, que age em receptores α e β. Exceções importantes: as glândulas sudoríparas são inervadas por fibras simpáticas colinérgicas (receptor M3), e a medula adrenal, que é um gânglio modificado, libera adrenalina.", "Regra prática: o simpático prepara para luta ou fuga; o parassimpático conserva energia. Os dois atuam de forma oposta em muitos órgãos."]}, {"t": "Por que isso importa para a farmacologia", "sub": ["Todo fármaco colinérgico ou simpático age em um desses pontos: no gânglio (NN), no órgão-alvo muscarínico (M), na placa motora (NM) ou no SNC. Saber onde a ACh atua permite prever o efeito de cada fármaco."]}]}, {"titulo": "2. O ciclo da acetilcolina: cinco etapas e seus alvos", "pontos": [{"t": "Síntese e captação", "sub": ["Captação de colina: o transportador CHT depende de sódio. Esta é a etapa limitante do ciclo e é bloqueada pelo hemicolínio.", "Síntese: a colina acetiltransferase (ChAT) junta acetil-CoA e colina e forma acetilcolina."]}, {"t": "Armazenamento e liberação", "sub": ["Vesículas: o transportador VAChT leva a ACh para dentro das vesículas do terminal pré-sináptico. É bloqueado pelo vesamicol.", "Liberação: um potencial de ação abre canais de Ca²⁺. A entrada de cálcio, com as proteínas SNARE, faz as vesículas liberarem a ACh na fenda. A toxina botulínica bloqueia a liberação."]}, {"t": "Ação e término", "sub": ["A ACh age nos receptores nicotínicos (resposta rápida, em gânglios e músculo esquelético) e muscarínicos (resposta nos órgãos-alvo parassimpáticos).", "Término: a acetilcolinesterase (AChE) hidrolisa a ACh em colina e acetato, em microssegundos. A colina é recaptada e reutilizada.", "Ideia central: a ACh é produzida, armazenada, liberada, age no receptor e é rapidamente degradada. Por isso a duração do efeito depende da velocidade da AChE."]}]}, {"titulo": "3. Receptores muscarínicos e nicotínicos", "pontos": [{"t": "Receptores muscarínicos (M1 a M5)", "sub": ["M1: SNC, gânglios e células parietais gástricas. É acoplado a Gq, que ativa a fosfolipase C, forma IP₃ e DAG e eleva o Ca²⁺. Efeito: cognição e aumento da secreção gástrica.", "M2: coração, nós SA e AV. É acoplado a Gi, que inibe a adenilato ciclase, reduz o AMPc e abre canais de K⁺. Efeito: queda da frequência cardíaca e da condução AV.", "M3: músculo liso, glândulas e endotélio. É acoplado a Gq. Efeito: contração do músculo liso, secreção e vasodilatação por NO endotelial.", "M4 e M5: SNC. Modulação central."]}, {"t": "Mnemônico", "sub": ["Receptores ímpares (M1, M3, M5) são acoplados a Gq. Pares (M2, M4) são acoplados a Gi.", "Gq → IP₃ e DAG → aumento de Ca²⁺. Gi → queda de AMPc e abertura de canais de K⁺."]}, {"t": "Receptores nicotínicos (NN e NM)", "sub": ["São canais iônicos, ativados pela ACh, com resposta rápida. NN: gânglios autonômicos e medula adrenal, que liberam catecolaminas. NM: placa motora, com contração do músculo esquelético.", "Diferenças: muscarínicos são acoplados à proteína G e modulam os órgãos, com resposta mais lenta. Nicotínicos são canais iônicos, com resposta rápida nos gânglios e no músculo."]}, {"t": "Efeitos da estimulação muscarínica", "sub": ["Olho: miose (esfíncter da pupila), acomodação para perto e redução da pressão intraocular.", "Coração: bradicardia e menor condução AV (M2).", "Vasos: vasodilatação via NO endotelial (M3), com queda da pressão.", "Brônquios: broncoconstrição e aumento da secreção.", "Trato gastrintestinal: aumento da motilidade e das secreções, com relaxamento de esfíncteres.", "Bexiga: contração do detrusor, o que favorece a micção.", "Glândulas: aumento da saliva, lágrima e suor."]}]}, {"titulo": "4. Agonistas colinérgicos: diretos e indiretos", "pontos": [{"t": "Agonistas diretos", "sub": ["Ligam-se diretamente aos receptores. Betanecol estimula a contração da bexiga e é usado na retenção urinária não obstrutiva e na atonia gastrointestinal pós-operatória. Pilocarpina aumenta a secreção salivar e reduz a pressão intraocular; é usada no glaucoma e na xerostomia. Carbacol age em muscarínicos e nicotínicos.", "Metacolina é hidrolisada pela AChE de forma lenta; é usada no teste de broncoprovocação para diagnóstico de asma.", "Cevimelina é agonista M1 e M3, usada na xerostomia da síndrome de Sjögren."]}, {"t": "Agonistas indiretos (anticolinesterásicos reversíveis)", "sub": ["Inibem a AChE. A ACh permanece mais tempo na fenda e potencializa todas as sinapses colinérgicas.", "Neostigmina aumenta a transmissão colinérgica; é usada na miastenia gravis, na reversão de bloqueio neuromuscular e no íleo e na retenção urinária pós-operatórios.", "Piridostigmina é usada no tratamento crônico da miastenia gravis.", "Donepezila é usada no tratamento sintomático do Alzheimer.", "Fisostigmina é terciária e atravessa a barreira hematoencefálica; é antídoto da intoxicação anticolinérgica central."]}]}, {"titulo": "5. Miastenia gravis: a ponte entre imunologia e farmacologia", "pontos": [{"t": "Fisiopatologia", "sub": ["Normalmente, o neurônio libera ACh, que se liga aos receptores nicotínicos do músculo e provoca contração.", "Na miastenia gravis, há autoanticorpos contra o receptor nicotínico da placa motora. A transmissão neuromuscular fica prejudicada. É hipersensibilidade tipo II, por bloqueio funcional (ver Imunologia, aula 8).", "Clínica: fraqueza flutuante que piora com esforço repetido e melhora com repouso. Sintomas: ptose palpebral, diplopia, dificuldade para mastigar e engolir, fala anasalada e fraqueza de braços e pernas; em casos graves, fraqueza respiratória."]}, {"t": "Tratamento e por que funciona", "sub": ["Sintomático: piridostigmina, várias vezes ao dia. Ela inibe a AChE e aumenta a ACh disponível na junção neuromuscular. Compensa o número reduzido de receptores funcionais.", "Modificadores: corticoide, imunossupressores e timectomia. Eles atuam sobre a autoimunidade. A piridostigmina não elimina os anticorpos.", "Crise: imunoglobulina IV ou plasmaférese, e suporte ventilatório."]}, {"t": "Crise miastênica × crise colinérgica", "sub": ["Crise miastênica: dose insuficiente ou piora da doença; fraqueza progressiva, inclusive respiratória; sem sinais muscarínicos; melhora com mais anticolinesterásico.", "Crise colinérgica: excesso de anticolinesterásico; fraqueza por bloqueio despolarizante; miose, sialorreia, bradicardia e fasciculações; piora com mais anticolinesterásico."]}]}, {"titulo": "6. Antagonistas muscarínicos: a síndrome anticolinérgica", "pontos": [{"t": "Atropina e a ordem de sensibilidade dos órgãos", "sub": ["Os efeitos da atropina aparecem em ordem de sensibilidade dos órgãos. Em torno de 0,5 mg: boca seca, redução da sudorese e bradicardia leve. Em torno de 1 mg: taquicardia, sede e leve midríase. Em torno de 2 mg: midríase, cicloplegia (visão turva) e palpitações. Em torno de 5 mg: retenção urinária, redução da motilidade intestinal e pele quente e seca. Acima de 10 mg: agitação, delírio, alucinações, hipertermia e coma."]}, {"t": "Indicações", "sub": ["Atropina: bradicardia sintomática, intoxicação por organofosforados e antissialagogo pré-anestésico.", "Escopolamina: cinetose (adesivo transdérmico), com efeitos centrais marcantes.", "Butilescopolamina: cólicas gastrointestinais, biliares e renais. Não atravessa a barreira hematoencefálica.", "Ipratrópio e tiotrópio: broncodilatação na DPOC. Tiotrópio é LAMA, de uso uma vez ao dia.", "Tropicamida e ciclopentolato: midríase e cicloplegia para exame oftalmológico.", "Oxibutinina, tolterodina e solifenacina: bexiga hiperativa.", "Biperideno e triexifenidil: parkinsonismo induzido por antipsicóticos e tremor de Parkinson.", "Glicopirrolato: antissialagogo, e associado à neostigmina na reversão de bloqueadores neuromusculares."]}, {"t": "Aminas terciárias × quaternárias", "sub": ["Terciárias (atropina, escopolamina, biperideno, oxibutinina, difenidramina, triexifenidil): lipossolúveis, com boa absorção oral. Atravessam a barreira hematoencefálica, com sedação, confusão e delírio.", "Quaternárias (ipratrópio, tiotrópio, butilescopolamina, glicopirrolato, neostigmina, piridostigmina): carga positiva permanente, absorção oral pobre e não atravessam a barreira. Efeitos predominantemente periféricos."]}, {"t": "Síndrome anticolinérgica", "sub": ["Seco como osso: pele e mucosas secas, sem sudorese. Vermelho como pimentão: rubor cutâneo. Quente como fogo: hipertermia. Cego como morcego: midríase e visão turva. Louco como chapeleiro: agitação, delírio e alucinações.", "Também há taquicardia, retenção urinária e íleo. Causas: atropina, plantas como a Datura (trombeteira), antidepressivos tricíclicos e anti-histamínicos de primeira geração. Antídoto: fisostigmina.", "Evitar em glaucoma de ângulo fechado, hiperplasia prostática com retenção urinária, obstrução gastrointestinal, taquiarritmias e em idosos (critérios de Beers)."]}, {"t": "Atropina no tratamento de intoxicações", "sub": ["A atropina bloqueia os receptores muscarínicos. É usada na intoxicação por organofosforados e carbamatos, que inibem a AChE e causam acúmulo de ACh. Ela reverte os efeitos muscarínicos, mas não corrige os efeitos nicotínicos, como a fraqueza muscular. Não serve como antídoto para qualquer overdose."]}]}, {"titulo": "7. Fármacos nicotínicos", "pontos": [{"t": "Agonistas e bloqueadores", "sub": ["Nicotina: ação bifásica, primeiro estimula e depois bloqueia os gânglios. Usada na reposição para cessação do tabagismo.", "Vareniclina: agonista parcial α4β2, reduz a fissura e a recompensa. Efeitos: náuseas e sonhos vívidos.", "Succinilcolina: agonista de Nm. Causa despolarização persistente da placa motora, com bloqueio neuromuscular e paralisia temporária.", "Bloqueadores ganglionares (mecamilamina e trimetafano): bloqueiam simpático e parassimpático. Uso muito restrito hoje.", "Bloqueio ganglionar: vence o tônus predominante. Arteríolas e veias (simpático): vasodilatação e hipotensão ortostática. Coração (parassimpático): taquicardia. Íris e músculo ciliar: midríase e cicloplegia. Trato gastrointestinal: constipação. Bexiga: retenção urinária. Glândulas salivares: xerostomia. Glândulas sudoríparas (colinérgicas): anidrose."]}]}, {"titulo": "8. Anticolinesterásicos: mecanismo, classificação e usos", "pontos": [{"t": "As colinesterases", "sub": ["Acetilcolinesterase (AChE): fica na fenda sináptica, na placa motora e nas hemácias. É uma das enzimas mais rápidas conhecidas. Tem subsítio aniônico, que liga o nitrogênio quaternário, e subsítio esterásico, com serina.", "Butirilcolinesterase: pseudocolinesterase plasmática, sintetizada no fígado. Metaboliza succinilcolina, mivacúrio e anestésicos locais do tipo éster."]}, {"t": "Três maneiras de inibir a AChE", "sub": ["Reversíveis (edrofônio): ligação eletrostática ao sítio aniônico. Duração de minutos. Edrofônio foi usado historicamente como teste diagnóstico de miastenia.", "Carbamatos (neostigmina, piridostigmina, fisostigmina, rivastigmina): carbamilam a serina, com hidrólise lenta. Duração de 30 minutos a 6 horas.", "Organofosforados (malation, clorpirifós, sarin, VX): fosforilam a serina de modo estável. A inibição é considerada irreversível após o envelhecimento da enzima."]}, {"t": "Usos clínicos", "sub": ["Neostigmina: reversão de bloqueadores neuromusculares adespolarizantes, miastenia gravis, retenção urinária e íleo pós-operatórios. Na reversão, deve-se associar glicopirrolato ou atropina. Não reverte bloqueio profundo (efeito teto).", "Piridostigmina: tratamento crônico da miastenia gravis.", "Donepezila, rivastigmina e galantamina: Alzheimer, com benefício sintomático modesto, sem alterar a progressão. Rivastigmina também é usada na demência da doença de Parkinson.", "Efeito teto: quando o fármaco atinge o efeito máximo, aumentar a dose não aumenta mais o efeito. É o caso de bloqueio neuromuscular profundo, em que a ACh aumentada não basta."]}]}, {"titulo": "9. Intoxicação por organofosforados e carbamatos", "pontos": [{"t": "Fontes e quadro", "sub": ["Fontes: agrotóxicos (exposição ocupacional sem EPI e tentativas de suicídio), absorção cutânea, inalatória e oral; 'chumbinho', raticida ilegal que frequentemente contém aldicarbe, um carbamato; agentes de guerra, como sarin, soman, VX e Novichok.", "Síndrome colinérgica aguda: muscarínicos (miose, sialorreia, sudorese, broncorreia e broncoespasmo, bradicardia, vômitos, diarreia e incontinência). Nicotínicos (fasciculações, cãibras, fraqueza, paralisia do diafragma, taquicardia e hipertensão ganglionar). Sistema nervoso central (ansiedade, confusão, convulsões, depressão respiratória e coma)."]}, {"t": "Conduta", "sub": ["1. Descontaminar: remover as roupas e lavar a pele com água e sabão; a equipe usa EPI.", "2. Via aérea: oxigênio e intubação se necessário. Evitar succinilcolina.", "3. Atropina: 1 a 2 mg IV, dobrando a dose a cada 5 minutos até secar as secreções brônquicas. Esse é o alvo da titulação, não a frequência cardíaca.", "4. Pralidoxima: reativa a AChE, antes do envelhecimento da enzima, e atua também nos efeitos nicotínicos. O tempo é a enzima: para o soman, o envelhecimento ocorre em minutos; para inseticidas, em horas.", "5. Convulsões: diazepam ou midazolam IV.", "Carbamatos: quadro mais curto, e a enzima não envelhece. Por isso não exigem a mesma urgência com a oxima.", "Diagnóstico: clínico, confirmado por colinesterase eritrocitária ou plasmática. Complicações: síndrome intermediária 24 a 96 horas após a crise (fraqueza proximal, pares cranianos e respiratória) e neuropatia tardia 1 a 3 semanas depois (polineuropatia sensitivo-motora distal)."]}, {"t": "Diferencial rápido", "sub": ["Colinérgica: miose e tudo molhado. Anticolinérgica: midríase e tudo seco. Na intoxicação simpatomimética, a pele é fria e úmida, diferente da síndrome anticolinérgica, que é quente e seca."]}]}, {"titulo": "10. Pontos-chave e casos da aula", "pontos": [{"t": "Casos discutidos em aula", "sub": ["Caso da trombeteira: jovem agitado, confuso, com alucinações, pele quente e seca, pupilas midriáticas, taquicardia e bexiga palpável. Síndrome anticolinérgica pela Datura. Conduta: suporte, controle de temperatura, benzodiazepínico para agitação e fisostigmina em casos selecionados.", "Caso do agricultor: sudorese, sialorreia, vômitos, pupilas puntiformes, broncorreia, bradicardia e fasciculações, após pulverização sem EPI. Síndrome colinérgica por organofosforado. Confirmação por colinesterase. Conduta: descontaminação, atropina titulada pela secagem brônquica e pralidoxima precoce."]}, {"t": "Pontos-chave", "sub": ["A ACh atua em todos os gânglios, nas fibras pós-ganglionares parassimpáticas e na placa motora.", "Muscarínicos são acoplados à proteína G; nicotínicos são canais iônicos.", "Betanecol e pilocarpina são os agonistas muscarínicos mais usados.", "Os efeitos da atropina surgem em ordem de sensibilidade dos órgãos.", "Terciários atravessam a barreira hematoencefálica; quaternários atuam só na periferia.", "Seco, vermelho, quente, cego e louco: síndrome anticolinérgica.", "Anticolinesterásicos aumentam a ACh em todas as sinapses colinérgicas. Reversíveis, carbamatos e organofosforados diferem na duração.", "Na intoxicação, a atropina é titulada pela secagem brônquica. As oximas devem ser dadas antes do envelhecimento da enzima."]}]}], "glossario": [{"termo": "Efeito teto", "tecnica": "Reversão de bloqueio neuromuscular", "definicao": "Limite de eficácia: aumentar a dose não aumenta o efeito, em bloqueio profundo.", "slide": 28}, {"termo": "Crise colinérgica", "tecnica": "Excesso de anticolinesterásico", "definicao": "Miose, sialorreia, bradicardia e fasciculações; piora com mais anticolinesterásico.", "slide": 26}, {"termo": "Envelhecimento da AChE", "tecnica": "Organofosforados", "definicao": "Fosforilação estável da serina; a oxima só reativa a enzima antes desse processo.", "slide": 56}, {"termo": "Síndrome anticolinérgica", "tecnica": "Toxicidade", "definicao": "Quadro de pele seca e quente, midríase, taquicardia, retenção urinária e delírio.", "slide": 38}, {"termo": "Aminas quaternárias", "tecnica": "Farmacocinética", "definicao": "Carga positiva permanente; absorção oral pobre e não atravessam a BHE.", "slide": 37}, {"termo": "Pralidoxima", "tecnica": "Antídoto", "definicao": "Oxima que reativa a AChE inibida por organofosforados, nos efeitos nicotínicos.", "slide": 55}, {"termo": "Síndrome de Sjögren (epônimo: Sjögren)", "tecnica": "Colinérgicos", "definicao": "Causa de xerostomia; a aula cita pilocarpina e cevimelina para o quadro.", "slide": 29}, {"termo": "Critérios de Beers (epônimo: Beers)", "tecnica": "Antimuscarínicos", "definicao": "Critérios que alertam contra anticolinérgicos em idosos; a aula cita a síndrome anticolinérgica.", "slide": 38}, {"termo": "Acetilcolina (ACh)", "tecnica": "Neurotransmissor", "definicao": "Neurotransmissor do parassimpático, do simpático pré-ganglionar e da placa motora. Hidrolisada pela AChE.", "slide": 5}, {"termo": "Colina acetiltransferase (ChAT)", "tecnica": "Síntese", "definicao": "Enzima que une acetil-CoA e colina para formar ACh no neurônio.", "slide": 5}, {"termo": "Transportador de colina (CHT)", "tecnica": "Captação", "definicao": "Transportador Na⁺-dependente que capta colina. Etapa limitante, bloqueada pelo hemicolínio.", "slide": 5}, {"termo": "Hemicolínio", "tecnica": "Fármaco", "definicao": "Bloqueia a captação de colina, a etapa limitante da síntese de ACh.", "slide": 5}, {"termo": "VAChT e vesamicol", "tecnica": "Armazenamento", "definicao": "VAChT leva a ACh para as vesículas. Vesamicol bloqueia esse transportador.", "slide": 5}, {"termo": "SNARE e toxina botulínica", "tecnica": "Liberação", "definicao": "Proteínas que fazem a vesícula se fundir à membrana. A toxina botulínica impede essa liberação.", "slide": 5}, {"termo": "Acetilcolinesterase (AChE)", "tecnica": "Degradação", "definicao": "Enzima que hidrolisa a ACh em colina e acetato em microssegundos. Alvo dos anticolinesterásicos.", "slide": 5}, {"termo": "Receptor muscarínico M1", "tecnica": "Receptor (Gq)", "definicao": "No SNC, gânglios e células parietais. Via Gq, com IP₃, DAG e aumento de Ca²⁺. Aumenta a secreção gástrica.", "slide": 8}, {"termo": "Receptor muscarínico M2", "tecnica": "Receptor (Gi)", "definicao": "No coração (nós SA e AV). Via Gi, com queda de AMPc e abertura de canais de K⁺. Reduz a frequência cardíaca e a condução AV.", "slide": 8}, {"termo": "Receptor muscarínico M3", "tecnica": "Receptor (Gq)", "definicao": "Em músculo liso, glândulas e endotélio. Causa contração, secreção e vasodilatação via NO.", "slide": 8}, {"termo": "Receptores M4 e M5", "tecnica": "Receptor (Gi/Gq)", "definicao": "No SNC, para modulação central. M4 é Gi; M5 é Gq.", "slide": 8}, {"termo": "Receptor nicotínico NN", "tecnica": "Receptor (canal)", "definicao": "Nos gânglios autonômicos, medula adrenal e SNC. Canal de Na⁺/K⁺ que despolariza o gânglio e libera catecolaminas.", "slide": 8}, {"termo": "Receptor nicotínico NM", "tecnica": "Receptor (canal)", "definicao": "Na placa motora do músculo esquelético. Canal que causa contração.", "slide": 8}, {"termo": "Gq, IP₃ e DAG", "tecnica": "Via de sinalização", "definicao": "Via dos receptores ímpares. IP₃ libera Ca²⁺ do retículo; DAG ativa a PKC.", "slide": 9}, {"termo": "Gi e canais de K⁺ (GIRK)", "tecnica": "Via de sinalização", "definicao": "Via dos receptores pares. Inibe a adenilato ciclase e abre canais de K⁺, causando hiperpolarização.", "slide": 11}, {"termo": "Óxido nítrico (NO)", "tecnica": "Mediador", "definicao": "Produzido pelo endotélio. Ativa a guanilato ciclase, aumenta o GMPc e causa vasodilatação.", "slide": 13}, {"termo": "Catecolaminas (dopamina, noradrenalina e adrenalina)", "tecnica": "Neurotransmissores", "definicao": "Atuam como neurotransmissores e hormônios. Dopamina: movimento e recompensa. Noradrenalina: atenção e alerta. Adrenalina: estresse.", "slide": 14}, {"termo": "Miastenia gravis", "tecnica": "Doença", "definicao": "Doença autoimune com autoanticorpos contra o receptor nicotínico da placa motora. Fraqueza que piora com esforço.", "slide": 23}, {"termo": "Piridostigmina", "tecnica": "Anticolinesterásico", "definicao": "Inibe a AChE e aumenta a ACh na junção neuromuscular. Tratamento sintomático da miastenia.", "slide": 23}, {"termo": "Neostigmina", "tecnica": "Anticolinesterásico", "definicao": "Carbamato que aumenta a ACh. Usado na reversão de bloqueadores neuromusculares e na miastenia.", "slide": 21}, {"termo": "Donepezila, galantamina e rivastigmina", "tecnica": "Anticolinesterásico", "definicao": "Inibidores da AChE usados no Alzheimer. Rivastigmina também na demência da doença de Parkinson.", "slide": 21}, {"termo": "Pilocarpina", "tecnica": "Agonista muscarínico", "definicao": "Agonista direto de M. Aumenta a secreção salivar e reduz a pressão intraocular. Usada no glaucoma e na xerostomia.", "slide": 20}, {"termo": "Betanecol", "tecnica": "Agonista muscarínico", "definicao": "Agonista muscarínico resistente à AChE. Estimula a bexiga e o intestino. Usado na atonia vesical e gastrointestinal.", "slide": 20}, {"termo": "Carbacol", "tecnica": "Agonista muscarínico", "definicao": "Agonista de receptores M e N. Resistente à AChE. Usado na miose cirúrgica e no glaucoma.", "slide": 20}, {"termo": "Metacolina", "tecnica": "Agonista muscarínico", "definicao": "Agonista M com hidrólise lenta. Usada no teste de broncoprovocação para diagnóstico de asma.", "slide": 29}, {"termo": "Cevimelina", "tecnica": "Agonista muscarínico", "definicao": "Agonista M1/M3, usado na xerostomia da síndrome de Sjögren.", "slide": 29}, {"termo": "Atropina", "tecnica": "Antagonista muscarínico", "definicao": "Antagonista muscarínico competitivo. Reverte os efeitos muscarínicos, mas não os nicotínicos. Antídoto de organofosforados e carbamatos.", "slide": 30}, {"termo": "Escopolamina", "tecnica": "Antagonista muscarínico", "definicao": "Amina terciária que atravessa a BHE. Usada na cinetose, em adesivo transdérmico.", "slide": 33}, {"termo": "Butilescopolamina (butilbrometo)", "tecnica": "Antagonista muscarínico", "definicao": "Amina quaternária que não atravessa a BHE. Usada em cólicas gastrointestinais, biliares e renais.", "slide": 33}, {"termo": "Ipratrópio e tiotrópio", "tecnica": "Antagonista muscarínico", "definicao": "Quaternários broncodilatadores. Tiotrópio é LAMA de uso diário, na DPOC.", "slide": 33}, {"termo": "Tropicamida e ciclopentolato", "tecnica": "Antagonista muscarínico", "definicao": "Usados para midríase e cicloplegia no exame oftalmológico.", "slide": 33}, {"termo": "Oxibutinina, tolterodina e solifenacina", "tecnica": "Antagonista muscarínico", "definicao": "Usados na bexiga hiperativa, com incontinência de urgência.", "slide": 33}, {"termo": "Biperideno e triexifenidil", "tecnica": "Antagonista muscarínico", "definicao": "Usados no parkinsonismo induzido por antipsicóticos e no tremor da doença de Parkinson.", "slide": 33}, {"termo": "Glicopirrolato", "tecnica": "Antagonista muscarínico", "definicao": "Quaternário antissialagogo. Associado à neostigmina para reverter bloqueadores neuromusculares.", "slide": 33}, {"termo": "Aminas terciárias e quaternárias", "tecnica": "Farmacocinética", "definicao": "Terciárias são lipossolúveis e atravessam a BHE. Quaternárias são carregadas e atuam na periferia.", "slide": 37}, {"termo": "Datura (trombeteira)", "tecnica": "Planta", "definicao": "Planta com atropina e escopolamina, causa de síndrome anticolinérgica.", "slide": 44}, {"termo": "Nicotina", "tecnica": "Agonista nicotínico", "definicao": "Ação bifásica: estimula e depois bloqueia os gânglios. Usada na reposição para cessar o tabagismo.", "slide": 40}, {"termo": "Vareniclina", "tecnica": "Agonista nicotínico", "definicao": "Agonista parcial α4β2 que reduz a fissura e a recompensa. Usada na cessação do tabagismo.", "slide": 40}, {"termo": "Succinilcolina", "tecnica": "Agonista nicotínico", "definicao": "Agonista NM que causa despolarização persistente da placa motora, com paralisia temporária.", "slide": 42}, {"termo": "Mecamilamina e trimetafano", "tecnica": "Bloqueador ganglionar", "definicao": "Bloqueiam os gânglios do simpático e do parassimpático. Uso muito restrito.", "slide": 40}, {"termo": "Butirilcolinesterase (pseudocolinesterase)", "tecnica": "Enzima", "definicao": "Enzima plasmática sintetizada no fígado. Hidrolisa succinilcolina, mivacúrio e anestésicos do tipo éster.", "slide": 48}, {"termo": "Edrofônio", "tecnica": "Anticolinesterásico", "definicao": "Inibidor reversível de ação curta (5 a 15 min). Teste diagnóstico de miastenia, no passado.", "slide": 50}, {"termo": "Fisostigmina", "tecnica": "Anticolinesterásico", "definicao": "Carbamato terciário que atravessa a BHE. Usado na intoxicação anticolinérgica com delírio.", "slide": 51}, {"termo": "Organofosforados (malation, clorpirifós, sarin, VX)", "tecnica": "Anticolinesterásico", "definicao": "Fosforilam a AChE de modo estável. Inibição irreversível após o envelhecimento da enzima.", "slide": 50}, {"termo": "Carbamatos (aldicarbe e outros)", "tecnica": "Anticolinesterásico", "definicao": "Carbamilam a AChE, com inibição de 30 min a 6 h. Aldicarbe está no chumbinho.", "slide": 50}, {"termo": "Chumbinho", "tecnica": "Exposição", "definicao": "Raticida ilegal que frequentemente contém aldicarbe. Causa comum de intoxicação no Brasil.", "slide": 53}, {"termo": "Envelhecimento da enzima (organofosforados)", "tecnica": "Conceito", "definicao": "Perda da reativação da AChE por oximas, após a fosforilação estável. Tempo é enzima.", "slide": 56}, {"termo": "Síndrome intermediária", "tecnica": "Complicação", "definicao": "Fraqueza proximal, de pares cranianos e respiratória, de 24 a 96 horas após a crise colinérgica.", "slide": 56}, {"termo": "Neuropatia tardia por organofosforado", "tecnica": "Complicação", "definicao": "Polineuropatia sensitivo-motora distal, de 1 a 3 semanas, pela esterase neurotóxica.", "slide": 56}, {"termo": "SLUDGE", "tecnica": "Mnemônico", "definicao": "Excesso muscarínico: salivação, lacrimejamento, urina, diarreia, cólica e êmese.", "slide": 30}, {"termo": "Gq e Gi (mnemônico dos receptores)", "tecnica": "Mnemônico", "definicao": "Receptores ímpares (M1, M3, M5) são Gq. Pares (M2, M4) são Gi.", "slide": 8}], "caso": {"titulo": "Caso: chá de trombeteira", "perfil": "Síndrome anticolinérgica por Datura.", "etapas": [{"titulo": "Etapa 1: síndrome", "texto": "Jovem de 22 anos, após festa e chá de trombeteira, agitado e confuso, com alucinações visuais. Pele quente, seca e avermelhada; pupilas midriáticas e pouco reativas; FC 132 bpm; temperatura 38,9 °C; bexiga palpável; ruídos hidroaéreos diminuídos.", "perguntas": [{"pergunta": "Qual é a síndrome tóxica, segundo a aula?", "alts": ["Síndrome anticolinérgica", "Síndrome colinérgica por organofosforado", "Síndrome simpatomimética por anfetamina", "Síndrome da crise miastênica", "Síndrome serotoninérgica por inibidor da MAO"], "erradas": ["Síndrome colinérgica tem miose, sialorreia e bradicardia, o oposto do quadro.", "Simpatomimético causa midríase, mas com sudorese e taquicardia típicas.", "Crise miastênica é fraqueza sem sinais muscarínicos.", "Serotoninérgica não é a síndrome descrita para trombeteira."], "justificativa": "Seco como osso, vermelho, quente, cego e louco: síndrome anticolinérgica, causada por plantas como a Datura (slide 38)."}]}, {"titulo": "Etapa 2: mecanismo e conduta", "texto": "A equipe pergunta qual é o mecanismo do quadro e qual o papel da atropina nesse caso.", "perguntas": [{"pergunta": "Qual é o mecanismo mais adequado para o quadro?", "alts": ["Bloqueio dos receptores muscarínicos pela escopolamina e atropina da planta", "Inibição da acetilcolinesterase, com excesso de ACh na sinapse", "Ativação de receptores nicotínicos, com fasciculações generalizadas", "Bloqueio de receptores beta, com bradicardia intensa", "Inibição da MAO, com acúmulo de serotonina no SNC"], "erradas": ["Inibição da AChE é o mecanismo do organofosforado, não da trombeteira.", "Ativação nicotínica causa fasciculações, que não são o quadro descrito.", "Bloqueio beta causa bradicardia, e não taquicardia com pele quente.", "Inibição da MAO não é o mecanismo da síndrome anticolinérgica."], "justificativa": "Os alcaloides da planta bloqueiam os receptores muscarínicos, como a atropina (slides 34 e 38)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Jovem, paciente T.R., 22 anos, levado ao pronto-socorro após ingerir chá de trombeteira. Apresenta agitação, alucinações visuais, pele quente, seca e avermelhada, pupilas midriáticas e pouco reativas, FC 132 bpm, temperatura 38,9 °C e retenção urinária. Qual é o mecanismo e o fármaco que reverte o quadro?", "alternativas": ["Excesso de ACh pela Datura; atropina em dose alta, que bloqueia a AChE e reverte a midríase do paciente", "Bloqueio nicotínico pela Datura; succinilcolina, que despolariza a placa motora e reverte a agitação", "Excesso de noradrenalina pela Datura; propranolol em dose alta, que bloqueia os receptores β e reverte a taquicardia", "Bloqueio muscarínico pela Datura; fisostigmina, anticolinesterásico que atravessa a barreira hematoencefálica", "Excesso de dopamina pela Datura; haloperidol em dose alta, que bloqueia os receptores D2 e controla a agitação"], "gabarito": "D", "justificativa": "A Datura causa síndrome anticolinérgica por bloqueio muscarínico: seco, vermelho, quente, cego e louco. Antídoto: fisostigmina, terciária que atravessa a barreira hematoencefálica (resumo: Antagonistas muscarínicos).", "tecnica": "Trombeteira e síndrome anticolinérgica", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Agricultor, paciente L.B., 45 anos, 1 hora após pulverizar a lavoura sem EPI. Apresenta sudorese profusa, sialorreia, vômitos, diarreia, pupilas puntiformes, sibilos e fasciculações em panturrilhas. FC 48 bpm e SatO₂ 86%. Qual é o diagnóstico sindrômico e a primeira conduta?", "alternativas": ["Síndrome colinérgica por organofosforado; descontaminação, oxigênio e atropina titulada pela secagem das secreções", "Síndrome anticolinérgica por antidepressivo; fisostigmina em dose alta e observação em ambiente sem estímulos", "Crise miastênica por dose insuficiente de piridostigmina; aumentar a dose do anticolinesterásico no mesmo momento", "Síndrome simpatomimética por anfetamina; propranolol em dose alta e resfriamento corporal ativo do paciente", "Intoxicação por monóxido de carbono; oxigenoterapia hiperbárica, sem atropina nem qualquer medida de descontaminação"], "gabarito": "A", "justificativa": "Miose, sialorreia, bradicardia, broncorreia e fasciculações indicam síndrome colinérgica. Conduta: descontaminar, garantir a via aérea e titular atropina até secar as secreções brônquicas (resumo: Intoxicação por organofosforado).", "tecnica": "Agricultor e organofosforado", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "No mesmo caso de intoxicação por organofosforado, a equipe discute a pralidoxima. Por que o tempo de administração é tão importante, e qual é o efeito que ela também tem?", "alternativas": ["A pralidoxima só funciona após 24 horas, porque precisa ser metabolizada pelo fígado antes de agir", "A pralidoxima bloqueia os receptores muscarínicos, e por isso deve ser dada antes da atropina sempre", "A pralidoxima é anticolinérgica e piora a broncorreia, por isso só é usada depois que o paciente recupera a consciência", "A AChE envelhece e não pode mais ser reativada; a pralidoxima também atua sobre os efeitos nicotínicos", "A pralidoxima serve apenas para o efeito cardíaco, sem ação sobre a junção neuromuscular do paciente"], "gabarito": "D", "justificativa": "Pralidoxima reativa a AChE, mas só antes do envelhecimento da enzima, que varia de minutos (soman) a horas (inseticidas). Também atua nos efeitos nicotínicos (resumo: Intoxicação).", "tecnica": "Pralidoxima e tempo", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Mulher, paciente C.N., 39 anos, com miastenia gravis em uso de piridostigmina. Após duas semanas, apresenta sialorreia, miose, bradicardia e fasciculações, com piora da fraqueza. Qual é o diagnóstico e a conduta farmacológica?", "alternativas": ["Crise miastênica por dose insuficiente; aumentar a piridostigmina, porque a fraqueza progressiva indica dose baixa", "Remissão da miastenia, porque a sialorreia e a miose indicam recuperação da junção neuromuscular da paciente", "Excesso de anticolinesterásico; reduzir a piridostigmina e tratar sinais muscarínicos", "Síndrome anticolinérgica por antidepressivo; fisostigmina em dose alta e suspensão de qualquer anticolinesterásico", "Infecção do SNC por efeito colateral da piridostigmina; antibiótico de amplo espectro e punção lombar imediata"], "gabarito": "C", "justificativa": "Excesso de anticolinesterásico causa crise colinérgica: sinais muscarínicos presentes e piora com mais fármaco. Na crise miastênica, a dose é insuficiente e os sinais muscarínicos estão ausentes (resumo: Crises na miastenia).", "tecnica": "Miastenia e crise", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um estudante afirma que a piridostigmina cura a miastenia gravis porque 'restaura os receptores nicotínicos bloqueados'. Qual é a correção mais precisa?", "alternativas": ["A piridostigmina destrói os autoanticorpos no plasma e, por isso, é o tratamento modificador definitivo da doença", "Inibe a AChE, aumenta a ACh e não elimina os autoanticorpos", "A piridostigmina estimula a produção de novos receptores nicotínicos na placa motora, curando a doença", "A piridostigmina bloqueia os receptores muscarínicos e impede a ação dos anticorpos sobre a placa motora", "A piridostigmina inibe a calcineurina nos linfócitos, o que elimina a fonte dos autoanticorpos"], "gabarito": "B", "justificativa": "Piridostigmina é sintomática: aumenta a ACh disponível. Não elimina os autoanticorpos. Os modificadores são corticoide, imunossupressores e timectomia (resumo: Miastenia gravis).", "tecnica": "Miastenia: o que a piridostigmina faz", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um anticolinesterásico é classificado como carbamato, com carbamilação da serina e hidrólise lenta. Qual é a diferença de duração e de necessidade de oxima em relação a um organofosforado?", "alternativas": ["Carbamatos duram dias e envelhecem a enzima; organofosforados duram minutos e não exigem nenhuma oxima", "Carbamatos duram minutos a horas e não envelhecem; organofosforados envelhecem", "Carbamatos e organofosforados têm a mesma duração e o mesmo envelhecimento, sem diferença clínica relevante", "Carbamatos são reversíveis e não inibem a AChE; organofosforados são irreversíveis e inibem a butirilcolinesterase", "Carbamatos são usados em anestesia para reversão de bloqueio profundo; organofosforados são usados apenas em glaucoma"], "gabarito": "B", "justificativa": "Carbamatos têm inibição mais curta (30 min a 6 h) e não envelhecem a enzima. Organofosforados fosforilam a serina de modo estável, com envelhecimento. Por isso a oxima é mais urgente nos organofosforados (resumo: Classificação dos anticolinesterásicos).", "tecnica": "Organofosforado e duração", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um paciente com bloqueio neuromuscular profundo recebe neostigmina. Mesmo com doses maiores, a força muscular não volta. Qual conceito explica esse fato, e qual associação deve sempre acompanhar a neostigmina?", "alternativas": ["Efeito teto: ACh aumentada não basta; associa-se glicopirrolato ou atropina", "Efeito de primeira passagem: a neostigmina é metabolizada no fígado e não chega ao músculo, sem associação", "Efeito placebo: a melhora é apenas psicológica, por isso se associa um analgésico para aumentar a adesão", "Efeito nocebo: o paciente piora porque espera piorar, e a associação deve ser com um antidepressivo tricíclico", "Efeito de indução enzimática: a neostigmina acelera o metabolismo do bloqueador, sem necessidade de associação"], "gabarito": "A", "justificativa": "Efeito teto é o limite de eficácia: no bloqueio profundo, aumentar a ACh não basta. A neostigmina sempre deve ser associada a glicopirrolato ou atropina, que bloqueiam os efeitos muscarínicos (resumo: Anticolinesterásicos, usos clínicos).", "tecnica": "Efeito teto e reversão", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um paciente recebe atropina e apresenta boca seca, mas não tem sudorese reduzida. Qual é a explicação farmacológica, considerando a inervação das glândulas sudoríparas?", "alternativas": ["As glândulas sudoríparas não têm receptor muscarínico, por isso a atropina não afeta a sudorese em nenhuma dose", "A sudorese é controlada por receptor nicotínico NN, e a atropina só age sobre os receptores muscarínicos M2", "A atropina aumenta a sudorese pela ativação dos receptores β2 nas glândulas, o que é um efeito paradoxal", "Sudoríparas são colinérgicas com M3; a atropina reduz a sudorese", "A sudorese é controlada apenas por adrenalina da medula adrenal, e a atropina não age sobre ela"], "gabarito": "D", "justificativa": "As glândulas sudoríparas são exceção: são inervadas por fibras simpáticas colinérgicas com receptor M3. A atropina, antagonista muscarínico, reduz a sudorese; o caso sugere atenção à dose (resumo: Sistema nervoso autônomo).", "tecnica": "Antagonista e sudorese", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Duas drogas antimuscarínicas são comparadas: uma terciária usada em cinetose e outra quaternária usada em cólica intestinal. Por que a primeira causa sedação, e a segunda, não?", "alternativas": ["A terciária tem carga permanente e fica presa no plasma; a quaternária atravessa a barreira hematoencefálica", "A terciária é agonista nicotínico e a quaternária é agonista muscarínico, com ação central oposta", "A terciária atravessa a barreira hematoencefálica; a quaternária tem carga permanente e atua na periferia", "A terciária é metabolizada no rim e a quaternária no fígado, sem relação com a barreira hematoencefálica", "A terciária é inibidora da AChE e a quaternária é inibidora da COX, com efeitos centrais opostos"], "gabarito": "C", "justificativa": "Aminas terciárias (escopolamina, atropina) são lipossolúveis e atravessam a barreira hematoencefálica, com efeitos centrais. Quaternárias (butilescopolamina) são carregadas e atuam na periferia (resumo: Terciárias × quaternárias).", "tecnica": "Terciária × quaternária", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um paciente recebe um bloqueador ganglionar. Qual efeito é esperado sobre a pressão arterial, a frequência cardíaca e a pupila, considerando qual tônus predomina em cada órgão?", "alternativas": ["Hipertensão pelo bloqueio do simpático vascular; bradicardia pelo bloqueio parassimpático; miose pelo bloqueio da íris", "Hipotensão pelo bloqueio do parassimpático vascular; bradicardia pelo bloqueio do simpático; miose pela contração da íris", "Hipotensão ortostática, taquicardia e midríase, pelo tônus predominante de cada órgão", "Hipertensão pelo bloqueio do parassimpático vascular; taquicardia pelo bloqueio do simpático; midríase pelo simpático da íris", "Nenhum efeito hemodinâmico, porque os gânglios não participam do controle da pressão, apenas da digestão"], "gabarito": "C", "justificativa": "O bloqueio ganglionar vence o tônus predominante. Nas arteríolas, o simpático predomina: há vasodilatação e hipotensão ortostática. No coração, o parassimpático predomina: há taquicardia. Na íris, o parassimpático predomina: há midríase (resumo: Fármacos nicotínicos).", "tecnica": "Bloqueio ganglionar", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um paciente recebe succinilcolina para intubação. Um colega pergunta por que o fármaco causa paralisia, se é agonista. Qual é a explicação farmacológica?", "alternativas": ["É antagonista de Nm que bloqueia a ACh e impede a despolarização da placa motora por completo", "É agonista de Nm com despolarização persistente da placa motora, levando a bloqueio neuromuscular", "É inibidor da AChE, que aumenta a ACh e causa paralisia pela hiperpolarização da membrana muscular", "É agonista de NN que ativa os gânglios e causa bloqueio simpático, o que resulta em paralisia flácida", "É agonista de M2 que reduz a frequência cardíaca, e a paralisia é consequência da bradicardia intensa"], "gabarito": "B", "justificativa": "Succinilcolina é agonista dos receptores nicotínicos musculares (Nm). A despolarização é persistente, o que bloqueia a placa motora e causa paralisia temporária (resumo: Fármacos nicotínicos).", "tecnica": "Nicotina e succinilcolina", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um paciente ingere 'chumbinho', raticida ilegal que contém aldicarbe. Qual é a classe química, e qual é a principal diferença clínica em relação aos organofosforados?", "alternativas": ["Organofosforado; quadro mais longo, e a enzima envelhece em minutos, exigindo oxima imediata", "Anticolinérgico; quadro de midríase persistente, sem inibição da acetilcolinesterase em nenhum momento", "Anti-histamínico; quadro de sedação profunda, sem alteração da transmissão colinérgica do paciente", "Betabloqueador; quadro de bradicardia isolada, sem sudorese, sialorreia ou fasciculações do paciente", "Carbamato; quadro mais curto, e a enzima não envelhece"], "gabarito": "E", "justificativa": "Aldicarbe é carbamato. O quadro é mais curto e a enzima não envelhece, ao contrário do organofosforado. Os sinais são colinérgicos (resumo: Intoxicação por carbamatos e organofosforados).", "tecnica": "Carbamato e aldicarbe", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um fármaco ativa um receptor colinérgico que é canal iônico, com resposta muito rápida, presente em gânglios autonômicos. Qual é o receptor e por qual mecanismo ele responde?", "alternativas": ["Receptor muscarínico M3, acoplado a Gq, que eleva o IP₃ e o DAG na célula muscular lisa", "Receptor muscarínico M2, acoplado a Gi, que inibe a adenilato ciclase no nó sinoatrial", "Receptor β1, acoplado a Gs, que eleva o AMPc e aumenta a contratilidade miocárdica", "Receptor D1, acoplado a Gs, que eleva o AMPc e causa vasodilatação renal", "Receptor nicotínico NN, canal iônico de Na⁺/K⁺ que despolariza o gânglio"], "gabarito": "E", "justificativa": "Nicotínicos são canais iônicos com resposta rápida. Os NN estão nos gânglios autonômicos e na medula adrenal, e os NM, na placa motora (resumo: Receptores M e N).", "tecnica": "Receptores e canal", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um paciente com doença de Alzheimer inicia donepezila. Um familiar pergunta se o fármaco para a progressão da doença. Qual é a resposta mais precisa?", "alternativas": ["É antagonista muscarínico que reverte a degeneração neuronal e interrompe a progressão definitivamente", "É agonista nicotínico que regenera os neurônios colinérgicos e cura a doença após seis meses de uso", "É inibidor da COX que reduz a inflamação cerebral e impede a formação de placas amiloides no paciente", "É anticorpo monoclonal que elimina a proteína tau e interrompe a progressão da doença em todos os pacientes", "Anticolinesterásico central, com benefício sintomático modesto, sem alterar a progressão"], "gabarito": "E", "justificativa": "Donepezila é anticolinesterásico de ação central. Tem benefício sintomático modesto, com efeitos como náuseas, diarreia, bradicardia e síncope, sem alterar a progressão (resumo: Anticolinesterásicos, usos clínicos).", "tecnica": "Alzheimer e donepezila", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Paciente, F.E., 50 anos, com intoxicação por organofosforado, apresenta miose, broncorreia, bradicardia e fasciculações. Após atropina, a broncorreia não diminui. Qual é a conduta farmacológica mais coerente?", "alternativas": ["Aumentar a atropina, dobrando a dose até secar as secreções brônquicas, e associar pralidoxima precoce", "Suspender a atropina, porque ela não tem efeito sobre a broncorreia e causa taquicardia em todos os pacientes", "Administrar propranolol para reduzir a broncorreia, porque o betabloqueador seca as secreções do pulmão", "Administrar piridostigmina para aumentar a ACh, porque o paciente está com miastenia associada à intoxicação", "Administrar fisostigmina em dose alta, porque é antídoto de qualquer intoxicação com organofosforado grave"], "gabarito": "A", "justificativa": "Na intoxicação, a atropina é titulada pela secagem brônquica. A pralidoxima reativa a AChE e deve ser precoce. Piridostigmina e fisostigmina não são condutas para essa intoxicação (resumo: Intoxicação por organofosforados).", "tecnica": "Síndrome colinérgica em caso clínico", "slide": null}], "id": "farma-gilmar-04", "titulo": "Aula 4", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-05"] = {"subtitulo": "Adrenérgicos e antiadrenérgicos: agonistas, bloqueadores e receptores", "pdf": "pdf/gilmar/aula-05.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 5 · Adrenérgicos e Antiadrenérgicos (Prof. Dr. Gilmar S. Erzinger)", "Brunton, Chabner e Knollmann (Goodman & Gilman, 12ª ed.); Aula 07 de Farmacologia Veterinária (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página.", "Slides e transcrição da aula, Prof. Dr. Gilmar S. Erzinger (resumo completo)"], "tabela": {"titulo": "Efeitos dos agonistas por órgão (slide 29)", "colunas": ["Órgão / tecido", "Receptor", "Efeito da estimulação"], "linhas": [["Coração (nós SA/AV, miocárdio)", "β1", "↑ automatismo, ↑ condução, ↑ contratilidade"], ["Músculo liso vascular", "α1 / β2", "Vasoconstrição (α1); vasodilatação no músculo esquelético (β2)"], ["Brônquios", "β2", "Broncodilatação"], ["Trato gastrintestinal", "α2 / β2", "↓ motilidade; contração dos esfíncteres"], ["Bexiga", "β2-3 / α1", "Relaxa o detrusor; contrai o esfíncter (retenção)"], ["Rim", "β1", "↑ liberação de renina"], ["Fígado e músculo esquelético", "β2 / α1", "Glicogenólise, gliconeogênese, captação de K⁺, tremor"], ["Tecido adiposo", "β3", "Lipólise"], ["Útero", "β2", "Relaxamento (varia com espécie e fase gestacional)"], ["Olho (músculo radial da íris)", "α1", "Midríase"]]}, "resumo": [{"titulo": "1. Bases: o sistema simpático e os receptores adrenérgicos", "pontos": [{"t": "Como o simpático chega ao órgão", "sub": ["A fibra pré-ganglionar libera acetilcolina no receptor nicotínico do gânglio. A fibra pós-ganglionar libera noradrenalina (NA) no órgão-alvo. A medula adrenal lança adrenalina (e um pouco de NA) diretamente no sangue. Por isso o efeito simpático é amplo e sistêmico.", "O simpático prepara o corpo para luta ou fuga. Os efeitos são: midríase, broncodilatação, aumento da frequência e da força cardíaca, glicogenólise e gliconeogênese no fígado, liberação de renina no rim, e inibição da secreção salivar aquosa."]}, {"t": "Ciclo da noradrenalina: onde os fármacos agem", "sub": ["1. Síntese: tirosina → DOPA → dopamina.", "2. Armazenamento: a dopamina entra na vesícula pelo VMAT e vira NA. A reserpina bloqueia esse transportador.", "3. Liberação: influxo de Ca²⁺ e exocitose.", "4. Receptor: a NA age nos receptores pós-sinápticos e nos pré-sinápticos α2.", "5. Recaptação: o transportador NET devolve a NA ao neurônio. A cocaína bloqueia esse transportador.", "6. Metabolismo: MAO e COMT degradam a NA."]}, {"t": "Receptores adrenérgicos e sinalização", "sub": ["α1: acoplado a Gq, ativa a fosfolipase C, forma IP₃ e DAG e eleva o Ca²⁺. Está na maioria dos tecidos simpáticos, sobretudo no músculo liso de vasos, esfíncteres e íris. Potência: NA ≥ adrenalina. A prazosina bloqueia.", "α2: acoplado a Gi, inibe a adenilil ciclase e reduz o AMPc. Está nas terminações pré-sinápticas, no SNC, no TGI, no pâncreas e nas plaquetas. Potência: adrenalina > NA. A ioimbina bloqueia.", "β1: acoplado a Gs, ativa a adenilil ciclase e aumenta o AMPc. Está no coração, no rim, nos adipócitos e no cérebro. Potência: NA = adrenalina.", "β2: acoplado a Gs. Está no músculo liso brônquico, no vascular do músculo esquelético, no útero e no fígado. Potência: adrenalina > NA.", "β3: acoplado a Gs. Está no tecido adiposo (lipólise) e no detrusor da bexiga.", "D1: acoplado a Gs. Está nos vasos renais, mesentéricos e coronários. O agonista natural é a dopamina.", "O AMPc ativa a proteína-cinase A (PKA), que fosforila proteínas efetoras. A PKA também fosforila o CREB no núcleo."]}, {"t": "Classificação dos fármacos", "sub": ["Simpatomiméticos de ação direta: atuam no receptor, seletivos ou não. α1: fenilefrina. α2: clonidina e xilazina. β1: dobutamina. β2: terbutalina e salbutamol. Não seletivos: adrenalina, NA e isoproterenol.", "Ação indireta: aumentam a NA disponível na fenda. Liberadores: anfetamina e tiramina. Bloqueadores da captação: cocaína. Inibidores da MAO: selegilina. Inibidores da COMT: entacapona.", "Ação mista: liberam NA e também ativam receptores diretamente. Exemplos: efedrina e pseudoefedrina.", "Antagonistas: bloqueiam o receptor sem ativá-lo, de forma competitiva; a fenoxibenzamina é exceção, com ligação covalente. Incluem α-bloqueadores, β-bloqueadores e a reserpina, que depleta NA."]}]}, {"titulo": "2. Catecolaminas × aminas não catecólicas", "pontos": [{"t": "Por que a via e a duração diferem", "sub": ["Catecolaminas (adrenalina, NA, dopamina, dobutamina, isoproterenol): início rápido e duração curta. São degradadas por MAO e COMT. Não são administradas por via oral, porque são inativadas no TGI e no fígado. São polares e penetram pouco no SNC. O uso típico é infusão IV em emergências: choque, parada cardiorrespiratória e insuficiência cardíaca.", "Não catecólicas (fenilefrina, efedrina, pseudoefedrina, anfetamina, salbutamol, terbutalina): são maus substratos da COMT e de muitas MAO, por isso duram mais. Podem ser dadas por via oral ou inalatória. Algumas atravessam a barreira hematoencefálica, como efedrina e anfetamina, com efeitos no SNC."]}]}, {"titulo": "3. Ação indireta e mista: anfetamina, cocaína e efedrina", "pontos": [{"t": "Anfetamina: liberadora", "sub": ["Entra no terminal pelo NET e desloca a NA das vesículas, pelo VMAT. O NET passa a funcionar ao contrário e a NA sai para a fenda. Efeitos: aumento da pressão arterial sistólica e efeitos centrais marcantes, como euforia, insônia e redução do apetite. Reserpina prévia abole a resposta."]}, {"t": "Cocaína: bloqueia a captação", "sub": ["Bloqueia o NET, então a NA liberada permanece mais tempo na fenda. Potencializa as respostas simpáticas. Também é anestésico local. A resposta potencializada é sinal de ação na captação."]}, {"t": "Efedrina: ação mista", "sub": ["Libera NA e inibe sua recaptação. Em doses altas, ativa α e β diretamente. Efedrina e pseudoefedrina não são catecóis, por isso são maus substratos de MAO e COMT.", "Efeitos: aumento da PA e do débito cardíaco. Broncodilatação menos potente e mais lenta que a da adrenalina. Usada na hipotensão em anestesia."]}]}, {"titulo": "4. Agonistas de uso clínico: catecolaminas", "pontos": [{"t": "Adrenalina (epinefrina)", "sub": ["Efeitos: inotrópica e cronotrópica positiva (β1). Um dos vasopressores mais potentes, por aumento do débito e vasoconstrição (α1). Vasodilatação na musculatura esquelética (β2). Potente broncodilatador (β2). Aumenta glicose, lactato e ácidos graxos.", "Usos: anafilaxia e reações alérgicas graves, fármaco de escolha; parada cardiorrespiratória (assistolia, fibrilação ventricular e dissociação eletromecânica); prolonga a ação de anestésicos locais; hemostático tópico.", "Efeitos adversos: taquicardia, arritmias, até fibrilação ventricular; aumento do consumo de O₂ pelo miocárdio, com isquemia; crise hipertensiva; tremor, ansiedade, agitação e palidez."]}, {"t": "Noradrenalina e isoproterenol", "sub": ["Noradrenalina: vasoconstrição intensa na maioria dos leitos, com aumento da PA sistólica e diastólica. Pouco efeito β2. A elevação da PA causa bradicardia reflexa, pelo nervo vago. Uso: hipotensão grave e choque vasodilatador, séptico, após reposição volêmica. Adversos: vasoconstrição renal, com queda do fluxo renal e isquemia; necrose se extravasar.", "Isoproterenol: agonista β não seletivo, quase sem ação α. No coração causa taquicardia e aumento da contratilidade. Nos vasos causa vasodilatação β2, com queda da PA diastólica e média. Uso: bradicardia severa e bloqueio cardíaco, como suporte temporário quando não há marca-passo. Adversos: taquicardia, arritmias, cefaleia e rubor."]}, {"t": "Dopamina: o efeito depende da dose", "sub": ["Dose baixa (menos de 2 µg/kg/min): receptor D1. Vasodilatação renal, mesentérica e coronária, com aumento do fluxo renal e da filtração glomerular.", "Dose intermediária (2 a 10 µg/kg/min): receptor β1. Inotropismo positivo, com aumento da contratilidade e do débito, pouco aumento da FC.", "Dose alta (mais de 10 µg/kg/min): receptor α1. Vasoconstrição, com aumento da resistência periférica e da PA. Perde-se o benefício renal.", "Usos: insuficiência cardíaca grave, choque cardiogênico e séptico. Adversos: náuseas, vômitos, taquicardia, arritmias, hipertensão e vasoconstrição."]}, {"t": "Dobutamina", "sub": ["Inotrópico positivo de curto prazo, β1. Aumenta a força de contração com pouco efeito cronotrópico e sem alterar muito a resistência periférica. Faixa usual de infusão IV: 2,5 a 10 µg/kg/min.", "Usos: choque cardiogênico e séptico, insuficiência cardíaca descompensada e suporte inotrópico em anestesia. Adversos: taquicardia e arritmias, sobretudo em doses altas; tolerância com infusões prolongadas. É ineficaz após betabloqueio."]}]}, {"titulo": "5. Agonistas de uso clínico: α, β2 e a sedação α2", "pontos": [{"t": "Agonistas β2: broncodilatadores e tocolíticos", "sub": ["Salbutamol, terbutalina, salmeterol e formoterol. Ação curta (3 a 4 horas, com início rápido) e ação longa (cerca de 12 horas, com início mais lento).", "Mecanismo: relaxam o músculo liso brônquico, inibem a liberação de histamina e leucotrienos pelos mastócitos e aumentam o batimento ciliar.", "Associações comuns: salmeterol com fluticasona, formoterol com budesonida, salbutamol com ipratrópio.", "Usos: asma e doença obstrutiva, e tocólise, com terbutalina e ritodrina.", "Adversos: tremor muscular (β2 no músculo esquelético), taquicardia, nervosismo e hipocalemia."]}, {"t": "Agonistas α1: vasoconstritores e descongestionantes", "sub": ["Fenilefrina: ação sistêmica ou tópica. Vasoconstrição sem estimular o coração. Não é inativada pela COMT, então o efeito é prolongado. Usos: hipotensão, descongestionante e midriático.", "Imidazolinas tópicas (nafazolina, oximetazolina, xilometazolina, tetraidrozolina): solução nasal ou colírio, com ação local. Usadas como descongestionante em rinite alérgica e hiperemia ocular.", "Atenção: bradicardia reflexa à vasoconstrição, como na fenilefrina. Congestão de rebote com uso crônico, por dessensibilização. A pseudoefedrina oral causa menos rebote, mas tem mais efeitos sistêmicos."]}, {"t": "Agonistas α2: sedação, analgesia e hipertensão", "sub": ["Clonidina e metildopa são usadas em hipertensão humana. A clonidina age no SNC: reduz o tônus simpático, com sedação e analgesia central, bradicardia e hipotensão. Pode haver hipertensão inicial transitória. Efeitos colaterais: sedação e boca seca.", "O efeito α2 central também explica a redução da liberação de NA pelo autorreceptor pré-sináptico."]}]}, {"titulo": "6. Efeitos dos agonistas e usos terapêuticos", "pontos": [{"t": "Efeitos por órgão", "sub": ["Coração (nós SA e AV, miocárdio), β1: aumento do automatismo, da condução e da contratilidade.", "Músculo liso vascular: α1 causa vasoconstrição; β2 causa vasodilatação no músculo esquelético.", "Brônquios, β2: broncodilatação.", "TGI, α2 e β2: diminuição da motilidade e contração dos esfíncteres.", "Bexiga, β2 e β3: relaxa o detrusor, e α1 contrai o esfíncter, o que favorece a retenção.", "Rim, β1: aumento da liberação de renina.", "Fígado e músculo esquelético, β2 e α1: glicogenólise, gliconeogênese, captação de K⁺ e tremor.", "Tecido adiposo, β3: lipólise.", "Útero, β2: relaxamento.", "Olho (músculo radial da íris), α1: midríase."]}, {"t": "Usos terapêuticos", "sub": ["Parada cardíaca: adrenalina na fibrilação ventricular, assistolia ou dissociação eletromecânica.", "Choque e hipotensão grave: noradrenalina, dopamina, dobutamina e fenilefrina.", "Insuficiência cardíaca: dobutamina e dopamina, como suporte inotrópico.", "Anafilaxia e alergias: adrenalina.", "Asma e broncoespasmo: salbutamol e terbutalina.", "Hipertensão em humanos: clonidina e metildopa.", "Descongestão e oftalmologia: imidazolinas e fenilefrina para midríase.", "Obs.: o material também traz usos e posologias veterinários. Não são o foco da prova."]}, {"t": "Efeitos adversos da classe", "sub": ["Taquicardia excessiva, que leva à fibrilação ventricular; crises hipertensivas; isquemia e necrose miocárdica.", "Adrenalina: tremor, ansiedade, agitação, cefaleia pulsátil, palidez e taquicardia.", "Dopamina: náuseas, vômitos, arritmias, hipertensão e vasoconstrição.", "Isoproterenol: taquicardia, cefaleia e rubor.", "Agonistas β2: tremor muscular e taquicardia.", "Fenilefrina: bradicardia reflexa.", "Clonidina: sedação e boca seca.", "Anfetamina: agitação, tremor, insônia, febre e surtos psicóticos."]}]}, {"titulo": "7. Antagonistas: α-bloqueadores", "pontos": [{"t": "Classificação e efeitos", "sub": ["α não seletivos: fenoxibenzamina (irreversível, por ligação covalente) e fentolamina.", "α1 seletivos: prazosina, terazosina, doxazosina e tansulosina. Quase todos terminam em '-zosina'.", "α2 seletivos: atipamezol, ioimbina, tolazolina e idazoxana.", "Efeito: bloqueio α1 nos vasos reduz o tônus simpático vascular, a resistência periférica e a PA. Pode causar taquicardia reflexa e hipotensão postural. Receptores β não são afetados.", "Reversão da adrenalina: após α-bloqueio, a adrenalina passa a baixar a PA, porque sobra só a vasodilatação β2."]}, {"t": "Usos", "sub": ["Feocromocitoma, vasoespasmo, hipertensão e isquemia visceral no choque. A tansulosina é usada na hiperplasia prostática.", "Os α2-antagonistas revertem a sedação e a analgesia dos agonistas α2 (atipamezol, ioimbina e tolazolina). A reversão também retira a analgesia; planeje a analgesia antes de reverter."]}]}, {"titulo": "8. Antagonistas: β-bloqueadores", "pontos": [{"t": "Mecanismo e classes", "sub": ["Todos são antagonistas competitivos. São não seletivos (β1 e β2) ou cardiosseletivos (β1). Não há β2-antagonistas de uso clínico. Pindolol e acebutolol são agonistas parciais (ASI).", "1ª geração, não seletivos: propranolol, nadolol, timolol, pindolol e sotalol.", "2ª geração, β1 seletivos: atenolol, metoprolol, esmolol (ultracurto, éster hidrolisado no sangue) e bisoprolol.", "3ª geração, vasodilatadores: carvedilol e labetalol (bloqueio α1 adicional), e nebivolol (aumenta o óxido nítrico). Carvedilol também é antioxidante.", "Nomes terminam em '-olol', exceto labetalol e carvedilol."]}, {"t": "Efeitos e cuidados", "sub": ["Efeitos: redução da FC, da contratilidade e da condução AV; redução da renina, com queda da PA. Não há hipotensão postural, porque os receptores α seguem funcionais. Reduzem a produção de humor aquoso.", "Broncoconstrição nos não seletivos: evitar em asma e doença obstrutiva. Preferir β1 seletivos.", "Cuidados: insuficiência cardíaca descompensada, bradicardia e bloqueio AV. Mascaram sinais de hipoglicemia em diabéticos. Não suspender abruptamente, porque há efeito rebote.", "Propranolol: além da queda de FC e débito, causa vasoconstrição periférica reflexa e retenção de sódio.", "Usos: hipertensão, arritmias, angina, hipertireoidismo (propranolol), infarto e ICC (metoprolol). Timolol tópico no glaucoma."]}, {"t": "Uso oftálmico no glaucoma", "sub": ["Timolol (β-bloqueador tópico) reduz a produção de humor aquoso. Brimonidina (agonista α2 tópico) reduz a produção e aumenta a drenagem.", "A absorção sistêmica pode causar bradicardia e broncoespasmo."]}]}, {"titulo": "9. Reserpina: depleção de noradrenalina", "pontos": [{"t": "Mecanismo", "sub": ["A reserpina bloqueia o VMAT, o transporte vesicular. NA, dopamina e serotonina ficam no citoplasma e são degradadas pela MAO. Sem NA vesicular, há pouca liberação e a função simpática fica bloqueada.", "Age no neurônio adrenérgico, não no receptor. Início lento e duração longa, com efeitos persistindo por dias após a suspensão.", "Abole a resposta aos simpatomiméticos de ação indireta, como a anfetamina. Foi usada na hipertensão, mas hoje foi substituída por fármacos com menos efeitos adversos."]}]}, {"titulo": "10. Síntese e pontos-chave", "pontos": [{"t": "O essencial para a prova", "sub": ["O receptor define o efeito: α1 contrai músculo liso; β1 acelera e fortalece o coração; β2 relaxa e mobiliza energia; α2 inibe a liberação de NA e causa sedação.", "Catecolaminas agem rápido e por pouco tempo, por via IV. Não catecólicas duram mais e funcionam por via oral ou inalatória.", "A dopamina muda de efeito com a dose: D1 → β1 → α1.", "Betabloqueadores reduzem a FC sem hipotensão postural. Evitar em broncopatas e na ICC descompensada.", "Dica: os α1-bloqueadores terminam em '-zosina'; os β-bloqueadores terminam em '-olol'. A reserpina age no neurônio, não no receptor."]}]}], "glossario": [{"termo": "Gq / Gs / Gi", "tecnica": "Vias de sinalização", "definicao": "Proteínas G que ativam fosfolipase C (Gq), ativam adenilil ciclase (Gs) ou inibem a adenilil ciclase (Gi).", "slide": 10}, {"termo": "Dopamina em dose baixa (D1)", "tecnica": "Dose-dependência", "definicao": "Vasodilatação renal, mesentérica e coronária, com aumento de fluxo e natriurese.", "slide": 24}, {"termo": "Catecolaminas", "tecnica": "Classificação", "definicao": "Adrenalina, noradrenalina, dopamina, dobutamina e isoproterenol; polares, de ação rápida e curta.", "slide": 16}, {"termo": "Efedrina", "tecnica": "Ação mista", "definicao": "Libera NA, inibe sua recaptação e ativa α e β diretamente em doses altas; não é catecol.", "slide": 18}, {"termo": "NET", "tecnica": "Recaptação", "definicao": "Transportador de noradrenalina; alvo da cocaína, que mantém a NA na fenda.", "slide": 18}, {"termo": "VMAT", "tecnica": "Armazenamento", "definicao": "Transportador vesicular; alvo da reserpina, que deixa a NA no citoplasma.", "slide": 50}, {"termo": "Crise de Adams-Stokes (epônimo: Adams-Stokes)", "tecnica": "Isoproterenol", "definicao": "Crise de bradicardia severa ou bloqueio cardíaco; o isoproterenol é citado como suporte temporário.", "slide": 22}, {"termo": "α1 (alfa-1)", "tecnica": "Receptor (Gq)", "definicao": "Maioria dos tecidos-alvo simpáticos. Via Gq e PLC, com IP₃ e DAG. Causa contração de músculo liso de vasos, esfíncteres e íris.", "slide": 7}, {"termo": "α2 (alfa-2)", "tecnica": "Receptor (Gi)", "definicao": "Terminações pré-sinápticas, SNC, TGI, pâncreas e plaquetas. Via Gi, com queda de AMPc. Inibe a liberação de NA e causa sedação.", "slide": 7}, {"termo": "β1 (beta-1)", "tecnica": "Receptor (Gs)", "definicao": "Coração e rim. Via Gs e AMPc. Aumenta frequência e contratilidade e libera renina.", "slide": 7}, {"termo": "β2 (beta-2)", "tecnica": "Receptor (Gs)", "definicao": "Músculo liso brônquico e vascular, útero e fígado. Relaxa e dilata vias aéreas e vasos.", "slide": 7}, {"termo": "β3 (beta-3)", "tecnica": "Receptor (Gs)", "definicao": "Tecido adiposo (lipólise) e bexiga (relaxa o detrusor).", "slide": 7}, {"termo": "Fosfolipase C (PLC)", "tecnica": "Via de sinalização", "definicao": "Enzima ativada por α1, que converte PIP2 em IP₃ e DAG.", "slide": 10}, {"termo": "Adenilil ciclase (AC)", "tecnica": "Via de sinalização", "definicao": "Enzima que converte ATP em AMPc. Ativada por Gs e inibida por Gi.", "slide": 10}, {"termo": "MAO e COMT", "tecnica": "Degradação", "definicao": "Enzimas que degradam as catecolaminas. Alvos de selegilina (MAO) e entacapona (COMT).", "slide": 6}, {"termo": "Reserpina", "tecnica": "Depletor de NA", "definicao": "Alcaloide que bloqueia o VMAT. Esgota a NA e age no neurônio, não no receptor.", "slide": 50}, {"termo": "Cocaína", "tecnica": "Inibidor da captação", "definicao": "Bloqueia o NET, o que mantém a NA na fenda por mais tempo.", "slide": 18}, {"termo": "Anfetamina", "tecnica": "Liberador de NA", "definicao": "Desloca a NA das vesículas e a libera pelo NET invertido. Efeitos centrais marcantes.", "slide": 18}, {"termo": "Efedrina e pseudoefedrina", "tecnica": "Ação mista", "definicao": "Liberam NA e ativam receptores diretamente. Usadas na incontinência urinária em cães e na descongestão.", "slide": 18}, {"termo": "Tiramina", "tecnica": "Liberador de NA", "definicao": "Amina que libera NA da terminação, com ação indireta.", "slide": 13}, {"termo": "Selegilina e entacapona", "tecnica": "Ação indireta", "definicao": "Selegilina inibe a MAO. Entacapona inibe a COMT. Ambas aumentam a NA disponível.", "slide": 13}, {"termo": "Fenilefrina", "tecnica": "Agonista α1", "definicao": "Vasoconstritor de ação sistêmica ou tópica. Não é inativada pela COMT, por isso dura mais.", "slide": 27}, {"termo": "Imidazolinas tópicas (nafazolina, oximetazolina, xilometazolina)", "tecnica": "Agonista α1", "definicao": "Descongestionantes nasais e colírios. Causam congestão de rebote com uso crônico.", "slide": 27}, {"termo": "Clonidina e metildopa", "tecnica": "Agonista α2", "definicao": "Anti-hipertensivos de uso humano. Agem no SNC para reduzir o tônus simpático.", "slide": 28}, {"termo": "Xilazina", "tecnica": "Agonista α2", "definicao": "Sedativo e analgésico veterinário. É emética em gatos. Revertida pela ioimbina.", "slide": 28}, {"termo": "Detomidina e romifidina", "tecnica": "Agonista α2", "definicao": "Sedativos e analgésicos veterinários de ação central, usados em contenção química.", "slide": 28}, {"termo": "Medetomidina e dexmedetomidina", "tecnica": "Agonista α2", "definicao": "Sedativos e analgésicos veterinários de ação central. Revertidos pelo atipamezol.", "slide": 28}, {"termo": "Atipamezol", "tecnica": "Antagonista α2", "definicao": "Antagonista α2 mais seletivo, cerca de 8.500:1. Reverte medetomidina e dexmedetomidina.", "slide": 41}, {"termo": "Ioimbina", "tecnica": "Antagonista α2", "definicao": "Antagonista α2 que reverte a xilazina em cães, gatos, equinos e cervídeos.", "slide": 41}, {"termo": "Tolazolina", "tecnica": "Antagonista α2", "definicao": "Antagonista α2 que reverte a xilazina em ruminantes e equinos. Também bloqueia α1.", "slide": 41}, {"termo": "Idazoxana", "tecnica": "Antagonista α2", "definicao": "Antagonista α2 experimental.", "slide": 41}, {"termo": "Adrenalina (epinefrina)", "tecnica": "Catecolamina", "definicao": "Agonista não seletivo. Usada em anafilaxia e parada cardiorrespiratória. Causa taquicardia e crise hipertensiva.", "slide": 21}, {"termo": "Noradrenalina (norepinefrina)", "tecnica": "Catecolamina", "definicao": "Vasoconstritor intenso, com reflexo de bradicardia. Usada em hipotensão grave e choque séptico.", "slide": 22}, {"termo": "Isoproterenol", "tecnica": "Catecolamina", "definicao": "Agonista β não seletivo, sem efeito α. Usado em bradicardia severa e bloqueio AV.", "slide": 22}, {"termo": "Dobutamina", "tecnica": "Agonista β1", "definicao": "Inotrópico de curto prazo. Faixa usual de 2,5 a 10 µg/kg/min. Ineficaz após betabloqueio.", "slide": 25}, {"termo": "Salbutamol, salmeterol, formoterol e terbutalina", "tecnica": "Agonista β2", "definicao": "Broncodilatadores. Salbutamol e terbutalina são de ação curta; salmeterol e formoterol são de ação longa.", "slide": 26}, {"termo": "Clembuterol", "tecnica": "Agonista β2", "definicao": "Broncodilatador e tocolítico, usado em equinos e bovinos. Causa tremor e taquicardia.", "slide": 26}, {"termo": "Ritodrina", "tecnica": "Agonista β2", "definicao": "Tocolítico para retardar o trabalho de parto.", "slide": 26}, {"termo": "Propranolol", "tecnica": "Betabloqueador", "definicao": "Não seletivo, β1 e β2. Usado em hipertensão, arritmias, hipertireoidismo e angina. Causa broncoconstrição.", "slide": 43}, {"termo": "Timolol", "tecnica": "Betabloqueador", "definicao": "Não seletivo. Usado topicamente no glaucoma, por reduzir a produção de humor aquoso.", "slide": 43}, {"termo": "Atenolol e metoprolol", "tecnica": "Betabloqueador", "definicao": "β1-seletivos. Usados em hipertensão, angina, infarto e ICC.", "slide": 43}, {"termo": "Esmolol", "tecnica": "Betabloqueador", "definicao": "β1-seletivo de ação ultracurta, éster hidrolisado no sangue. Usado em arritmias agudas por via IV.", "slide": 46}, {"termo": "Nebivolol", "tecnica": "Betabloqueador", "definicao": "Betabloqueador de 3ª geração que aumenta o NO, com efeito vasodilatador.", "slide": 48}, {"termo": "Carvedilol e labetalol", "tecnica": "Betabloqueador", "definicao": "Betabloqueadores de 3ª geração com bloqueio α1 adicional.", "slide": 48}, {"termo": "Pindolol e acebutolol", "tecnica": "Betabloqueador", "definicao": "Agonistas parciais (ASI), que mantêm alguma atividade simpática.", "slide": 42}, {"termo": "Fenoxibenzamina", "tecnica": "Alfabloqueador", "definicao": "Antagonista α não seletivo e irreversível, com ligação covalente.", "slide": 37}, {"termo": "Prazosina, terazosina e doxazosina", "tecnica": "Alfabloqueador", "definicao": "α1-seletivos. Usados na hipertensão e na obstrução funcional do esfíncter uretral.", "slide": 37}, {"termo": "Tansulosina", "tecnica": "Alfabloqueador", "definicao": "α1-seletivo usado na hiperplasia prostática.", "slide": 37}, {"termo": "Brimonidina", "tecnica": "Agonista α2 tópico", "definicao": "Reduz a produção de humor aquoso e aumenta a drenagem no glaucoma.", "slide": 49}, {"termo": "Feocromocitoma", "tecnica": "Doença", "definicao": "Tumor que produz catecolaminas. Uma das indicações citadas para alfabloqueadores.", "slide": 40}], "caso": {"titulo": "Caso: anafilaxia em paciente asmático com betabloqueador", "perfil": "Escolha do fármaco e efeitos de betabloqueio.", "etapas": [{"titulo": "Etapa 1: anafilaxia", "texto": "Homem de 35 anos tem anafilaxia após picada de inseto: hipotensão, edema de laringe e broncoespasmo. Chega ao pronto-socorro com pressão de 70 por 40 mmHg.", "perguntas": [{"pergunta": "Qual é o fármaco de escolha, segundo a aula?", "alts": ["Adrenalina, pelos efeitos α1, β1 e β2", "Propranolol, para reduzir a frequência cardíaca", "Dobutamina, pelo efeito inotrópico apenas", "Fenoxibenzamina, pelo bloqueio alfa irreversível", "Clonidina, pela ação central sedativa"], "erradas": ["Propranolol bloqueia β e pioraria o broncoespasmo e a hipotensão.", "Dobutamina atua em β1 e não resolve o broncoespasmo nem a vasoconstrição.", "Fenoxibenzamina bloqueia α e reduziria a pressão, o oposto do necessário.", "Clonidina causa sedação e hipotensão, sem indicação na anafilaxia."], "justificativa": "A adrenalina é o fármaco de escolha na anafilaxia, por efeitos α1, β1 e β2 (slide 21)."}]}, {"titulo": "Etapa 2: asmático em betabloqueador", "texto": "Outro paciente, asmático, usa propranolol para hipertensão. Tem broncoespasmo e precisa de broncodilatação.", "perguntas": [{"pergunta": "Por que o propranolol agrava o quadro, e qual classe de betabloqueador é preferível?", "alts": ["Bloqueia β2 brônquico; preferir β1-seletivos, que poupam os brônquios", "Ativa α1 brônquico; preferir α2-seletivos, sem efeito pulmonar", "Induz tolerância β2; preferir dopamina em dose baixa", "Libera histamina; preferir anti-histamínicos de primeira geração", "Inibe COX-2 brônquica; preferir coxibes"], "erradas": ["Propranolol não ativa α1 no brônquio; o problema é o bloqueio de β2.", "Dopamina em dose baixa atua em D1 renal e não é a escolha para broncoespasmo.", "A histamina não é o mecanismo do efeito do propranolol.", "Coxibes são anti-inflamatórios e não tratam o broncoespasmo beta."], "justificativa": "Betabloqueadores não seletivos causam broncoconstrição; β1-seletivos poupam os brônquios (slides 42 e 44)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Homem, paciente D.F., 33 anos, com alergia a crustáceos, apresenta após refeição hipotensão (PA 70/40 mmHg), estridor, urticária generalizada e broncoespasmo. Qual é o fármaco de escolha imediato e o mecanismo que reverte a hipotensão e o broncoespasmo?", "alternativas": ["Difenidramina endovenosa, que bloqueia H1 e reverte a hipotensão pela vasodilatação de vênulas pós-capilares", "Cromoglicato inalatório, que estabiliza o mastócito e impede a degranulação já em curso no tecido do paciente", "Salbutamol inalatório isolado, que é vasodilatador e reverte a hipotensão pela ação em receptores α2 vasculares", "Dexclorfeniramina associada a ranitidina, que bloqueiam H1 e H2 para reduzir a permeabilidade vascular do paciente", "Adrenalina, com vasoconstrição por α1 e broncodilatação por β2, efeitos opostos aos da histamina"], "gabarito": "E", "justificativa": "Na anafilaxia, a adrenalina é o fármaco de escolha. Ela causa vasoconstrição por α1 e broncodilatação por β2, sem bloquear o receptor de histamina (resumo: Adrenalina).", "tecnica": "Adrenalina na anafilaxia", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Paciente com feocromocitoma, paciente V.L., 41 anos, recebe fenoxibenzamina antes da cirurgia. Durante a operação, uma dose de adrenalina causa queda da pressão arterial, em vez de elevação. Qual é a explicação farmacológica?", "alternativas": ["A fenoxibenzamina ativa os receptores β1, que aumentam a frequência cardíaca e reduzem a pressão arterial", "O α-bloqueio deixa a vasodilatação β2 sem oposição; a adrenalina passa a baixar a PA", "A fenoxibenzamina é agonista α1, e a adrenalina passa a agir apenas sobre receptores muscarínicos M3", "A adrenalina é metabolizada pela MAO em segundos quando há fenoxibenzamina, reduzindo a concentração plasmática", "A fenoxibenzamina bloqueia a degranulação de mastócitos, que liberam adrenalina endógena no feocromocitoma"], "gabarito": "B", "justificativa": "Após o α-bloqueio, a adrenalina passa a agir só sobre os receptores β2, com vasodilatação e queda da PA. Esse é o fenômeno de reversão (resumo: α-bloqueadores).", "tecnica": "Reversão da adrenalina", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Paciente C.R., 58 anos, com DPOC e hipertensão, precisa de betabloqueador. Qual classe é a mais adequada, e qual é o risco da alternativa não seletiva?", "alternativas": ["β não seletivo, como propranolol, que é mais seguro na DPOC por bloquear β1 e β2 com igual intensidade", "Timolol sistêmico, que bloqueia β2 nos brônquios e reduz a produção de humor aquoso no olho do paciente", "β1 seletivo, que poupa os β2 dos brônquios; a não seletiva causa broncoconstrição", "Labetalol, que bloqueia β2 nos brônquios e α1 nos vasos, com broncodilatação garantida na DPOC", "Esmolol, que é ultracurto e bloqueia β2 nos brônquios, sem seletividade para o coração do paciente"], "gabarito": "C", "justificativa": "Betabloqueadores não seletivos bloqueiam β2 e causam broncoconstrição. Em DPOC e asma, preferem-se os β1 seletivos (resumo: β-bloqueadores, efeitos e cuidados).", "tecnica": "Asma e β-bloqueador", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Paciente E.S., 62 anos, diabético insulinodependente, em uso de propranolol para hipertensão, apresenta hipoglicemia grave sem taquicardia nem tremor. Qual é a explicação farmacológica?", "alternativas": ["O propranolol aumenta a glicemia por bloqueio β2 no fígado, então a hipoglicemia é causada pela insulina em excesso", "O propranolol ativa a insulina endógena, que aumenta a glicose e causa hipoglicemia sem sinais de alerta", "O propranolol causa diurese osmótica, e a hipoglicemia é percebida apenas pela queda de peso do paciente", "O betabloqueio mascara os sinais adrenérgicos da hipoglicemia, como taquicardia e tremor, que são os alertas", "O propranolol impede a absorção intestinal de glicose, e a hipoglicemia só ocorre durante o jejum do paciente"], "gabarito": "D", "justificativa": "Betabloqueadores mascaram sinais de hipoglicemia, como taquicardia e tremor. O paciente diabético precisa de orientação específica (resumo: β-bloqueadores, cuidados).", "tecnica": "Betabloqueador e hipoglicemia", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Paciente J.P., 55 anos, em uso crônico de propranolol, suspende o fármaco de forma abrupta e tem taquicardia e crise hipertensiva. Qual é a explicação farmacológica e a conduta na prescrição?", "alternativas": ["Reação de hipersensibilidade tipo I contra o propranolol, com degranulação de mastócitos; trocar por corticoide", "Efeito rebote por hipersensibilidade dos receptores regulados para cima; a suspensão deve ser gradual", "Efeito de primeira passagem que é maior após a suspensão; reiniciar o fármaco na mesma dose imediatamente", "Intoxicação pelo metabólito ativo acumulado, que é eliminado de forma abrupta pela urina; suspender o rim", "Indução do CYP3A4 pela suspensão, que acelera a degradação do fármaco; aumentar a dose do betabloqueador"], "gabarito": "B", "justificativa": "A suspensão abrupta causa rebote, porque os receptores, regulados para cima, respondem de forma exagerada. A conduta é reduzir a dose de forma gradual (resumo: β-bloqueadores, cuidados).", "tecnica": "Suspensão de betabloqueador", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Paciente F.T., 70 anos, em choque cardiogênico, recebe dopamina. A dose é aumentada até 15 µg/kg/min. Qual é o receptor predominante nessa faixa, e qual efeito renal benéfico se perde?", "alternativas": ["D1, com vasodilatação renal; o efeito se mantém em qualquer dose e não se perde com o aumento", "β2, com broncodilatação; o efeito renal melhora com a dose, porque o β2 aumenta a filtração glomerular", "α1, com vasoconstrição; perde-se a vasodilatação renal", "β1, com aumento da contratilidade; o efeito renal aumenta de forma proporcional à dose administrada", "α2, com sedação central; o efeito renal é reduzido, mas a pressão arterial se mantém estável"], "gabarito": "C", "justificativa": "Dopamina muda de receptor com a dose: D1 em dose baixa, β1 em dose intermediária e α1 em dose alta (mais de 10 µg/kg/min). Em dose alta, perde-se a vasodilatação renal (resumo: Dopamina).", "tecnica": "Dopamina: dose e receptor", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Paciente S.M., 48 anos, com choque séptico após reposição volêmica adequada, continua hipotenso. A equipe escolhe noradrenalina. Que efeito cardíaco reflexo pode aparecer, e qual é a sua causa?", "alternativas": ["Taquicardia direta, pela ativação de β1 no nó sinoatrial, que é um efeito principal da noradrenalina", "Bradicardia reflexa, pelo aumento da PA que ativa o barorreflexo com resposta vagal", "Bloqueio atrioventricular, pela ativação de α2 no nó AV, que é o efeito primário do fármaco", "Fibrilação atrial imediata, pela ativação de D1 no miocárdio, que é o efeito dominante em choque", "Parada cardíaca, pela ativação de M2 no nó sinusal, que é o efeito direto da noradrenalina"], "gabarito": "B", "justificativa": "Noradrenalina causa vasoconstrição intensa, com aumento da PA. A elevação da pressão ativa o reflexo vagal, com bradicardia reflexa (resumo: Noradrenalina).", "tecnica": "Choque vasodilatador e noradrenalina", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Paciente, A.K., 60 anos, em anestesia, recebe fenilefrina para hipotensão. A frequência cai. Um residente acredita que o fármaco é bradicardizante direto. Qual é a explicação mais correta?", "alternativas": ["É efeito direto do α1 no nó sinoatrial, que reduz a automaticidade do marca-passo natural do coração", "É efeito de β2 no coração, que reduz a contratilidade e a frequência de forma direta e imediata", "É efeito de M2, porque a fenilefrina ativa receptores muscarínicos no nó AV do paciente", "É efeito de D1, porque a fenilefrina ativa receptores dopaminérgicos no coração em todas as doses", "Bradicardia reflexa à vasoconstrição: a fenilefrina não age no coração"], "gabarito": "E", "justificativa": "Fenilefrina é agonista α1 que vasoconstringe sem estimular o coração. A queda da frequência é reflexa, pelo barorreflexo, e não direta (resumo: Agonistas α1).", "tecnica": "Fenilefrina e bradicardia", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Paciente, R.G., 35 anos, usa descongestionante nasal tópico há 3 semanas, diariamente. Agora tem congestão pior do que antes do uso. Qual é o mecanismo?", "alternativas": ["Dessensibilização dos receptores α1 da mucosa nasal, com congestão de rebote", "Aumento da IgE nasal, que ativa mastócitos após a suspensão do descongestionante e causa edema", "Bloqueio dos receptores β2 nasais, que reduz a dilatação dos vasos e causa congestão persistente", "Inibição da acetilcolinesterase nasal, que aumenta a secreção de muco nas vias aéreas superiores", "Liberação de histamina pelos eosinófilos, que aumentam a permeabilidade vascular e causam rinite crônica"], "gabarito": "A", "justificativa": "Imidazolinas tópicas têm ação local, mas o uso contínuo leva a dessensibilização dos receptores e congestão de rebote (resumo: Agonistas α1, imidazolinas).", "tecnica": "Congestão de rebote", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Paciente, M.L., 52 anos, em uso de clonidina para hipertensão, apresenta sedação e boca seca. Qual é o mecanismo central desses efeitos?", "alternativas": ["Agonismo α2 central, que reduz o tônus simpático e causa sedação e analgesia", "Bloqueio α1 periférico, que reduz a resistência vascular e causa hipotensão postural com sedação", "Bloqueio β1 cardíaco, que reduz a frequência e a contratilidade e causa fadiga com sonolência", "Ativação de D1 renal, que aumenta a diurese e reduz o volume plasmático do paciente com sonolência", "Inibição da COX, que reduz a produção de prostaglandinas e causa sedação por efeito direto no SNC"], "gabarito": "A", "justificativa": "Clonidina é agonista α2 central. Reduz o tônus simpático, com sedação, analgesia e hipotensão. Pode causar boca seca (resumo: Agonistas α2).", "tecnica": "Clonidina e sedação", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Paciente, H.B., 46 anos, tratado com reserpina para hipertensão, recebe anfetamina e não apresenta a resposta esperada de aumento da PA. Qual é a explicação?", "alternativas": ["A reserpina bloqueia o receptor α1, e a anfetamina depende desse receptor para agir no coração do paciente", "A reserpina ativa a MAO, que degrada a anfetamina antes de ela alcançar a fenda sináptica do paciente", "A reserpina bloqueia o VMAT, e a NA não está estocada nas vesículas para ser liberada pela anfetamina", "A reserpina aumenta a recaptação pelo NET, o que impede a anfetamina de entrar no neurônio do paciente", "A reserpina inibe a COMT, o que aumenta a noradrenalina e torna a anfetamina desnecessária no tratamento"], "gabarito": "C", "justificativa": "Reserpina bloqueia o VMAT. Sem NA vesicular, a anfetamina, que age por deslocamento vesicular, não produz resposta. Essa abolição é característica dos simpatomiméticos indiretos (resumo: Reserpina).", "tecnica": "Reserpina e anfetamina", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um estudante compara a anfetamina e a cocaína, que aumentam a noradrenalina na fenda. Qual é a diferença de mecanismo entre elas?", "alternativas": ["Anfetamina bloqueia a recaptação pelo NET; cocaína entra pelo NET e desloca a NA das vesículas", "Anfetamina ativa diretamente o receptor α1; cocaína ativa diretamente o receptor β2 no músculo liso", "Anfetamina inibe a MAO; cocaína inibe a COMT, e ambas aumentam a degradação da noradrenalina", "Anfetamina entra pelo NET e desloca a NA das vesículas; cocaína bloqueia a recaptação pelo NET", "Anfetamina é agonista muscarínico; cocaína é antagonista muscarínico, e ambas atuam sobre a acetilcolina"], "gabarito": "D", "justificativa": "Anfetamina é liberadora: entra pelo NET e desloca NA das vesículas, invertendo o transportador. Cocaína bloqueia a recaptação pelo NET, prolongando a ação da NA (resumo: Ação indireta).", "tecnica": "Anfetamina × cocaína", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um anestesiologista usa efedrina para hipotensão e um colega questiona por que ela não é apenas um agonista direto. Qual é a explicação mais correta?", "alternativas": ["Efedrina libera NA e também ativa receptores diretamente; é ação mista", "Efedrina é apenas agonista α1 direto, sem qualquer efeito sobre a liberação de noradrenalina no tecido", "Efedrina é inibidora da MAO e, portanto, atua apenas aumentando a degradação da noradrenalina na fenda", "Efedrina é antagonista β, o que impede a ativação do coração e reduz a pressão arterial do paciente", "Efedrina é anticolinérgica e atua por bloqueio muscarínico nos vasos, sem ação adrenérgica nenhuma"], "gabarito": "A", "justificativa": "A efedrina libera NA, inibe sua recaptação e, em doses altas, ativa α e β diretamente. Essa é a ação mista. Não é catecol, por isso dura mais (resumo: Ação mista).", "tecnica": "Efedrina e ação mista", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Paciente, P.S., 63 anos, com insuficiência cardíaca descompensada, recebe dobutamina. Após betabloqueio prévio, o efeito é fraco. Por quê?", "alternativas": ["A dobutamina age por receptor α2, que é ativado pelo betabloqueador e reduz a contratilidade do paciente", "A dobutamina age por receptor D1, que é inibido pelo betabloqueador e causa vasodilatação renal", "A dobutamina age por receptor muscarínico M3, que é estimulado pelo betabloqueador e causa broncorreia", "A dobutamina age por receptor nicotínico NN, que é bloqueado pelo betabloqueador e causa paralisia ganglionar", "A dobutamina age por receptor β1, que está bloqueado pelo betabloqueador, então o efeito inotrópico cai"], "gabarito": "E", "justificativa": "A dobutamina é agonista β1. Com betabloqueio prévio, o receptor está ocupado e o efeito é reduzido. A dobutamina é ineficaz após betabloqueio (resumo: Dobutamina).", "tecnica": "Dobutamina e betabloqueio", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Paciente, E.M., 68 anos, com hiperplasia prostática, inicia tansulosina e se queixa de tontura ao levantar. Qual é o mecanismo e a orientação?", "alternativas": ["Bloqueio β2 vascular aumenta a resistência periférica; orientar hidratação intensa e repouso de 24 horas", "Bloqueio M3 do esfíncter aumenta a retenção urinária; orientar esvaziamento vesical antes de levantar", "Ativação de α2 central reduz a atividade do SNC; orientar evitar qualquer atividade física por uma semana", "Bloqueio α1 vascular reduz o tônus simpático; orientar levantar-se devagar e monitorar a PA em pé", "Inibição da COMT aumenta a noradrenalina; orientar reduzir o consumo de cafeína e de álcool durante o tratamento"], "gabarito": "D", "justificativa": "Alfabloqueadores causam hipotensão postural pelo bloqueio α1 vascular. A tansulosina é usada na hiperplasia prostática, e a orientação é levantar-se devagar (resumo: Alfabloqueadores, efeitos e usos).", "tecnica": "Alfa-bloqueador e hipotensão postural", "slide": null}], "id": "farma-gilmar-05", "titulo": "Aula 5", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["farma-gilmar-06"] = {"subtitulo": "Autacoides: histamina, serotonina, eicosanoides, PAF, cininas e AINEs", "pdf": "pdf/gilmar/aula-06.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 6 · Autacoides (Prof. Gilmar S. Erzinger)", "Brunton, Chabner e Knollmann (Goodman & Gilman); Nature Reviews Drug Discovery (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página.", "Slides e transcrição da aula, Prof. Dr. Gilmar S. Erzinger (resumo completo)"], "tabela": {"titulo": "Prostanoides: produção e ação (slide 33)", "colunas": ["Sigla", "Prostanoide", "Produção", "Ação"], "linhas": [["PGD2", "Prostaglandina D2", "Mastócitos", "Vasodilatação, inibição da agregação plaquetária, relaxamento do TGI e útero"], ["PGF2α", "Prostaglandina F2α", "Miométrio", "Contração do miométrio, luteólise e broncoconstrição"], ["PGI2", "Prostaciclina", "Endotélio", "Vasodilatação, hiperalgesia, inibição da agregação, renina e natriurese"], ["PGE2", "Prostaglandina E2", "Pulmão, macrófago", "Vasodilatação, hiperalgesia, febre, proliferação celular"], ["TXA2", "Tromboxano A2", "Plaquetas", "Agregação plaquetária, vasoconstrição e broncoconstrição"]]}, "resumo": [{"titulo": "1. Inflamação, dor e autacoides", "pontos": [{"t": "O que é inflamação", "sub": ["Inflamação é a reação do organismo a uma infecção ou lesão tecidual. A capacidade de montar essa resposta é essencial para a sobrevivência, diante de patógenos e lesões ambientais. Os sinais cardinais são calor, rubor, edema (tumor), dor e perda de função.", "Em algumas situações e doenças, a resposta é exagerada e persistente, sem benefício aparente. É aí que os fármacos entram para interromper a cadeia de mediadores."]}, {"t": "Autacoides: mediadores de ação local", "sub": ["Autacoides (do grego autos, próprio, e akos, remédio) são substâncias naturais, com estruturas químicas e atividades variadas, produzidas rapidamente em resposta a um estímulo. Agem perto do local onde são sintetizadas.", "Mediadores inflamatórios: histamina, serotonina, eicosanoides (derivados de lipídeos de 20 carbonos) e PAF, além de peptídeos, como as cininas, e citocinas."]}, {"t": "Como a dor é transmitida", "sub": ["Mediadores como bradicinina, prostaglandinas, serotonina e histamina sensibilizam as terminações nociceptivas periféricas. O sinal sobe para os centros superiores, onde é modulado.", "Exemplo do slide: em preparação de nervo, a bradicinina isolada ou a PGE₂ isolada não aumentam muito o sinal. Mas a bradicinina aplicada após a PGE₂ aumenta a intensidade do sinal. Ou seja, os mediadores atuam em sinergia, e a prostaglandina prepara o terreno para a bradicinina."]}]}, {"titulo": "2. Histamina e anti-histamínicos", "pontos": [{"t": "Síntese e ações", "sub": ["A histamina é uma amina biogênica vasodilatadora, derivada da histidina. É produzida e liberada em maior quantidade por mastócitos e basófilos.", "No músculo liso vascular, ativa H1 e causa dilatação de vênulas pós-capilares e arteríolas terminais, com eritema. No endotélio, a contração separa as células e causa edema e pápula. Nos nervos periféricos, sensibiliza as terminações, com prurido e dor. Nos pulmões, causa broncoconstrição, com sintomas semelhantes aos da asma. No coração, o efeito é pequeno."]}, {"t": "Receptores de histamina", "sub": ["H1: Gq/11, aumenta IP₃, DAG e Ca²⁺, e ativa o NF-κB. Está no músculo liso, no endotélio vascular e no cérebro.", "H2: Gs, aumenta o AMPc. Está nas células parietais gástricas, no miocárdio, nos mastócitos e no cérebro. Ativa a secreção de ácido gástrico.", "H3: Gi/o, reduz o AMPc. Está no SNC, onde é neurotransmissor e regula o ritmo circadiano e a vigília.", "H4: Gi/o, reduz o AMPc e aumenta o Ca²⁺. Está nas células hematopoéticas e na mucosa gástrica. Participa da quimiotaxia."]}, {"t": "As três estratégias contra a histamina", "sub": ["1. Bloquear o receptor: anti-H1 (difenidramina, loratadina), que são agonistas inversos. Tratam alergia.", "2. Impedir a desgranulação dos mastócitos: cromolin e nedocromil estabilizam o mastócito e são usados na profilaxia da asma.", "3. Antagonismo fisiológico: a epinefrina (adrenalina) neutraliza funcionalmente os efeitos da histamina na anafilaxia, produzindo efeitos opostos."]}, {"t": "Anti-histamínicos H1: primeira e segunda gerações", "sub": ["O primeiro anti-histamínico H1 foi descrito por Bovet e Staub, em 1937, após o achado de que a histamina era um mediador importante da hipersensibilidade alérgica.", "São úteis em rinite, conjuntivite, urticária e prurido. Bloqueiam fortemente o aumento da permeabilidade capilar, que forma edema e pápula. Têm propriedades anti-inflamatórias, atribuídas à supressão da via NF-κB nas células imunes.", "Primeira e segunda gerações são igualmente eficazes contra a alergia. Mas não são efetivas na vasculite urticariforme nem no angioedema hereditário, que é deficiência do inibidor de C1.", "A diferença é a lipofilicidade. Os de primeira geração são lipofílicos, atravessam a barreira hematoencefálica e causam sonolência. Os de segunda geração têm efeito sedativo mínimo."]}, {"t": "Antagonistas H2", "sub": ["Cimetidina e ranitidina são antagonistas seletivos de H2. Competem reversivelmente com a histamina nas células parietais e reduzem a secreção gástrica.", "Indicações: doença de refluxo ácido (pirose) e doença ulcerosa péptica."]}]}, {"titulo": "3. Serotonina: triptanos e antieméticos", "pontos": [{"t": "Síntese, distribuição e degradação", "sub": ["A serotonina (5-hidroxitriptamina, 5-HT) é neurotransmissor no cérebro e hormônio local na periferia. É produzida a partir do triptofano, que vira 5-hidroxitriptofano pela triptofano hidroxilase, e depois serotonina pela dopa descarboxilase. É degradada pela MAO em ácido 5-hidroxi-indolacético (5-HIAA), eliminado na urina."]}, {"t": "Onde a serotonina está", "sub": ["No SNC: neurotransmissor, em altas concentrações no mesencéfalo.", "Na parede do intestino: mais de 90% do conteúdo total do organismo está nas células enterocromafins.", "No sangue: as plaquetas acumulam serotonina por transporte ativo e a liberam quando se agregam."]}, {"t": "Receptores e seus efeitos", "sub": ["5-HT1A, 1B, 1D, 1E e 1F: inibem a adenilato ciclase. O 5-HT1D está em vasos cranianos e causa vasoconstrição. O sumatriptano é agonista de 5-HT1D e 1B.", "5-HT2A, 2B, 2C: ativam a fosfolipase C. Estão em plaquetas, músculo liso (contração), estômago e plexo coroide.", "5-HT3: canal iônico, em nervos periféricos e na área postrema. Causa excitação neuronal. A ondansetrona é antagonista.", "5-HT4: ativa a adenilato ciclase, no hipocampo e no trato gastrointestinal. Estimula a motilidade.", "Efeitos gerais: aumento da motilidade intestinal, contração de brônquios e útero, vasoconstrição e vasodilatação endotélio-dependente, agregação plaquetária, sensibilização de terminações nociceptivas e ação central variável."]}, {"t": "Triptanos e enxaqueca", "sub": ["Os receptores 5-HT1D e 5-HT1B estão em vasos cerebrais e meníngeos, onde causam vasoconstrição. Agonistas seletivos desses receptores reduzem os sintomas da enxaqueca, por vasoconstrição dos vasos cerebrais dilatados.", "Fármacos: sumatriptano, almotriptano, eletriptano, rizatriptano, zolmitriptano, naratriptano e frovatriptano."]}, {"t": "Ondansetrona e procinéticos", "sub": ["Ondansetrona: antiemético que bloqueia os receptores 5-HT3 da zona de gatilho quimiorreceptora. Controla náuseas e vômitos de quimioterapia, radioterapia e pós-operatório.", "Tegaserode e prucaloprida: agonistas parciais de 5-HT4, que estimulam a motilidade do TGI. Usados na constipação crônica e na síndrome do cólon irritável."]}]}, {"titulo": "4. Eicosanoides: a cascata do ácido araquidônico", "pontos": [{"t": "De onde vêm os eicosanoides", "sub": ["Eicosanoides são moléculas de 20 carbonos derivadas de ácidos graxos, como as prostaglandinas, prostaciclinas, tromboxanos e leucotrienos. Controlam inflamação, imunidade e sinalização no SNC.", "A ação catalítica da fosfolipase A₂ (PLA₂) libera o ácido araquidônico da membrana. A PLA₂ depende de fosforilação e de aumento do Ca²⁺. É estimulada por receptores 5-HT2, mGluR1 e receptores de interferons.", "A PLA₂ é inibida pelos corticosteroides, que por isso bloqueiam toda a cascata."]}, {"t": "As duas vias do ácido araquidônico", "sub": ["Via da COX (cicloxigenase): prostaglandinas e tromboxanos.", "Via da LOX (lipoxigenase): leucotrienos, HETE, HPETE e lipoxinas.", "Corticosteroide bloqueia as duas vias, pois inibe a PLA₂. AINE bloqueia só a COX. Por isso os leucotrienos continuam sendo produzidos sob AINE, o que ajuda a explicar broncoespasmo em asmáticos sensíveis ao AAS."]}, {"t": "Isoformas da COX", "sub": ["COX-1, constitutiva: estômago, rim, plaquetas, útero e SNC. Funções: citoproteção gástrica (PGE₂ aumenta o muco e reduz o ácido), agregação plaquetária (TXA₂) e antiagregação (PGI₂), função renal, contração uterina (PGF₂α) e dor e inflamação.", "COX-2, induzida: macrófago, linfócito, neutrófilo e endotélio. Funções: dor e inflamação (PGE₂, PGF₂α, PGI₂, PGD₂). COX-2 também é constitutiva no rim e no SNC, com função renal e transmissão nervosa (PGE₂ e PGD₂)."]}, {"t": "Prostanoides e suas ações", "sub": ["PGD₂ (mastócitos): vasodilatação, inibição da agregação plaquetária e relaxamento do músculo liso do TGI e do útero.", "PGF₂α (miométrio): contração do miométrio, luteólise e broncoconstrição.", "PGI₂ (prostaciclina, endotélio): vasodilatação, hiperalgesia, inibição da agregação plaquetária, liberação de renina e natriurese.", "PGE₂ (pulmão e macrófago): vasodilatação, hiperalgesia, febre e proliferação celular. Também protege a mucosa gástrica.", "TXA₂ (tromboxano, plaquetas): função trombótica, com agregação plaquetária, vasoconstrição e broncoconstrição."]}]}, {"titulo": "5. PAF, cininas e citocinas", "pontos": [{"t": "PAF: fator de ativação plaquetária", "sub": ["PAF é um mediador fosfolipídico potente. Aumenta a adesão celular e ativa as células endoteliais, diretamente ou pela formação de radicais de oxigênio e metabólitos do ácido araquidônico.", "Síntese: a fosfatidilcolina é hidrolisada pela PLA₂, gerando liso-PC. A LPC acetiltransferase (LPCAT) adiciona o grupo acetil e forma o PAF. É de 100 a 1.000 vezes mais potente que a histamina."]}, {"t": "Cininas: bradicinina e calidina", "sub": ["Bradicinina e calidina são peptídeos formados pela ação das calicreínas sobre os cininogênios, que são α-globulinas.", "Receptor B1: estimulado por calidina e, mais, pela bradicinina (é induzível). Antagonista: Des-Arg-Hoe 140.", "Receptor B2: estimulado principalmente pela bradicinina (é constitutivo). Antagonista: Hoe 140.", "Ações: vasodilatação dependente do endotélio (NO), aumento da permeabilidade das vênulas, sensibilização de terminações sensoriais (dor), e contração do músculo liso intestinal e uterino."]}, {"t": "Citocinas", "sub": ["Citocinas são proteínas reguladoras, com ação parácrina e autócrina, que regulam a resposta imune e inflamatória.", "Interleucinas: IL-1, IL-6, IL-8, IL-10 e IL-13. Ativam células inflamatórias.", "Fatores de crescimento: GM-CSF e M-CSF, que ativam o macrófago e as células NK e dendríticas.", "Quimiocinas (CC, CXC, XC, CX3C): quimiotaxia de leucócitos.", "Interferons (IFNα, IFNβ, IFNγ): antiviral e ativação de leucócitos.", "TNF-α: pró-inflamatória. Causa febre, anorexia e choque, tem citotoxicidade e ativa células endoteliais e teciduais.", "As citocinas podem ser pró-inflamatórias ou anti-inflamatórias, e controlam o processo."]}]}, {"titulo": "6. AINEs: mecanismo e efeitos", "pontos": [{"t": "Mecanismo único, três efeitos", "sub": ["O principal mecanismo dos AINEs é inibir a cicloxigenase. Isso reduz a conversão do ácido araquidônico em prostaglandinas nas células inflamatórias.", "Anti-inflamatório: reduz a PGE₂ e a prostaciclina na região lesionada, o que diminui a vasodilatação e, indiretamente, o edema. Não trata a causa da lesão.", "Analgésico: reduz a sensibilização das terminações nociceptivas por PGE₂, bradicinina e 5-HT. O alívio da cefaleia provavelmente resulta de menor vasodilatação mediada por prostaglandinas.", "Antipirético: a IL-1 aumenta a produção de prostaglandinas no hipotálamo e eleva o ponto de controle da temperatura. Os AINEs reduzem a PGE₂ no SNC."]}, {"t": "Aspirina (AAS)", "sub": ["O AAS é o AINE mais antigo. Inativa irreversivelmente a COX-1 e a COX-2, por acetilação.", "Além de analgésico e anti-inflamatório, inibe a agregação plaquetária e é usado nas doenças cardiovasculares.", "Oral, rapidamente absorvido. Cerca de 75% é metabolizado no fígado. Meia-vida de 4 horas.", "Como a plaqueta não sintetiza COX nova, a dose baixa antiagrega durante toda a vida da plaqueta."]}, {"t": "Paracetamol", "sub": ["Principal analgésico de venda livre. Tem efeitos analgésico e antipirético fortes, mas poucos efeitos anti-inflamatórios.", "O perfil peculiar parece decorrer da atuação no SNC. O slide atribui isso a uma 'COX-3'. Correção: a COX-3 descrita foi uma variante de splicing da COX-1 no córtex canino, sem isoforma funcional sequenciada em humanos. O mecanismo aceito hoje é multifatorial: inibição central da COX, favorecida pelo baixo peróxido no SNC, e ação do metabólito AM404 nas vias endocanabinoide e TRPV1. Para a prova, responda o que está no slide, mas saiba a correção.", "Administrado por via oral e metabolizado no fígado, com meia-vida de 2 a 4 horas. Em doses tóxicas, gera NAPQI, que causa lesão hepática potencialmente fatal após 24 a 48 horas."]}, {"t": "Propiônicos, oxicans e coxibes", "sub": ["Derivados do ácido propiônico: analgésicos, antipiréticos e anti-inflamatórios. Usados na dor e na inflamação da artrite gotosa aguda e na dismenorreia primária.", "Oxicans (piroxicam e outros): inibidores não seletivos da COX. Exceção: o meloxicam, com leve preferência pela COX-2 em baixas doses (cerca de 10:1). Têm menos efeito no TGI que o AAS. Usados na artrite reumatoide e na osteoartrite.", "Coxibes (celecoxibe, rofecoxibe): inibidores seletivos da COX-2. Causam menos úlcera péptica, mas têm risco cardiovascular. Contraindicados em hipertensão, insuficiência cardíaca ou distúrbios de coagulação. Usados em tratamentos curtos e no pós-operatório."]}]}, {"titulo": "7. Efeitos colaterais dos AINEs", "pontos": [{"t": "TGI, rim e coração", "sub": ["TGI: efeitos associados à inibição da COX-1 constitutiva, com supressão das prostaglandinas gastroprotetoras. Dispepsia, náuseas, vômitos, danos gastrintestinais e risco de hemorragia, que pode ser fatal.", "Rim: PGE₂ e PGI₂ são produzidas no rim e promovem vasodilatação compensatória contra a noradrenalina e a angiotensina II. Em pacientes com função renal comprometida, os AINEs causam insuficiência renal reversível. O uso contínuo de altas doses pode causar a nefropatia associada a analgésicos, muitas vezes irreversível.", "Coração: uso prolongado, sobretudo de coxibes, pode causar hipertensão e predispor a AVC e infarto, pelo aumento da agregação plaquetária. O desequilíbrio entre COX-1 e COX-2 explica isso: a COX-1 constitutiva causa agregação plaquetária e a COX-2 inibe esse processo. Com coxibes, a COX-2 é inibida e a COX-1 favorece a formação de trombos."]}, {"t": "Outros efeitos", "sub": ["Reações cutâneas, broncoespasmo em asmáticos sensíveis à aspirina, distúrbios hepáticos e depressão da medula óssea."]}]}, {"titulo": "8. Pontos-chave", "pontos": [{"t": "Para revisar antes da prova", "sub": ["A histamina é o mediador da fase imediata; o anti-H1 a bloqueia. A fase tardia é sustentada por citocinas, que exigem corticoide.", "A serotonina atua em 5-HT1D (triptanos) e 5-HT3 (ondansetrona).", "Corticoide bloqueia a PLA₂, que inicia a cascata inteira. AINE bloqueia apenas a COX.", "COX-1 protege o estômago e agrega plaquetas; COX-2 é induzida na inflamação. Coxibes poupam a COX-1 e aumentam o risco trombótico.", "O paracetamol não é anti-inflamatório forte e causa lesão hepática em dose tóxica, pelo NAPQI.", "A dor é sensibilizada por sinergia entre mediadores: a PGE₂ prepara o terreno para a bradicinina."]}]}], "glossario": [{"termo": "Autacoide", "tecnica": "Conceito", "definicao": "Substância natural produzida rapidamente em resposta a estímulos, com ação local.", "slide": 6}, {"termo": "PAF", "tecnica": "Mediador lipídico", "definicao": "Fator ativador plaquetário, mediador fosfolipídico que aumenta a adesão celular, 100 a 1.000 vezes mais potente que a histamina.", "slide": 36}, {"termo": "COX-1 e COX-2", "tecnica": "Cicloxigenases", "definicao": "COX-1 constitutiva (estômago, plaquetas, rim); COX-2 induzida na inflamação; alvo dos AINEs.", "slide": 30}, {"termo": "Coxibes", "tecnica": "AINE seletivo", "definicao": "Inibidores seletivos da COX-2, como celecoxibe e rofecoxibe, com menos efeito gástrico.", "slide": 64}, {"termo": "Nefropatia associada a analgésicos", "tecnica": "Efeito renal", "definicao": "Lesão renal por uso contínuo de altas doses de AINEs, frequentemente irreversível.", "slide": 68}, {"termo": "5-HT3", "tecnica": "Receptor da serotonina", "definicao": "Canal iônico da zona de gatilho; alvo da ondansetrona contra náuseas.", "slide": 22}, {"termo": "Primeiros anti-histamínicos H1 (epônimo: Bovet e Staub)", "tecnica": "Anti-histamínicos H1", "definicao": "Bovet e Staub descreveram os primeiros anti-histamínicos H1, em 1937.", "slide": 13}, {"termo": "Histamina", "tecnica": "Mediador", "definicao": "Amina biogênica vasodilatadora, derivada da histidina. Liberada por mastócitos e basófilos.", "slide": 8}, {"termo": "Receptor H1", "tecnica": "Receptor (Gq)", "definicao": "Broncoconstrição, eritema, edema, prurido e dor. Via Gq e NF-κB.", "slide": 10}, {"termo": "Receptor H2", "tecnica": "Receptor (Gs)", "definicao": "Secreção de ácido gástrico nas células parietais. Via Gs e AMPc.", "slide": 10}, {"termo": "Receptor H3", "tecnica": "Receptor (Gi/o)", "definicao": "Modula neurotransmissão no SNC e vigília. Via Gi/o.", "slide": 10}, {"termo": "Receptor H4", "tecnica": "Receptor (Gi/o)", "definicao": "Presente em células hematopoiéticas e na mucosa gástrica. Eleva Ca²⁺ intracelular.", "slide": 10}, {"termo": "Difenidramina", "tecnica": "Anti-histamínico H1", "definicao": "Agonista inverso do H1, de primeira geração, lipofílico. Causa sedação. Usado em alergia.", "slide": 11}, {"termo": "Anti-histamínicos H1 de primeira e segunda geração", "tecnica": "Anti-histamínico H1", "definicao": "Igualmente eficazes na alergia. A primeira geração é mais lipofílica e sedativa.", "slide": 15}, {"termo": "Cromolina e nedocromil", "tecnica": "Estabilizador de mastócitos", "definicao": "Impedem a desgranulação dos mastócitos. Usados na asma.", "slide": 11}, {"termo": "Cimetidina e ranitidina", "tecnica": "Antagonista H2", "definicao": "Antagonistas seletivos de H2 que reduzem a secreção ácida. Usados na pirose e na doença ulcerosa.", "slide": 16}, {"termo": "Serotonina (5-HT)", "tecnica": "Mediador", "definicao": "Neurotransmissor no cérebro e hormônio local na periferia. Sintetizada do triptofano. Degradada pela MAO.", "slide": 19}, {"termo": "Triptofano hidroxilase e dopa descarboxilase", "tecnica": "Síntese", "definicao": "Enzimas que transformam o triptofano em 5-hidroxitriptofano e depois em serotonina.", "slide": 19}, {"termo": "5-HIAA (ácido 5-hidroxi-indolacético)", "tecnica": "Metabólito", "definicao": "Principal metabólito da serotonina, eliminado na urina.", "slide": 19}, {"termo": "Receptor 5-HT1A", "tecnica": "Receptor (Gi)", "definicao": "Autorreceptor nos núcleos da rafe. Inibe a adenilato ciclase. Agonistas: buspirona e 8-OH-DPAT.", "slide": 21}, {"termo": "Receptores 5-HT1B e 5-HT1D", "tecnica": "Receptor (Gi)", "definicao": "Em vasos cerebrais e meníngeos. Causam vasoconstrição. Alvo dos triptanos.", "slide": 21}, {"termo": "Sumatriptano e triptanos", "tecnica": "Agonista 5-HT1B/1D", "definicao": "Causam vasoconstrição de vasos cerebrais e meníngeos. Usados na enxaqueca.", "slide": 24}, {"termo": "Receptor 5-HT2A", "tecnica": "Receptor (Gq)", "definicao": "Plaquetas, músculo liso e córtex. Ativa a PLC. Antagonistas: cetanserina e risperidona.", "slide": 22}, {"termo": "Receptor 5-HT3", "tecnica": "Canal iônico", "definicao": "Nervos periféricos e área postrema. Canal que excita o neurônio. Antagonista: ondansetrona.", "slide": 22}, {"termo": "Ondansetrona", "tecnica": "Antagonista 5-HT3", "definicao": "Antiemético. Atua na zona de gatilho quimiorreceptora. Usado em quimioterapia e pós-operatório.", "slide": 25}, {"termo": "Receptor 5-HT4", "tecnica": "Receptor (Gs)", "definicao": "Hipocampo e TGI. Estimula a motilidade intestinal. Agonistas: cisaprida e renzaprida.", "slide": 22}, {"termo": "Tegaserode e prucaloprida", "tecnica": "Agonista 5-HT4 parcial", "definicao": "Estimulam a motilidade intestinal. Usados na constipação crônica e na síndrome do cólon irritável.", "slide": 25}, {"termo": "Eicosanoides", "tecnica": "Mediador", "definicao": "Derivados de ácidos graxos de 20 carbonos: prostaglandinas, prostaciclinas, tromboxanos e leucotrienos.", "slide": 27}, {"termo": "Fosfolipase A2 (PLA2)", "tecnica": "Enzima", "definicao": "Libera o ácido araquidônico dos fosfolipídios de membrana. Ativada por Ca²⁺ e fosforilação.", "slide": 28}, {"termo": "Ácido araquidônico", "tecnica": "Precursor", "definicao": "Ácido graxo de 20 carbonos liberado da membrana. Origem das prostaglandinas e leucotrienos.", "slide": 28}, {"termo": "Cicloxigenase (COX)", "tecnica": "Enzima", "definicao": "Converte o ácido araquidônico em prostaglandinas e tromboxanos. Alvo dos AINEs.", "slide": 29}, {"termo": "Lipoxigenase (LOX)", "tecnica": "Enzima", "definicao": "Converte o ácido araquidônico em leucotrienos, HETE, HPETE e lipoxinas.", "slide": 29}, {"termo": "PGE2", "tecnica": "Prostanoide", "definicao": "Vasodilatação, hiperalgesia, febre e proliferação celular. Protege a mucosa gástrica.", "slide": 33}, {"termo": "PGI2 (prostaciclina)", "tecnica": "Prostanoide", "definicao": "Vasodilatação, inibe a agregação plaquetária e causa natriurese. Produzida pelo endotélio.", "slide": 33}, {"termo": "TXA2 (tromboxano A2)", "tecnica": "Prostanoide", "definicao": "Agregação plaquetária, vasoconstrição e broncoconstrição. Produzido nas plaquetas.", "slide": 33}, {"termo": "PGF2α", "tecnica": "Prostanoide", "definicao": "Contrai o miométrio, causa luteólise e broncoconstrição.", "slide": 33}, {"termo": "PGD2", "tecnica": "Prostanoide", "definicao": "Liberada pelos mastócitos. Causa vasodilatação e inibe a agregação plaquetária.", "slide": 33}, {"termo": "LPCAT (lisofosfatidilcolina aciltransferase)", "tecnica": "Enzima", "definicao": "Adiciona o grupo acetil à liso-PC e forma PAF.", "slide": 35}, {"termo": "Cininas (bradicinina e calidina)", "tecnica": "Peptídeos", "definicao": "Formadas por calicreínas a partir dos cininogênios. Causam vasodilatação, permeabilidade e dor.", "slide": 38}, {"termo": "Calicreína e cininogênio", "tecnica": "Enzima e substrato", "definicao": "Calicreína cliva os cininogênios em bradicinina e calidina.", "slide": 38}, {"termo": "Receptor B1 (cinina)", "tecnica": "Receptor", "definicao": "Induzível. Agonista preferencial é a calidina. Antagonista: Des-Arg-Hoe 140.", "slide": 39}, {"termo": "Receptor B2 (cinina)", "tecnica": "Receptor", "definicao": "Constitutivo. Agonista preferencial é a bradicinina. Antagonista: Hoe 140.", "slide": 39}, {"termo": "Hoe 140 e Des-Arg-Hoe 140", "tecnica": "Antagonista de cinina", "definicao": "Antagonistas dos receptores B2 e B1, respectivamente.", "slide": 39}, {"termo": "IL-1, IL-6, IL-8, IL-10 e IL-13", "tecnica": "Interleucinas", "definicao": "Ativam células inflamatórias. IL-1 e IL-6 têm papel pró-inflamatório. IL-10 é anti-inflamatória.", "slide": 42}, {"termo": "TNF-α", "tecnica": "Citocina pró-inflamatória", "definicao": "Causa febre, anorexia, choque e citotoxicidade, e ativa células endoteliais.", "slide": 42}, {"termo": "IFN-α, IFN-β e IFN-γ", "tecnica": "Interferons", "definicao": "Antivirais, e ativam leucócitos. IFN-γ é o principal ativador de macrófagos.", "slide": 42}, {"termo": "GM-CSF e M-CSF", "tecnica": "Fatores de crescimento", "definicao": "Ativam macrófagos e células dendríticas e NK.", "slide": 42}, {"termo": "Quimiocinas (CC, CXC, XC e CX3C)", "tecnica": "Quimiotaxinas", "definicao": "Atraem leucócitos ao local da inflamação.", "slide": 42}, {"termo": "AAS (ácido acetilsalicílico)", "tecnica": "AINE", "definicao": "Inativa COX-1 e COX-2 de modo irreversível, por acetilação. Inibe a agregação plaquetária.", "slide": 60}, {"termo": "Paracetamol", "tecnica": "Analgésico e antipirético", "definicao": "Forte analgésico e antipirético, com pouca ação anti-inflamatória. Atua no SNC, por COX-3. Hepatotóxico em dose alta.", "slide": 61}, {"termo": "Propiônicos", "tecnica": "AINE", "definicao": "Analgésicos, antipiréticos e anti-inflamatórios. Usados na artrite gotosa aguda e na dismenorreia.", "slide": 62}, {"termo": "Oxicans e meloxicam", "tecnica": "AINE", "definicao": "Inibidores quase não seletivos da COX. Meloxicam tem leve preferência pela COX-2, cerca de 10:1.", "slide": 63}, {"termo": "Broncoespasmo por sensibilidade à aspirina", "tecnica": "Efeito adverso", "definicao": "Asmáticos sensíveis à aspirina podem ter broncoespasmo com AINEs.", "slide": 70}, {"termo": "NF-κB", "tecnica": "Via de sinalização", "definicao": "Fator de transcrição que regula a inflamação. Os anti-histamínicos H1 suprimem essa via.", "slide": 14}, {"termo": "Sinais cardinais da inflamação", "tecnica": "Conceito", "definicao": "Calor, rubor, edema (tumor), dor e perda de função.", "slide": 3}], "caso": {"titulo": "Caso: asmático sensível à aspirina com dor", "perfil": "Broncoespasmo por AINE e risco de sangramento por COX-1.", "etapas": [{"titulo": "Etapa 1: broncoespasmo após AINE", "texto": "Mulher de 40 anos, asmática, toma ácido acetilsalicílico para cefaleia e evolui com broncoespasmo e sibilos minutos depois.", "perguntas": [{"pergunta": "Qual é o mecanismo mais provável do broncoespasmo, segundo a aula?", "alts": ["Inibição da COX com desvio do ácido araquidônico para leucotrienos broncoconstritores", "Ativação de receptores H2 brônquicos pela histamina liberada", "Bloqueio de receptores beta-2 pelo ácido acetilsalicílico", "Ativação de receptores 5-HT3 pulmonares pela serotonina", "Inibição da COX-2, que aumenta a produção de PGE2 brônquica"], "erradas": ["Receptores H2 não são o mecanismo do broncoespasmo descrito.", "O ácido acetilsalicílico não atua como bloqueador beta-2.", "Receptores 5-HT3 não são o mecanismo citado para a asma por AINE.", "Inibir COX-2 reduz prostaglandinas, e não aumenta PGE2."], "justificativa": "A aula cita broncoespasmo em asmáticos sensíveis à aspirina entre os efeitos dos AINEs (slide 70). O desvio para leucotrienos é um mecanismo comum da via da lipoxigenase (slide 29)."}]}, {"titulo": "Etapa 2: sangramento em idoso", "texto": "Homem de 72 anos, usando AINE não seletivo por artrose, tem melena e queda de hemoglobina. A endoscopia mostra úlcera gástrica.", "perguntas": [{"pergunta": "Qual é o mecanismo do sangramento, segundo a aula?", "alts": ["Inibição da COX-1, com perda de prostaglandinas gastroprotetoras", "Inibição da COX-2, com excesso de tromboxano na mucosa", "Ativação da histamina H1, com aumento da secreção gástrica", "Bloqueio dos receptores 5-HT4, com redução da motilidade", "Estímulo de PAF, com vasodilatação da submucosa"], "erradas": ["A inibição da COX-2 não é o mecanismo gastrointestinal central, segundo a aula.", "Excesso de tromboxano não é o mecanismo descrito para a úlcera.", "Histamina H1 não é o mecanismo de sangramento pelo AINE.", "Receptores 5-HT4 estimulam a motilidade, e não causam a lesão descrita."], "justificativa": "Os efeitos indesejados no TGI são principalmente pela inibição da COX-1 constitutiva, que suprime as prostaglandinas gastroprotetoras (slide 67)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Paciente J.R., 31 anos, com urticária e prurido em minutos após contato com um alérgeno. O anti-H1 de primeira geração alivia os sintomas, mas o paciente relata sonolência intensa. Qual característica explica a sonolência, e qual alternativa de segunda geração evita esse efeito?", "alternativas": ["Lipofilicidade permite atravessar a barreira hematoencefálica; efeito sedativo", "Hidrofilia impede a absorção e concentra o fármaco no trato digestivo; de segunda geração, a sedação é maior", "Ligação à albumina impede a distribuição ao cérebro; de segunda geração, a sedação ocorre pela via renal", "Ação em H2 gástrico reduz a secreção ácida e causa sonolência por hipocalemia; a segunda geração age em H4", "Ação em H3 hipotalâmico aumenta a vigília e causa insônia; a segunda geração age em H1 periférico apenas"], "gabarito": "A", "justificativa": "Anti-H1 de primeira geração são lipofílicos e atravessam a barreira hematoencefálica, causando sedação. Os de segunda geração têm eficácia equivalente, sem sedação relevante (resumo: Histamina e anti-histamínicos).", "tecnica": "Histamina: fase imediata", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Paciente, A.T., 44 anos, com crise de urticária sustentada por citocinas, não responde ao anti-H1 em dose plena. Qual é a estratégia farmacológica mais coerente, pela lógica da fase tardia?", "alternativas": ["Mais uma dose de anti-H1, porque a histamina é o único mediador da fase tardia da reação alérgica do paciente", "Cromolin em dose alta, porque ele bloqueia citocinas e impede a degranulação já em curso nos tecidos", "Adrenalina em infusão contínua, porque ela bloqueia citocinas e os receptores de histamina H1 do paciente", "Corticosteroide, que inibe a PLA₂ e controla a inflamação de fase tardia", "Ondansetrona, porque o receptor 5-HT3 é o principal mediador da fase tardia da urticária crônica"], "gabarito": "D", "justificativa": "Anti-H1 bloqueia a histamina, que é mediador da fase imediata. Na fase tardia, citocinas sustentam a inflamação, e o corticoide inibe a PLA₂ e a cascata inteira (resumo: Histamina; Eicosanoides).", "tecnica": "Fase tardia e corticoide", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Paciente M.K., 47 anos, com pirose e úlcera duodenal, recebe um antagonista H2. Qual receptor é bloqueado, qual é o efeito sobre o estômago, e por que a estratégia é diferente de um inibidor de bomba?", "alternativas": ["H2 nas células parietais; reduz a secreção ácida induzida pela histamina", "H1 nas células parietais, com aumento da secreção ácida; o inibidor de bomba também bloqueia o H1 gástrico", "H3 no SNC, com redução da vigília e do apetite; o inibidor de bomba age no SNC de forma semelhante", "H4 nas células hematopoéticas, com quimiotaxia; o inibidor de bomba age sobre o H4 do estômago", "H2 nos mastócitos, com degranulação e liberação de triptase; o inibidor de bomba bloqueia a degranulação"], "gabarito": "A", "justificativa": "Antagonistas H2 (cimetidina, ranitidina) bloqueiam o receptor H2 das células parietais e reduzem a secreção ácida. Inibidores de bomba bloqueiam a etapa final da secreção ácida (resumo: Histamina, receptores e antagonistas H2).", "tecnica": "Anti-H2 e pirose", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Mulher de 36 anos, com enxaqueca com aura, recebe sumatriptano. Qual receptor é ativado, e em que tecido o efeito terapêutico ocorre?", "alternativas": ["5-HT3, no canal iônico da zona de gatilho, com vasodilatação cerebral que alivia a dor pulsátil", "5-HT1B e 5-HT1D, em vasos cerebrais e meníngeos, com vasoconstrição que reduz os sintomas", "5-HT4, no hipocampo, com estímulo à motilidade do TGI que alivia a cefaleia da paciente", "5-HT2A, nas plaquetas, com agregação que impede a dilatação dos vasos cerebrais na enxaqueca", "5-HT1A, nos núcleos da rafe, com inibição do ciclo sono-vigília e alívio da cefaleia pulsátil"], "gabarito": "B", "justificativa": "Triptanos são agonistas seletivos de 5-HT1B e 5-HT1D, presentes em vasos cerebrais e meníngeos. A vasoconstrição nesses vasos reduz os sintomas da enxaqueca (resumo: Serotonina e triptanos).", "tecnica": "Serotonina e triptano", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Paciente, C.L., 58 anos, em quimioterapia, apresenta náuseas e vômitos. A equipe prescreve ondansetrona. Qual é o receptor bloqueado, e onde ele está localizado?", "alternativas": ["Receptor 5-HT1D, em vasos cranianos, com vasodilatação que alivia as náuseas e os vômitos do paciente", "Receptor 5-HT4, em hipocampo, com estímulo da motilidade gástrica que previne os vômitos da quimioterapia", "Receptor H2, em células parietais gástricas, com redução da secreção ácida que alivia os vômitos", "Receptor D2, na área postrema, com bloqueio dopaminérgico que reduz a sensação de náusea do paciente", "Receptor 5-HT3, canal iônico da zona de gatilho quimiorreceptora e nervos periféricos"], "gabarito": "E", "justificativa": "Ondansetrona é antagonista de 5-HT3, que está na zona de gatilho quimiorreceptora e em nervos periféricos. É usada na quimioterapia, na radioterapia e no pós-operatório (resumo: Ondansetrona).", "tecnica": "Ondansetrona e quimioterapia", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Paciente A.S., 52 anos, asmático, sensível à aspirina, tem broncoespasmo após tomar um AINE. Qual é o mecanismo, e por que um corticoide não causaria o mesmo efeito?", "alternativas": ["AINE bloqueia a PLA₂ e aumenta a COX; o corticoide bloqueia a LOX e aumenta leucotrienos no pulmão", "AINE ativa o receptor β2 e causa broncoconstrição paradoxal; o corticoide bloqueia o receptor β2 do paciente", "AINE desvia o ácido araquidônico para a LOX; corticoide bloqueia PLA₂ e as duas vias", "AINE aumenta a IgE e ativa mastócitos no brônquio; o corticoide inibe a IgE e impede a degranulação", "AINE bloqueia o receptor H1 e aumenta a histamina; o corticoide inibe a histamina diretamente no mastócito"], "gabarito": "C", "justificativa": "AINEs bloqueiam só a COX, e o ácido araquidônico segue para a LOX, aumentando os leucotrienos. Corticosteroides inibem a PLA₂, bloqueando COX e LOX (resumo: Eicosanoides, duas vias).", "tecnica": "Inibição da COX e LOX", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Paciente, F.G., 62 anos, em uso crônico de AINE para artrite, apresenta dispepsia e hemorragia digestiva. Qual isoforma da COX é inibida e qual prostaglandina gastroprotetora deixa de ser produzida?", "alternativas": ["COX-2 induzida; PGI₂, que aumenta a acidez e causa hemorragia na mucosa gástrica", "COX-1 induzida; TXA₂, que reduz o muco e aumenta a secreção de pepsina no estômago", "COX-2 constitutiva; PGD₂, que causa vasoconstrição e isquemia da mucosa gástrica", "COX-1 constitutiva; PGF₂α, que causa broncoconstrição e contração do esfíncter gástrico", "COX-1 constitutiva; PGE₂, que aumenta o muco e reduz a secreção ácida"], "gabarito": "E", "justificativa": "A COX-1 constitutiva produz PGE₂, que é citoprotetora: aumenta o muco e reduz a secreção ácida. Sua inibição causa dispepsia, úlcera e hemorragia (resumo: AINEs, efeitos gastrointestinais).", "tecnica": "COX-1 e estômago", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Paciente, L.M., 66 anos, com artrose, usa coxibe por longo prazo e tem infarto do miocárdio. Qual é o desequilíbrio de prostaglandinas que explica o risco trombótico?", "alternativas": ["PGI₂ endotelial, pró-agregante e produzida pela COX-1, é preservada; TXA₂ plaquetário é suprimido", "PGI₂ antiagregante, produzida pela COX-2, é suprimida; TXA₂ fica intacto", "PGE₂ renal, antiagregante e produzida pela COX-1, é aumentada; TXA₂ plaquetário é reduzido pelo fármaco", "PGD₂ mastocitária, pró-agregante e produzida pela COX-2, é aumentada; PGF₂α uterina é reduzida", "PGF₂α uterina, antiagregante e produzida pela COX-2, é aumentada; TXA₂ é inibido pelo coxibe"], "gabarito": "B", "justificativa": "Coxibes inibem a COX-2 e poupam a COX-1. Suprimem a PGI₂ antiagregante e deixam o TXA₂ pró-agregante. O desequilíbrio favorece trombose (resumo: Coxibes e risco cardiovascular).", "tecnica": "Coxibe e trombose", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um paciente recebe AAS em dose baixa por longo prazo para prevenção cardiovascular. Por que a dose baixa mantém efeito antiagregante por toda a vida da plaqueta?", "alternativas": ["Porque o AAS é reversível e se acumula no plasma, mantendo a inibição de COX-1 por dias após a dose", "Porque o AAS aumenta a produção de PGI₂ no endotélio, que é antiagregante por longo prazo", "Porque o AAS ativa o receptor P2Y12, que bloqueia a agregação plaquetária de forma reversível e rápida", "Porque a inibição da COX-1 é irreversível por acetilação, e a plaqueta não sintetiza enzima nova", "Porque o AAS inibe a COX-2 de forma seletiva, que é a principal enzima das plaquetas em repouso"], "gabarito": "D", "justificativa": "AAS inativa a COX-1 de forma irreversível, por acetilação. A plaqueta não sintetiza nova enzima, então a dose baixa antiagrega durante toda a vida da plaqueta (resumo: AINEs, aspirina).", "tecnica": "AAS: irreversibilidade", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um aluno afirma que o paracetamol age pela COX-3, como indicado no slide. Qual é a correção mais precisa?", "alternativas": ["A COX-3 é uma isoforma humana funcional sequenciada no fígado, e é a principal alvo dos AINEs", "COX-3 foi variante de splicing da COX-1 em córtex canino; mecanismo multifatorial", "A COX-3 é o nome da enzima que converte histamina em prostaglandina no endotélio humano", "A COX-3 é o receptor do paracetamol na membrana do hepatócito, que ativa a fase II do metabolismo", "A COX-3 é a enzima que converte PGE₂ em tromboxano, e é inibida pelos coxibes em todos os tecidos"], "gabarito": "B", "justificativa": "COX-3 foi descrita como variante de splicing da COX-1 no córtex canino, sem isoforma funcional em humanos. O mecanismo aceito inclui inibição central da COX e o metabólito AM404 (resumo: Paracetamol).", "tecnica": "Paracetamol: mecanismo e correção", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Paciente, B.N., 28 anos, ingeriu grande quantidade de paracetamol há 30 horas e apresenta lesão hepática. Qual metabólito causa a lesão, e por que ele se acumula?", "alternativas": ["Glicuronídeo, produzido na fase II; a glicuronidação aumenta e o conjugado se acumula no fígado", "Sulfato de paracetamol, produzido pela sulfatação; a enzima é inibida pelo CYP3A4 e o sulfato se acumula", "Acetilcolina, produzida pela fase I; o metabólito libera acetilcolina no fígado e causa necrose", "Histamina, produzida pela fase II; a histamina se acumula e causa necrose centrolobular do fígado", "NAPQI, produzido na fase I; a conjugação com glutationa se satura e o metabólito se acumula"], "gabarito": "E", "justificativa": "Em dose tóxica, o paracetamol gera NAPQI, na fase I. Quando a glutationa se esgota, o NAPQI se acumula e lesa o hepatócito, em 24 a 48 horas (resumo: Paracetamol).", "tecnica": "Paracetamol em dose tóxica", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Em um experimento de nervo, a bradicinina isolada não aumenta muito o sinal de dor, e a PGE₂ isolada também não. Mas a bradicinina aplicada após a PGE₂ aumenta a intensidade do sinal. O que esse resultado mostra?", "alternativas": ["A bradicinina é inativa na presença de prostaglandina, e a PGE₂ anula o efeito da cinina no nervo", "A PGE₂ é um AINE natural que bloqueia a bradicinina e reduz a dor, por isso o sinal diminui", "A bradicinina atua somente sobre a COX-2, e a PGE₂ atua somente sobre a COX-1 do nervo", "Os mediadores atuam em sinergia: a prostaglandina sensibiliza o nociceptor para a bradicinina", "A dor depende apenas de histamina, e a bradicinina e a PGE₂ não têm nenhum efeito na transmissão"], "gabarito": "D", "justificativa": "A PGE₂ prepara o nociceptor, e a bradicinina aplicada depois amplifica o sinal. Os mediadores atuam em sinergia na sensibilização da dor (resumo: Dor e mediadores).", "tecnica": "Bradicinina e prostaglandina", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Paciente com infecção bacteriana grave apresenta febre alta, hipotensão e taquicardia. Qual citocina tem papel mais direto na febre e no choque, e qual é o mecanismo de ação pelo qual o AINE alivia a febre?", "alternativas": ["TNF-α, que causa febre, anorexia e choque; o AINE reduz a PGE₂ hipotalâmica induzida pela IL-1", "IFN-γ, que causa febre por ação na medula óssea; o AINE bloqueia a produção de IFN-γ pelo linfócito", "IL-13, que causa febre por ação no endotélio; o AINE bloqueia a IL-13 diretamente no hipotálamo", "IL-10, que causa febre por ação no fígado; o AINE aumenta a IL-10 para reduzir a temperatura", "IL-8, que causa febre por quimiotaxia de neutrófilos; o AINE bloqueia o receptor CXCR1 do paciente"], "gabarito": "A", "justificativa": "TNF-α causa febre, anorexia e choque. A IL-1 eleva a PGE₂ no hipotálamo, aumentando o ponto de controle da temperatura. O AINE reduz essa PGE₂ central (resumo: Citocinas e antipirese).", "tecnica": "Citocinas e febre", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Um estudante quer comparar o PAF com a histamina em potência. Qual é a relação correta, e qual é a origem do PAF?", "alternativas": ["PAF é 10 vezes menos potente que a histamina; é formado a partir da histidina pela histidina descarboxilase", "PAF e histamina têm a mesma potência; ambos são formados a partir do triptofano pela triptofano hidroxilase", "PAF é de 100 a 1.000 vezes mais potente que a histamina; é formado a partir da fosfatidilcolina via liso-PC", "PAF é um eicosanoide da via COX, com potência igual à do tromboxano; é formado a partir da prostaglandina", "PAF é um esteroide com potência semelhante à do cortisol; é formado no fígado a partir do colesterol"], "gabarito": "C", "justificativa": "PAF é um mediador fosfolipídico 100 a 1.000 vezes mais potente que a histamina. Sua síntese parte da fosfatidilcolina, via liso-PC e LPCAT (resumo: PAF, cininas e citocinas).", "tecnica": "Eicosanoides e PAF", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Idoso, paciente J.P., 78 anos, com insuficiência cardíaca e hipovolemia, usa AINE para dor lombar e apresenta piora da função renal. Qual é a explicação farmacológica?", "alternativas": ["O AINE aumenta a produção de noradrenalina no rim, causando vasoconstrição intensa e necrose tubular aguda", "O AINE ativa a COX-2 renal, que produz tromboxano em excesso e obstrui as arteríolas aferentes", "PGE₂ e PGI₂ renais mantêm vasodilatação; o AINE as suprime", "O AINE bloqueia a angiotensina II, reduzindo a filtração glomerular de forma imediata e irreversível", "O AINE aumenta a retenção de sódio por ativação de α2, elevando a pressão na arteríola aferente"], "gabarito": "C", "justificativa": "PGE₂ e PGI₂ renais mantêm a vasodilatação compensatória. Em quem depende dessa compensação, o AINE precipita insuficiência renal, que pode ser reversível (resumo: AINEs, efeitos renais).", "tecnica": "Caso integrado: AINE e insuficiência renal", "slide": null}], "id": "farma-gilmar-06", "titulo": "Aula 6", "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "manobras": [], "imagens": [], "casos_extremos": []};
